\subsection{Signal Model}
Denote the vector collecting the information symbols intended for the $K$ users by $\mathbf{s} = [s_1, \dots, s_K]^T \in \mathbb{C}^{K \times 1}$ with $\mathbb{E} [\mathbf{s} \mathbf{s}^H ] = \mathbf{I}_K$ and the transmit beamformer for the $k$-th user by $\mathbf{w}_k = [w_{1,k}, \dots, w_{M,k}]^T \in \mathbb{C}^{M \times 1}$. The feed signal at the $m$-th waveguide is given by
\begin{align} \label{signal_1}
c_m = \underset{k \in \mathcal{K}}{\sum} w_{m,k} s_k.
\end{align}
% where $w_{m,k}$ denotes the transmit beamforming weights for for the $k$-th user at the $m$-th waveguide. $s_k \sim \mathcal{CN}(0,1)$ is the information symbol for the $k$-th user.
We assume lossless in-waveguide propagation because the in-waveguide attenuation has been shown to be insignificant \cite{10912473}.
After the in-waveguide propagation, the signal transmitted from the $N$ PAs on the $m$-th waveguide is given by $\mathbf{g}_m c_m$, where $\mathbf{g}_m \in \mathbb{C}^{N \times 1}$ denotes the in-waveguide channel vector given by
\begin{align}
\mathbf{g}_m \overset{\triangle}{=} [ \alpha_{m,1} e^{-j\frac{2 \pi}{\lambda_g}\|\mathbf{p}_{m,1} - \mathbf{p}_{m,0} \|}, \dots, \alpha_{m,N} e^{-j\frac{2 \pi}{\lambda_g}\|\mathbf{p}_{m,N} - \mathbf{p}_{m,0} \|}]^T.
\end{align}
Here, $\alpha_{m,n}$ denotes the radiation power ratio at the $(m,n)$-th PA, satisfying $\underset{n \in \mathcal{N}}{\sum} \alpha_{m,n}^2 \leq 1, \hspace{1mm} \forall m \in \mathcal{M}$, where, $\alpha_{m,n}=0$ indicates that the $(m,n)$-th antenna is deactivated.
Constant $\lambda_g = \frac{\lambda_c}{n_{\text{eff}}}$ represents the waveguide wavelength, with $\lambda_c$ denoting the free-space wavelength and $n_{\text{eff}}$ representing the effective refractive index of the waveguide \cite{pozar2012microwave}. 
\begin{remark}
The existing works in PASS design assume fixed radiation powers, which limits the PASS in fully exploiting its capabilities. In this work, we consider PASS design with adjustable radiation power, providing a new degree of freedom (DoF) for system optimization and allowing a more flexible power allocation.
\end{remark}
For the ease of presentation, $\mathbf{g}_m$ is reformulated as
\begin{equation}
    \mathbf{g}_m = \mathbf{G}_m \bm{\alpha}_m,
\end{equation}
where $\mathbf{G}_m \in \mathbb{C}^{N \times N}$ and $\bm{\alpha}_m \in \mathbb{R}^{N \times 1}$ are given by, respectively,
\begin{align}
\mathbf{G}_m &= \mathrm{diag}\big([ e^{-j\frac{2 \pi}{\lambda_g}\|\mathbf{p}_{m,1} - \mathbf{p}_{m,0} \|}, \dots, e^{-j\frac{2 \pi}{\lambda_g}\|\mathbf{p}_{m,N} - \mathbf{p}_{m,0} \|}]\big), \\
\bm{\alpha}_m & = [\alpha_{m,1}, \dots, \alpha_{m,N}]^T.
\end{align}
The received signal at the $k$-th user is given by
\begin{align} \label{received_signal}
y_k = \underset{m \in \mathcal{M}}{\sum} \mathbf{h}_{m,k}^H \mathbf{g}_m c_m + n_k,
\end{align}
where $\mathbf{h}_{m,k} \in \mathbb{C}^{N \times 1}$ is the free-space channel vector between the antennas of the $m$-th waveguide and the $k$-th user, and is given by
\begin{align}
    \mathbf{h}_{m,k} = \left[\frac{\beta e^{-j\frac{2\pi}{\lambda_c} \|\mathbf{p}_{m,1} - \overline{\mathbf{p}}_k \| }}{\|\mathbf{p}_{m,1} - \overline{\mathbf{p}}_k \|}, \dots, \frac{\beta e^{-j\frac{2\pi}{\lambda_c} \|\mathbf{p}_{m,N} - \overline{\mathbf{p}}_k \| }}{\|\mathbf{p}_{m,N} - \overline{\mathbf{p}}_k \|} \right]^H.
\end{align}
Here, $\beta = \frac{\lambda_c}{4 \pi}$ is a constant and $n_k \sim \mathcal{CN}(0,\sigma_k^2)$ denotes the additive white Gaussian noise (AWGN) at the $k$-th user. By defining 
% The free-space channel vector between the $m$-th waveguide and the $k$-th user is given by
% \begin{align}
%     \mathbf{h}_{m,k} = \left[\frac{\beta e^{-j\frac{2\pi}{\lambda_c} \|\mathbf{p}_{m,1} - \overline{\mathbf{p}}_k \| }}{\|\mathbf{p}_{m,1} - \overline{\mathbf{p}}_k \|}, \dots, \frac{\beta e^{-j\frac{2\pi}{\lambda_c} \|\mathbf{p}_{m,N} - \overline{\mathbf{p}}_k \| }}{\|\mathbf{p}_{m,N} - \overline{\mathbf{p}}_k \|} \right]^H,
% \end{align}
% where $\beta = \frac{c}{4 \pi f_c}$ denotes the reference path loss.
% Then the received signal at the $k$-th user is given by
% \begin{align} \label{received_signal}
% y_k &= \underset{m \in \mathcal{M}}{\sum} \mathbf{h}_{m,k}^H \mathbf{g}_m c_m + n_k \notag \\
% & = \mathbf{h}_k^H \mathbf{G} \mathbf{A} \mathbf{c} + n_k,
% \end{align}
% where $n_k \sim \mathcal{CN}(0,\sigma_k^2)$. 
\begin{align}
\mathbf{h}_k & \overset{\triangle}{=} \left[\mathbf{h}_{1,k}^H, \dots, \mathbf{h}_{M,k}^H \right]^H \in \mathbb{C}^{MN \times 1}, \\
\mathbf{G} & \overset{\triangle}{=} \diag \left[ \mathbf{G}_1, \dots, \mathbf{G}_M \right] \in \mathbb{C}^{MN \times MN}, \\
\mathbf{A} & \overset{\triangle}{=} \diag \left[ \bm{\alpha}_1, \dots, \bm{\alpha}_M \right] \in \mathbb{R}^{MN \times M}, \label{A_expression} \\
\mathbf{c} & \overset{\triangle}{=} [c_1, \dots, c_M]^T \in \mathbb{C}^{M \times 1},
\end{align}
the received signal $y_k$ can be rewritten compactly as
\begin{align}
y_k & = \mathbf{h}_k^H \mathbf{G} \mathbf{A} \mathbf{c} + n_k \notag \\
& = \underbrace{\mathbf{h}_k^H\mathbf{G} \mathbf{A} \mathbf{w}_k s_k}_{\text{Desired signal}} + \underbrace{\underset{k' \in \mathcal{K}\setminus \{k\}}{\sum} \mathbf{h}_k^H\mathbf{G} \mathbf{A} \mathbf{w}_{k'} s_{k'}}_{\text{Multi-user interference}} + n_k.
\end{align}
As a result, the SINR at the $k$-th user is given by
\begin{align}
\gamma_k = \frac{\left| \mathbf{h}_k^H\mathbf{G} \mathbf{A} \mathbf{w}_k \right|^2}{ \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \mathbf{h}_k^H\mathbf{G} \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2}.
\end{align}
