\subsection{Sub-problem for Updating $\mathbf{t}_k$}
By fixing the other optimization variables, the auxiliary variable $\mathbf{t}_k$ is updated by solving
\begin{align} \label{t_lag}
\underset{\substack{ \mathbf{t}_k }}{\mino} \frac{\rho_2}{2} \hspace{-1mm} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k \hspace{-1mm} - \hspace{-1mm} \mathbf{u}_k \hspace{-1mm} + \hspace{-1mm} \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2 \hspace{-1mm} + \hspace{-1mm} \mathbb{I}_{\mathcal{F}}(\mathbf{w}_k, \bm{\alpha}_m, \mathbf{X},  \mathbf{t}_k),
\end{align}
which can be equivalently rewritten as follows
\begin{align} \label{t_k}
\underset{\substack{ \mathbf{t}_k }}{\mino} \hspace*{3mm} & \frac{\rho_2}{2} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k + \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2 \notag\\
\subto\hspace*{2mm} & \overline{\mbox{C1}} \mbox{:} \hspace{1mm} \gamma_k \geq \Gamma_k, \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
Different from the problem with respect to $\mathbf{w}_k$ in \eqref{block_W}, a phase rotation of $\mathbf{t}_k$ has an impact on the objective function value. As a result, the transformation used in \eqref{socp} cannot be applied to problem \eqref{t_k}. Instead, we first rewrite $\overline{\mbox{C1}}$ equivalently as
\begin{align} \label{c1_}
\hspace{-2mm}\overline{\mbox{C1}} \mbox{:} \hspace{1mm} \Gamma_k  \hspace{-1mm} \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum} \hspace{-1mm} \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 - \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right|^2  + \sigma_k^2 \Gamma_k \leq 0, \hspace{1mm} \forall k,
\end{align}
where the left-hand side of the inequality is a difference of convex (d.c.) functions with respect to $\mathbf{t}_k$ which can be effectively tackled by SCA. Specifically, we construct an upper-bound on the non-convex term $-\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right|^2$ by employing its first-order Taylor expansion. 
% with respect to $\mathbf{t}_k$ as follows
% \begin{align} \label{first_taylor}
% - \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right|^2 \leq & - 2 \Re\left\{ \left(\mathbf{t}^{(i-1)}_k\right)^H \mathbf{A} \mathbf{w}_k \mathbf{w}_k^H \mathbf{A}^H \mathbf{t}_k \right\} \notag \\
% & + \left| \left(\mathbf{t}^{(i-1)}_k\right)^H \mathbf{A} \mathbf{w}_k \right|^2,
% \end{align}
Constraint $\overline{\mbox{C1}}$ is transformed into
\begin{align}
\myoverline{\mbox{C1}} \mbox{:} \hspace{1mm} & \Gamma_k \hspace{-1mm} \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum} \hspace{-1mm} \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 -2 \Re\left\{ \left(\mathbf{t}^{(i-1)}_k\right)^H \mathbf{A} \mathbf{w}_k \mathbf{w}_k^H \mathbf{A}^H \mathbf{t}_k \right\} \notag \\
& + \left| \left(\mathbf{t}^{(i-1)}_k\right)^H \mathbf{A} \mathbf{w}_k \right|^2 + \sigma_k^2 \Gamma_k \leq 0, \hspace{1mm} \forall k \in \mathcal{K},
\end{align}
where $\mathbf{t}^{(i-1)}_k$ denotes the solution of $\mathbf{t}_k$ obtained in the previous iteration.
As a result, problem \eqref{t_k} is replaced by the following approximated optimization problem 
\begin{align} \label{sca}
\underset{\substack{ \mathbf{t}_k }}{\mino} \hspace*{3mm} & \frac{\rho_2}{2} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k + \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2 \notag\\
\subto\hspace*{2mm} & \myoverline{\mbox{C1}},
\end{align}
which is convex and can be solved efficiently.
