\subsection{Sub-problem for Updating $\bm{\alpha}_m$}
By fixing the other optimization variables, the antenna radiation power ratios $\bm{\alpha}_m$ are updated by solving
\begin{align}
\underset{\substack{ \bm{\alpha}_m }}{\mino} \hspace*{3mm} \mathbb{I}_{\mathcal{F}}(\mathbf{w}_k, \bm{\alpha}_m, \mathbf{X},  \mathbf{t}_k),
\end{align}
which is equivalent to the following feasibility check problem
\begin{align} \label{alpha_feasibility_continuous}
\underset{\substack{ }}{\mathrm{Find}} \hspace*{3mm} & \bm{\alpha}_m   \notag\\
\subto\hspace*{3mm} & \overline{\mbox{C1}}, \mbox{C2}.
\end{align}
To accelerate the convergence and to provide more DoFs for energy minimization in other sub-problems, we update $\bm{\alpha}_m$ by maximizing the SINR among users \cite{10364735}, which leads to the following problem
\begin{align} \label{alpha_1}
\underset{\substack{ \bm{\alpha}_m }}{\maxo} \hspace*{3mm} & \underset{k \in \mathcal{K}}{\sum} \frac{\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right|^2}{ \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2} \notag\\
\subto\hspace*{2mm} & \mbox{C2:} \hspace{1mm}  \left\| \bm{\alpha}_m \right\|^2_2 \leq 1, \hspace{1mm} \forall m \in \mathcal{M},
\end{align}
where the non-convexity is caused by the fractional expression. To deal with this issue, fractional programming is exploited. By introducing auxiliary variable $\mathbf{q} = [q_1, \dots, q_K]^T \in \mathbb{R}^{K \times 1}$, problem \eqref{alpha_1} is then equivalently transformed into \cite{8314727}
\begin{align} \label{fp}
\underset{\substack{ \bm{\alpha}_m, \mathbf{q} }}{\maxo} \hspace*{3mm} & f_2 \overset{\triangle}{=} \underset{k \in \mathcal{K}}{\sum} \Bigg( 2 q_k \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right| \notag \\
& - q_k^2 \bigg( \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2 \bigg) \Bigg) \notag\\
\subto\hspace*{3mm} & \mbox{C2:} \hspace{1mm}  \left\| \bm{\alpha}_m \right\|^2_2 \leq 1, \hspace{1mm} \forall m \in \mathcal{M}.
\end{align}
For given $\bm{\alpha}_m$, the optimal $\mathbf{q}$ is obtained from $\frac{\partial f_2}{\partial q_k} = 0, \forall k \in \mathcal{K}$, given by
\begin{align} \label{cal_q_1}
q_k = \frac{\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right| }{\underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2}, \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
Next, we solve problem \eqref{fp} for given $\mathbf{q}$. To begin with, we introduce auxiliary variable $\bm{\psi} \in \mathbb{R}^{K \times 1}$ whose the $k$-th element is $\psi_k$ and the following constraint
\begin{align}
\mbox{C9:} \hspace{1mm} \left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \right| \geq \psi_k, \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
The resulting objective function is then expressed as
\begin{align}
\overline{f}_2 \overset{\triangle}{=} \underset{k \in \mathcal{K}}{\sum} \left( 2 q_k \psi_k - q_k^2 \left( \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \mathbf{t}_k^H \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2 \right) \right).
\end{align}
Note that constraint C9 is non-convex with respect to $\bm{\alpha}_m$. To handle this,
we first equivalently transform C9 into 
\begin{align}
\mbox{C9:} \hspace{1mm} \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \mathbf{w}_k^H \mathbf{A}^T \mathbf{t}_k \geq \psi_k^2,  \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
By constructing a lower bound on the term $\mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \mathbf{w}_k^H \mathbf{A}^T \mathbf{t}_k$, 
% , given by
% \begin{align}
% & \mathbf{t}_k^H \mathbf{A} \mathbf{w}_k \mathbf{w}_k^H \mathbf{A}^T \mathbf{t}_k \geq - \mathrm{Tr} \left( \mathbf{T}_k \mathbf{A}^{(i-1)} \mathbf{W}_k \left(\mathbf{A}^{(i-1)}\right)^T \right) \notag \\
% & \hspace{5mm} + \mathrm{Tr}\left( \left( \mathbf{T}_k \mathbf{A}^{(i-1)} \mathbf{W}_k + \mathbf{T}_k^T \mathbf{A}^{(i-1)} \mathbf{W}_k^T \right)^T \mathbf{A} \right),
% \end{align}
constraint C9 can be rewritten as
\begin{align}
& \overline{\mbox{C9}} \mbox{:} \hspace{1mm} \mathrm{Tr}\left( \left( \mathbf{T}_k \mathbf{A}^{(i-1)} \mathbf{W}_k + \mathbf{T}_k^T \mathbf{A}^{(i-1)} \mathbf{W}_k^T \right)^T \mathbf{A} \right) \notag \\
& - \mathrm{Tr} \left( \mathbf{T}_k \mathbf{A}^{(i-1)} \mathbf{W}_k \left(\mathbf{A}^{(i-1)}\right)^T \right) - \psi_k^2 \geq 0, \hspace{1mm} \forall k \in \mathcal{K},
\end{align}
where $\mathbf{T}_k \overset{\triangle}{=} \mathbf{t}_k \mathbf{t}_k^H$, $\mathbf{W}_k \overset{\triangle}{=} \mathbf{w}_k \mathbf{w}_k^H$. $\mathbf{A}^{(i-1)}$ is the solution obtained in the previous iteration. 
With $\mathbf{q}$ obtained from \eqref{cal_q_1}, optimization problem \eqref{fp} for solving $\bm{\alpha}_m$ is then transformed into
\begin{align} \label{prob_alpha_2}
\underset{\substack{ \bm{\alpha}_m, \bm{\psi} }}{\maxo} \hspace*{3mm} & \overline{f}_2 \notag\\
\subto\hspace*{3mm} & \mbox{C2}, \overline{\mbox{C9}},
\end{align}
which is convex and can be solved efficiently.
