\subsection{Sub-problem for Updating $\bm{\theta}$}
The auxiliary variable $\bm{\theta}$ is updated by solving
\begin{align} \label{prob_theta}
\underset{\substack{ \bm{\theta} }}{\mino} \hspace*{1mm} & f_3 \overset{\triangle}{=} \frac{\rho_1}{2} \left\| \bm{\theta} - \bm{\phi} + \frac{\bm{\mu}}{\rho_1} \right\|^2_2\hspace*{-2mm}+ \frac{\rho_2}{2} \hspace*{-1mm} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k \hspace*{-1mm} - \hspace*{-1mm} \mathbf{u}_k  \hspace*{-1mm} + \hspace*{-1mm} \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2.
\end{align}
Here, the non-convexity comes from the second term, which can be explicitly expressed as $\frac{\rho_2}{2} \underset{\substack{k, m, n}}{\sum} v_{k,m,n}(\theta_{k,m,n})$, where $v_{k,m,n}(\theta_{k,m,n})$ is defined as
\begin{equation}
v_{k,m,n}(\theta_{k,m,n})\overset{\triangle}{=} \left| r_{k,m,n} t_{k,m,n} \hspace{-0.5mm} - \hspace{-0.5mm} \beta e^{j \theta_{k,m,n}} \hspace{-0.5mm} + \hspace{-0.5mm} \frac{\lambda_{k,m,n}}{\rho_2} \right|^2.
\end{equation}
The variable $\lambda_{k,m,n}$ is the $((m-1)N + n)$-th element of $\bm{\lambda}_k$. We note that the variable $\theta_{k,m,n}$ is involved in the exponential term, which is neither convex nor concave. To handle this challenge, we construct an upper-bound on $v_{k,m,n}(\theta_{k,m,n})$ based on the following lemma \cite{7547360, xu2025joint}.
\begin{lemma}
\textit{(Descent Lemma \cite{bertsekas1997nonlinear})}: Let $f: \mathbb{R}^n \rightarrow \mathbb{R}$ be a continuously differentiable function with a Lipschitz continuous gradient on $\mathcal{X} \in \mathbb{R}^n$ with Lipschitz constant $L$. Then, for all $\mathbf{x}, \mathbf{y} \in \mathcal{X}$, we have
\begin{align}
f(\mathbf{x}) \leq f(\mathbf{y}) + \nabla f(\mathbf{y})^T(\mathbf{x} - \mathbf{y}) + \frac{L}{2} \| \mathbf{x} - \mathbf{y} \|^2_2.
\end{align}
\end{lemma}

\begin{Prop}
$v_{k,m,n}(\theta_{k,m,n})$ has a Lipschitz continuous gradient on $\mathbb{R}$ with the Lipschitz constant $L_{k,m,n}$ given by
\begin{align}
L_{k,m,n} = 2 \beta \left|r_{k,m,n} t_{k,m,n} + \frac{\lambda_{k,m,n}}{\rho_2} \right|.
\end{align}
\end{Prop}
\textit{Proof:} Please refer to the Appendix.
\QED
\par
Based on Proposition 1, an upper-bound on $v_{k,m,n}(\theta_{k,m,n})$ is constructed as follows
\begin{align}
& v_{k,m,n}(\theta_{k,m,n}) \notag \\
& \leq v_{k,m,n}\left(\theta_{k,m,n}^{(i-1)}\right) + \nabla_{\theta} v_{k,m,n}\left(\theta_{k,m,n}^{(i-1)}\right) \left(\theta_{k,m,n}- \theta_{k,m,n}^{(i-1)}\right) \notag \\
& \hspace{4mm} + \frac{L_{k,m,n}}{2} \left( \theta_{k,m,n}- \theta_{k,m,n}^{(i-1)} \right)^2 \notag \\
& \overset{\triangle}{=} \widetilde{v}_{k,m,n}(\theta_{k,m,n}),
\end{align}
where 
\begin{align}
&\nabla_{\theta} v_{k,m,n}\left(\theta_{k,m,n}^{(i-1)}\right) = 2 \beta \left|r_{k,m,n} t_{k,m,n} + \frac{\lambda_{k,m,n}}{\rho_2} \right| \notag \\ \times 
& \sin \left( \theta_{k,m,n}^{(i-1)} - \angle \left( r_{k,m,n}t_{k,m,n}+ \frac{\lambda_{k,m,n}}{\rho_2} \right) \right).
\end{align}
Here, $\theta_{k,m,n}^{(i-1)}$ denotes the solution of $\theta_{k,m,n}$ obtained in the previous iteration.
As a result, the second-order surrogate function of objective function $f_3$ in \eqref{prob_theta} is given by
\begin{align}
f_3 & \leq \hspace*{-1.5mm}\underset{\substack{k, m, n}}{\sum}\hspace*{-2mm}\left( \hspace*{-1mm} \frac{\rho_1}{2} \hspace*{-1mm} \left( \theta_{k,m,n}\hspace*{-0.5mm}-\hspace*{-0.5mm} \phi_{k,m,n}\hspace*{-0.5mm}+\hspace*{-0.5mm}\frac{\mu_{k,m,n}}{\rho_1} \right)^2 \hspace*{-2mm}+ \hspace*{-1mm}\frac{\rho_2}{2} \widetilde{v}_{k,m,n}(\theta_{k,m,n}) \hspace*{-1mm} \right) \notag \\
& \overset{\triangle}{=} \widetilde{f}_3,
\end{align}
where $\mu_{k,m,n}$ denotes the $((k-1)MN + (m-1)N + n)$-th element of $\bm{\mu}$.
Problem \eqref{prob_theta} is transformed into
\begin{align} \label{theta_2}
\underset{\substack{ \bm{\theta} }}{\mino} \hspace*{3mm} & \widetilde{f}_3,
\end{align}
which has the closed-form solution given by \eqref{opt_theta}, shown at the bottom of the page.
