\subsection{Sub-problem for Updating $\mathbf{X}$}
The antenna positions $\mathbf{X}$ are updated by solving
\begin{align} \label{x_prob}
\underset{\substack{ \mathbf{X} }}{\mino} \hspace*{3mm} & \frac{1}{T_1 + T_2} \underset{\substack{m, n}}{\sum} E_{m,n} + \mathbb{I}_{\mathcal{F}}(\mathbf{w}_k, \bm{\alpha}_m, \mathbf{X},  \mathbf{t}_k) \notag \\ & \hspace{-15mm} + \frac{\rho_1}{2} \left\| \bm{\theta} - \bm{\phi} + \frac{\bm{\mu}}{\rho_1} \right\|^2_2  + \frac{\rho_2}{2} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k + \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2,
\end{align}
which is equivalent to
\begin{align} \label{optimize_X}
\underset{\substack{ \mathbf{X} }}{\mino} \hspace*{3mm} & f_4 \overset{\triangle}{=} \frac{1}{T_1 + T_2} \underset{\substack{m, n}}{\sum} E_{m,n} + \frac{\rho_1}{2} \left\| \bm{\theta} - \bm{\phi} + \frac{\bm{\mu}}{\rho_1} \right\|^2_2 \notag \\
&  \hspace{8mm}  + \frac{\rho_2}{2} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k + \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2\notag\\
\subto\hspace*{2mm} & \mbox{C3-C5}.
\end{align}
By substituting the locations of the antennas and users, the objective function is formulated as
\begin{align} \label{f_4}
& f_4 = \frac{P}{(T_1 + T_2)v} \underset{\substack{m, n}}{\sum} |x_{m,n} - x'_{m,n}| \notag \\
& + \frac{\rho_1}{2} \underset{\substack{k, m, n}}{\sum} \left( \theta_{k,m,n} - \frac{2 \pi}{\lambda_c} ( r_{k,m,n}+n_{\text{eff}}x_{m,n}) + \frac{\mu_{k,m,n}}{\rho_1} \right)^2 \notag \\
& + \frac{\rho_2}{2} \underset{\substack{k, m, n}}{\sum} \left| r_{k,m,n} t_{k,m,n} - \beta e^{j\theta_{k,m,n}} + \frac{\lambda_{k,m,n}}{\rho_2} \right|^2.
\end{align}
\par
% To deal with the first term, we introduce auxiliary variables $\omega_{m,n} \geq 0, \hspace{1mm} \forall m \in \mathcal{M}, \forall n \in \mathcal{N}$ and constraints 
% \begin{align}
% \mbox{C9:} \hspace{1mm} | x_{m,n} - x'_{m,n} | \leq \omega_{m,n}, \hspace{1mm} \forall m \in \mathcal{M}, \hspace{1mm}\forall n \in \mathcal{N},
% \end{align}
% which can be further reformulated as the following two convex constraints
% \begin{align}
% & \mbox{C9a:} \hspace{1mm} x_{m,n} - x'_{m,n} \leq \omega_{m,n}, \hspace{1mm} \forall m \in \mathcal{M}, \hspace{1mm}\forall n \in \mathcal{N}, \\
% & \mbox{C9b:} \hspace{1mm} x_{m,n} - x'_{m,n} \geq -\omega_{m,n}, \hspace{1mm} \forall m \in \mathcal{M}, \hspace{1mm}\forall n \in \mathcal{N}.
% \end{align}
% \par
% Accordingly, constraint C5 can be formulated as
% \begin{align}
% \overline{\mbox{C5}} \mbox{:} \hspace{1mm} \omega_{m,n} \leq vT_1, \hspace{1mm} \forall m \in \mathcal{M}, \hspace{1mm}\forall n \in \mathcal{N}.  
% \end{align}
% The objective function $f_4$ is accordingly transformed into
% \begin{align}
% f_4 = \frac{P}{(T_1 + T_2)v} \underset{\substack{m, n}}{\sum} \omega_{m,n} + \frac{\rho}{2} \underset{\substack{k, m, n}}{\sum} | r_{k,m,n} t_{k,m,n} - \beta e^{j\frac{2\pi}{\lambda_c}(r_{k,m,n}+n_{\text{eff}}x_{m,n})} + \frac{\lambda_{k,m,n}}{\rho_2}|^2.
% \end{align}
\par
Here, the non-convexity of the objective function comes from the last two terms. To deal with the second term, we introduce auxiliary variables $\xi_{k,m,n} \geq 0, \hspace{1mm} \forall k, \forall m, \forall n$, and the following constraint
\begin{align}
\mbox{C10:} \hspace{1mm} & \left| \theta_{k,m,n} - \frac{2 \pi}{\lambda_c} (r_{k,m,n}+n_{\text{eff}}x_{m,n}) + \frac{\mu_{k,m,n}}{\rho_1} \right| \leq \xi_{k,m,n}, \notag \\
 & \forall k, \forall m, \forall n,
\end{align}
which is equivalent to
\begin{align}
& \mbox{C10a:} \hspace{1mm} \theta_{k,m,n} - \frac{2 \pi}{\lambda_c} (r_{k,m,n}+n_{\text{eff}}x_{m,n}) + \frac{\mu_{k,m,n}}{\rho_1} \geq -\xi_{k,m,n}, \notag \\ 
& \hspace{10mm} \forall k \in \mathcal{K}, \forall m \in \mathcal{M}, \forall n \in \mathcal{N}, \\
& \mbox{C10b:} \hspace{1mm} \theta_{k,m,n} - \frac{2 \pi}{\lambda_c} (r_{k,m,n}+n_{\text{eff}}x_{m,n}) + \frac{\mu_{k,m,n}}{\rho_1} \leq \xi_{k,m,n}, \notag \\
& \hspace{10mm} \forall k \in \mathcal{K}, \forall m \in \mathcal{M}, \forall n \in \mathcal{N},
\end{align}
where constraint C10a is convex but C10b is non-convex due to the term $r_{k,m,n}$. To tackle this issue, we construct a lower bound with respect to $r_{k,m,n}$, which is given by
\begin{align} \label{linear_r}
r_{k,m,n} & \geq r_{k,m,n}^{(i-1)} + \frac{x_{m,n}^{(i-1)} - \overline{x}_k}{r_{k,m,n}^{(i-1)}} \left( x_{m,n} - x_{m,n}^{(i-1)} \right) \notag \\
& \overset{\triangle}{=} \widetilde{r}_{k,m,n},
\end{align}
where $r_{k,m,n}^{(i-1)}$ denotes the value of $r_{k,m,n}$ evaluated using $x_{m,n}^{(i-1)}$ obtained in the previous iteration. Constraint C10b is then transformed into
\begin{align}
\overline{\mbox{C10b}} \mbox{:} \hspace{1mm} & \frac{2 \pi}{\lambda_c} (\widetilde{r}_{k,m,n}+n_{\text{eff}}x_{m,n}) +\xi_{k,m,n}\geq \theta_{k,m,n} + \frac{\mu_{k,m,n}}{\rho_1}, \notag \\
& \forall k, \forall m, \forall n.
\end{align}
\par
Next, we handle the term $\frac{\rho_2}{2} \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k + \frac{\bm{\lambda}_k}{\rho_2} \right\|^2_2$ in objective function $f_4$ in \eqref{optimize_X}. To begin with, we define $\eta_{k,m,n}(x_{m,n}) \overset{\triangle}{=} \left| r_{k,m,n} t_{k,m,n} - \beta e^{j\theta_{k,m,n}} + \frac{\lambda_{k,m,n}}{\rho_2} \right|^2 $, which can be expanded as
\begin{align}
\eta_{k,m,n} = & |t_{k,m,n}|^2 r_{k,m,n}^2 + \left| \frac{\lambda_{k,m,n}}{\rho_2} - \beta e^{j \theta_{k,m,n}} \right|^2 \notag \\
& \hspace{-3mm} + 2 \left| \frac{\lambda_{k,m,n}}{\rho_2} - \beta e^{j \theta_{k,m,n}} \right| |t_{k,m,n}| \cos\left( \vartheta_{k,m,n} \right) r_{k,m,n},
\end{align}
where $\vartheta_{k,m,n} \overset{\triangle}{=} \angle t_{k,m,n} - \angle\left( \frac{\lambda_{k,m,n}}{\rho_2} - \beta e^{j\theta_{k,m,n}} \right)$. The convexity of $\eta_{k,m,n}$ depends on the value of $\cos\left( \vartheta_{k,m,n} \right)$. Specifically, $\eta_{k,m,n}$ is convex if $\cos\left( \vartheta_{k,m,n} \right) \geq 0$. Otherwise, $\eta_{k,m,n}$ is non-convex and is in the form of a d.c. function. For handling the non-convex case of $\vartheta_{k,m,n}$, we linearize $r_{k,m,n}$ by $\widetilde{r}_{k,m,n}$ as in \eqref{linear_r}, leading to a convex upper bound on $\eta_{k,m,n}$, denoted by $\widetilde{\eta}_{k,m,n}$. As a result, the surrogate function of the term $\left| r_{k,m,n} t_{k,m,n} - \beta e^{j\theta_{k,m,n}} + \frac{\lambda_{k,m,n}}{\rho_2} \right|^2$ is obtained as
\begin{align}
\overline{\eta}_{k,m,n} = 
\begin{cases}
    \eta_{k,m,n}, \hspace{2mm} \cos\left( \vartheta_{k,m,n} \right) \geq 0, \\
    \widetilde{\eta}_{k,m,n}, \hspace{2mm} \text{otherwise}.
\end{cases}
\end{align}
We note that the term $\vartheta_{k,m,n}$ is a constant when optimizing $\mathbf{X}$, hence the expression for $\overline{\eta}_{k,m,n}$ is known before solving problem \eqref{optimize_X}.
The objective function is now formulated as follows
\begin{align}
\overline{f}_4 = & \frac{P}{(T_1 + T_2)v} \hspace*{-1mm} \underset{\substack{m, n}}{\sum} |x_{m,n} \hspace*{-1mm} - \hspace*{-1mm} x'_{m,n}| \hspace*{-1mm} + \hspace*{-3mm} \underset{\substack{k, m, n}}{\sum} \hspace*{-2mm} \left( \frac{\rho_1}{2} \xi_{k,m,n}^2 \hspace*{-1mm} + \hspace*{-1mm} \frac{\rho_2}{2} \overline{\eta}_{k,m,n} \right).
\end{align}
Thus, optimization problem \eqref{optimize_X} is transformed into
\begin{align} \label{prob_x_2}
\underset{\substack{ \mathbf{X}, \bm{\xi} }}{\mino} \hspace*{4mm} & \overline{f}_4 \notag\\
\subto\hspace*{2mm} & \mbox{C3-C5}, \mbox{C10a}, \overline{\mbox{C10b}},
\end{align}
which is a convex optimization problem and can be solved efficiently. 
\par
The ADMM-based algorithm for solving problem \eqref{continuous} for continuous antenna movement is summarized in $\textbf{Algorithm 1}$, where we set the scaling factor $\epsilon > 1$ to gradually enlarge the penalty parameters to speed up the elimination of constraint violations. and force the equality constraints to be satisfied. $f_1^{(i)}$ denotes the value of $f_1$ obtained in the $i$-th iteration. The convergence and computational complexity of Algorithm 1 are discussed in the following.
\par
% \textit{i) Convergence:} 
The objective function values of problems \eqref{sca}, \eqref{theta_2}, \eqref{prob_x_2} serve as upper bounds on the objective function values of problems \eqref{t_lag}, \eqref{prob_theta}, \eqref{x_prob}, respectively. For any fixed penalty parameters, these upper bounds are monotonically tightened by alternatingly solving \eqref{sca}, \eqref{theta_2}, and \eqref{prob_x_2} for updating $\mathbf{t}_k$, $\bm{\theta}$, and $\mathbf{X}$, respectively. Together by alternatingly solving \eqref{socp} and \eqref{prob_alpha_2} for updating $\mathbf{w}_k$ and $\bm{\alpha}_m$, the augmented Lagrangian function $\mathcal{L}(\mathbf{w}_k,\bm{\alpha}_m,\mathbf{X}, \bm{\theta}, \mathbf{t}_k, \bm{\mu}, \bm{\lambda}_k)$ is non-increasing and the corresponding solution is guaranteed to converge to a stationary point of problem \eqref{continuous} \cite{boyd2011distributed}.
% 
% According to \cite{boyd2011distributed}, Algorithm 1 is guaranteed to converge to a stationary point of problem \eqref{continuous}.
% 
% $\left\{ \mathbf{w}_k^{(i)}, \mathbf{t}_k^{(i)}, \bm{\alpha}_m^{(i)}, \bm{\theta}^{(i)}, \mathbf{X}^{(i)} \right\}$
% 
The computational complexity of Algorithm 1 is dominated by updating variables $\mathbf{t}_k$, $\bm{\alpha}_m$, and $\mathbf{X}$. Updating $\mathbf{t}_k$ involves solving a quadratic constrained quadratic programming
(QCQP) problem \eqref{sca} with complexity given by $B_1 = \mathcal{O}(M^3N^3K^{3.5} + MNK^{4.5})$ \cite{ben2001lectures}. Updating $\bm{\alpha}_m$ requires solving the QCQP \eqref{prob_alpha_2} with complexity given by $B_2 = \mathcal{O}((K+M)^{0.5}M^3N^3 + ((K+M)^{0.5}MNK))$. Updating $\mathbf{X}$ requires solving SOCP problem \eqref{prob_x_2} with complexity given by $B_3 = \mathcal{O}(K^{0.5}M^{3.5}N^{3.5} + K^{1.5}M^{2.5}N^{2.5})$. As a result, the overall complexity of Algorithm 1 is given by $B_1 + B_2 + B_3$.

% The complexity for updating $\mathbf{w}_k$ by solving \eqref{socp} is given by $\mathcal{O}(M^3K^{3.5} + MK^{4.5})$, the complexity for updating $\mathbf{t}_k$ by solving \eqref{sca} is given by $\mathcal{O}(M^3N^3K^{3.5} + MNK^{4.5})$, the complexity for updating $\bm{\alpha}_m$ by solving \eqref{prob_alpha_2} is given by $\mathcal{O}((MN+K)^{1.5}M^2N^2)$, the complexity for updating $\bm{\theta}$ by solving \eqref{opt_theta} is given by $\mathcal{O}(KMN)$, the complexity for updating  $\mathbf{X}$ by solving \eqref{prob_x_2} is given by $\mathcal{O}(K^{0.5}M^{3.5}N^{3.5} + K^{1.5}M^{2.5}N^{2.5})$


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{algorithm}[t]
\caption{ADMM-based Algorithm for Solving Problem \eqref{continuous} for Continuous Antenna Movement}
\begin{algorithmic}[1]
\small
\STATE Set iteration index $i=1$, scaling factor for the penalty parameters $\epsilon > 1$, error tolerances $\varsigma_1$ and $\varsigma_2$. Initialize $\mathbf{X}^{(1)}$ within the maximum movement distance; initialize $\bm{\theta}^{(1)}$ and $\mathbf{t}^{(1)}$ according to \eqref{C6} and \eqref{vectort_k}, respectively; initialize $\alpha_{m,n}^{(1)} = \frac{1}{\sqrt{N}}$
\REPEAT
\STATE Update $\mathbf{w}_k$ by solving problem \eqref{socp}
\STATE Update $\mathbf{t}_k$ by solving problem \eqref{sca}
\STATE Update $\bm{\alpha}_m$ by solving problem \eqref{prob_alpha_2}
\STATE Update $\bm{\theta}$ by \eqref{opt_theta}
\STATE Update $\mathbf{X}$ by solving problem \eqref{prob_x_2}
\STATE Update dual variables $\bm{\mu}$ and $\bm{\lambda}$ by \eqref{update_mu} and \eqref{update_lambda}
\STATE Update penalty parameters $\rho_1 \leftarrow \epsilon \rho_1$, $\rho_2 \leftarrow \epsilon \rho_2$
\STATE Set $i \leftarrow i + 1$
\UNTIL  $\left\| \bm{\theta} - \bm{\phi} \right\|^2_2 + \underset{k \in \mathcal{K}}{\sum} \left\| \mathbf{R}_k \mathbf{t}_k - \mathbf{u}_k \right\|^2_2 \leq \varsigma_1$ and $\frac{\left|f_1^{(i)} - f_1^{(i-1)}\right|}{f_1^{(i-1)}} \leq \varsigma_2$
\end{algorithmic}
\end{algorithm}
%\cite[Theorem 3.12]{polik2010interior}
