\section{Joint Power and Antenna Control for Discrete Antenna Movement}
In this section, we consider PASS with discrete antenna movement. Different from the case with continuous antenna movement, the possible positions of the PAs with discrete movement are discretized, leading to the joint power and antenna control problem becoming an MINLP. To handle this issue, we recast the optimization problem as an antenna position selection problem. An algorithm exploiting the BCD method and bilinear transformation is developed to tackle the formulated optimization problem.
\par
\subsection{Problem Reformulation for Discrete Antenna Movement}
\par
The discrete antenna movement problem can be seen as an antenna position selection problem. Specifically, each PA should be assigned one particular position to move toward. Assume there are $\widetilde{N}$ available discrete positions within the maximum movement distance of each PA and we define the set $\widetilde{\mathcal{N}} \overset{\triangle}{=} \left[1, \dots, \widetilde{N} \right]$ to collect the indices of the available antenna positions. The location of the $\widetilde{n}$-th available antenna position with respect to the $(m,n)$-th PA is denoted by $\widetilde{\mathbf{p}}_{m,n,\widetilde{n}} = [\widetilde{x}_{m,n,\widetilde{n}}, y_m, h]^T$, where $\widetilde{x}_{m,n,\widetilde{n}}$ denotes the corresponding $x$-axis coordinate.
To accommodate the problem in the discrete antenna movement case, we first expand the equivalent channel between the PAs and the $k$-th user $\mathbf{h}_k^H\mathbf{G} \in \mathbb{C}^{1 \times MN}$ as follows
\begin{align} \label{disc_h}
\mathbf{h}_k^H\mathbf{G} = [\overline{\mathbf{h}}_{k,1}^H, \dots, \overline{\mathbf{h}}_{k,M}^H],
\end{align}
where $\overline{\mathbf{h}}_{k,m} \in \mathbb{C}^{N \times 1}$ denotes the effective channel vector between the $m$-th waveguide and the $k$-th user. By considering the problem as a discrete antenna position selection problem, we express $\overline{\mathbf{h}}_{k,m}$ as
\begin{align} \label{h_exp}
\overline{\mathbf{h}}_{k,m}^H & = \left[\widetilde{\mathbf{h}}_{k,m,1}^H \mathbf{z}_{m,1}, \dots, \widetilde{\mathbf{h}}_{k,m,N}^H \mathbf{z}_{m,N} \right], \notag \\
& = \widetilde{\mathbf{h}}_{k,m}^H \mathbf{Z}_m,·············
\end{align}
where
$\widetilde{\mathbf{h}}_{k,m}$ and $\mathbf{Z}_m$ are defined as
\begin{align}
\widetilde{\mathbf{h}}_{k,m} & \overset{\triangle}{=} \left[ \widetilde{\mathbf{h}}_{k,m,1}^H, \dots, \widetilde{\mathbf{h}}_{k,m,N}^H \right]^H  \in \mathbb{C}^{N\widetilde{N} \times 1}, \\
\mathbf{Z}_m & \overset{\triangle}{=} \diag \left[ \mathbf{z}_{m,1}, \dots, \mathbf{z}_{m,N} \right] \in \mathbb{C}^{N\widetilde{N} \times N},
\end{align}
Here, $\widetilde{\mathbf{h}}_{k,m,n}^H \overset{\triangle}{=} [\widetilde{h}_{k,m,n,1}, \dots, \widetilde{h}_{k,m,n,\widetilde{N}}]$ denotes the channel vector from all available antenna positions of the $(m,n)$-th PA to the $k$-th user, with the elements given by
\begin{align}
\widetilde{h}_{k,m,n,\widetilde{n}} = \frac{\beta e^{-j\frac{2\pi}{\lambda_c}(\|\widetilde{\mathbf{p}}_{m,n,\widetilde{n}} - \overline{\mathbf{p}}_k \|+n_{\text{eff}}\|\widetilde{\mathbf{p}}_{m,n,\widetilde{n}} - \mathbf{p}_{m,0} \|)}}{\|\widetilde{\mathbf{p}}_{m,n,\widetilde{n}} - \overline{\mathbf{p}}_k \|}.
\end{align}
% \begin{align}
% \overline{\mathbf{h}}_{k,m}^H & = \widetilde{\mathbf{h}}_{k,m}^H \mathbf{Z}_m,
% \end{align}
% where $\widetilde{\mathbf{h}}_{k,m}^H \overset{\triangle}{=} [\widetilde{h}_{k,m,1}, \dots, \widetilde{h}_{k,m,\widetilde{N}}]$ denotes the channel vector from all available antenna positions to the $k$-th user. $\widetilde{h}_{k,m,\widetilde{n}}$ is expressed as 
% \begin{align}
% \widetilde{h}_{k,m,\widetilde{n}} = \frac{\beta e^{-j\frac{2\pi}{\lambda_c}(\|\widetilde{\mathbf{p}}_{m,\widetilde{n}} - \overline{\mathbf{p}}_k \|+n_{\text{eff}}\|\widetilde{\mathbf{p}}_{m,\widetilde{n}} - \mathbf{p}_{m,0} \|)}}{\|\widetilde{\mathbf{p}}_{m,\widetilde{n}} - \overline{\mathbf{p}}_k \|}.
% \end{align}
% $\mathbf{Z}_m \overset{\triangle}{=} [\mathbf{z}_{m,1}, \dots, \mathbf{z}_{m,N}] \in \mathbb{Z}^{\widetilde{N} \times N}$ is antenna position selection matrix for the $m$-th waveguide.
We define vector $\mathbf{z}_{m,n} \overset{\triangle}{=} [z_{m,n,1}, \dots, z_{m,n,\widetilde{N}}]^T \in \mathbb{R}^{\widetilde{N} \times 1}$ to indicate the antenna position selection for the $(m,n)$-th PA. Specifically, $z_{m,n,\widetilde{n}} = 1$ indicates that the $(m,n)$-th PA will be moved to the available antenna position $\widetilde{\mathbf{p}}_{m,n,\widetilde{n}}$, otherwise, $z_{m,n,\widetilde{n}} = 0$. One PA occupies only one position, leading to the following constraint
\begin{align}
\mbox{C11:} \hspace{1mm} \mathbf{1}_{\widetilde{N}}^T \mathbf{z}_{m,n} = 1,\forall m \in \mathcal{M}, \forall n \in \mathcal{N},
% \underset{\widetilde{n} \in \widetilde{\mathcal{N}}}{\sum}
\end{align}
where $\mathbf{1}_{\widetilde{N}} \in \mathbb{R}^{\widetilde{N} \times 1}$ is a vector with all elements being equal to $1$. By substituting \eqref{h_exp} into \eqref{disc_h}, the effective channel vector $\mathbf{h}_k^H\mathbf{G}$ can be expressed as
\begin{align}
\mathbf{h}_k^H\mathbf{G} = \widetilde{\mathbf{h}}_k^H\mathbf{Z},
\end{align}
where 
\begin{align}
\widetilde{\mathbf{h}}_k & = [\widetilde{\mathbf{h}}_{k,1}^H, \dots, \widetilde{\mathbf{h}}_{k,M}^H ]^H \in \mathbb{C}^{MN\widetilde{N} \times 1}, \\
\mathbf{Z} & = \diag\left[ \mathbf{Z}_1, \dots, \mathbf{Z}_M \right]  \in \mathbb{C}^{MN\widetilde{N} \times MN}.
\end{align}
As a result, the SINR at the $k$-th user can be rewritten equivalently as
\begin{align}
\widetilde{\gamma}_k = \frac{\left| \widetilde{\mathbf{h}}_k^H\mathbf{Z} \mathbf{A} \mathbf{w}_k \right|^2}{ \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \widetilde{\mathbf{h}}_k^H\mathbf{Z} \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2}.
\end{align}
Then, we define $\widetilde{\mathbf{x}}_{m,n} = [\widetilde{x}_{m,n,1}, \dots, \widetilde{x}_{m,n,\widetilde{N}}]^T$ to collect all available locations of the $(m,n)$-th PA along the $x$-axis, leading to $x_{m,n} = \widetilde{\mathbf{x}}_{m,n}^T \mathbf{z}_{m,n}$. Furthermore, we define the displacement vector of the $(m,n)$-th PA as 
\begin{align}
\widetilde{\mathbf{d}}_{m,n} = \left[\left| \widetilde{x}_{m,n,1} - x'_{m,n} \right|, \dots, \left| \widetilde{x}_{m,n,\widetilde{N}} - x'_{m,n} \right| \right]^T,
\end{align}
which results in $|x_{m,n} - x'_{m,n}| = \widetilde{\mathbf{d}}_{m,n}^T \mathbf{z}_{m,n}$.
\par
Based on the above transformations, the optimization problem for discrete antenna movement is given by
\begin{align} \label{discrete}
\hspace*{-3mm}\underset{\substack{ \mathbf{w}_k, \bm{\alpha}_m, \mathbf{Z} }}{\mino} \hspace*{3mm} & \hspace{-1mm} f_5 \hspace{-1mm} \overset{\triangle}{=} \hspace{-1mm} \frac{T_2}{T_1 + T_2} \underset{k \in \mathcal{K}}{\sum} \| \mathbf{w}_k\|^2_2 \hspace{-1mm} + \hspace{-1mm} \frac{P}{(T_1 + T_2)v} \hspace{-1mm} \underset{\substack{m,n}}{\sum} \hspace{-1mm} \widetilde{\mathbf{d}}_{m,n}^T  \mathbf{z}_{m,n} \notag\\
\subto\hspace*{1mm} & \widetilde{\mbox{C1}}\mbox{:} \hspace{1mm} \widetilde{\gamma}_k \geq \Gamma_k, \hspace{1mm} \forall k \in \mathcal{K}, \notag \\
& \mbox{C2:}\hspace*{1mm} \left\| \bm{\alpha}_m \right\|^2_2 \leq 1, \hspace{1mm} \forall m, \notag \\
& \widetilde{\mbox{C3}} \mbox{:} \hspace*{1mm} \widetilde{\mathbf{x}}_m^T \mathbf{z}_{m,n} \hspace{-1mm} - \hspace{-1mm} \widetilde{\mathbf{x}}_m^T \mathbf{z}_{m,n-1} \hspace{-1mm} \geq \hspace{-1mm} \Delta_{\mathrm{min}}, \forall 2 \hspace{-1mm} \leq \hspace{-1mm} n \hspace{-1mm} \leq N, \forall m, \notag \\
& \widetilde{\mbox{C4}} \mbox{:} \hspace*{1mm} 0 \leq \widetilde{\mathbf{x}}_m^T \mathbf{z}_{m,n} \leq D, \hspace*{1mm} \forall n, \hspace{1mm} \forall m, \notag \\
& \widetilde{\mbox{C5}} \mbox{:} \hspace*{1mm} \widetilde{\mathbf{d}}_{m,n}^T \mathbf{z}_{m,n} \leq v T_1, \hspace*{1mm} \forall n, \hspace{1mm} \forall m, \notag \\
& \mbox{C11:}\hspace*{1mm} \mathbf{1}_{\widetilde{N}}^T \mathbf{z}_{m,n} = 1, \hspace*{1mm} \forall n, \hspace{1mm} \forall m, \notag \\
& \mbox{C12:}\hspace*{1mm} z_{m,n,\widetilde{n}} \in \{0, 1\}, \hspace*{1mm} \forall \widetilde{n}, \forall n, \hspace{1mm} \forall m.
\end{align}
\par
Compared to problem \eqref{continuous} for continuous antenna movement, problem \eqref{disc_h} has an additional binary constraint C12 for the antenna position selection variable, leading to a challenging MINLP problem.
\par
\subsection{Solution for Discrete Antenna Movement}
In this subsection, we develop a BCD-based algorithm to solve problem \eqref{discrete}.
The optimization variables are divided into two blocks, and the associated sub-problems are handled by capitalizing on bilinear transformation, penalty method, and SCA. A corresponding analysis of convergence and complexity is also provided.
\par
\begin{remark}
For continuous antenna movement, the channel coefficients depend on optimization variable $\mathbf{X}$ in problem \eqref{continuous} in a complicated manner, motivating the use of the variable splitting method, followed by using ADMM to handle the resulting equality constraints. However, problem \eqref{disc_h} for discrete antenna movement is formulated as an antenna position selection problem. The channel coefficients are a linear combination of the binary antenna position selection variables and the known channel coefficients of all possible antenna positions, making BCD suitable for handling the problem.
\end{remark}
\par
According to the principle of BCD, the variables of problem \eqref{discrete} are divided into two blocks, i.e., $\{ \mathbf{w}_k, \mathbf{Z}\}$ and $\{ \bm{\alpha}_m \}$. The sub-problems associated with the two blocks are solved in an alternating manner \cite{xu2025resolution}.
\par
\subsubsection{Update of $\{ \mathbf{w}_k, \mathbf{Z}\}$}
The sub-problem associated with block $\{ \mathbf{w}_k, \mathbf{Z}\}$ is given by
\begin{align} \label{bcd_1}
\hspace*{-3mm}\underset{\substack{ \mathbf{w}_k, \mathbf{Z} }}{\mino} \hspace*{3mm} & f_5  \notag\\
\subto\hspace*{3mm} & \widetilde{\mbox{C1}}, \widetilde{\mbox{C3}}\mbox{-}\widetilde{\mbox{C5}}, \mbox{C11}, \mbox{C12},
\end{align}
which is non-convex due to constraint $\widetilde{\mbox{C1}}$, the coupling between $\mathbf{w}_k$ and $\mathbf{Z}$, and binary constraint $\mbox{C12}$. In the following, we first transform $\widetilde{\mbox{C1}}$ into a more tractable form.
\par
We note that, similar to the transformation for \eqref{block_W}, a phase shift applied to $\mathbf{w}_k$ does not impact constraint $\widetilde{\mbox{C1}}$ nor the objective function value of problem \eqref{bcd_1}. Hence, $\widetilde{\mbox{C1}}$ can be equivalently expressed as
\begin{align}
\widetilde{\mbox{C1a}}\mbox{:} & \hspace{1mm} \left\lVert 
\begin{array}{c}
\mathbf{W}^H \mathbf{A}^H \mathbf{Z}^H \widetilde{\mathbf{h}}_k   \\ \sigma_k 
\end{array}
\right\rVert \leq \sqrt{1+\frac{1}{\Gamma_k}} \Re\left\{\widetilde{\mathbf{h}}_k^H \mathbf{Z} \mathbf{A} \mathbf{w}_k\right\}, \hspace{1mm} \forall k, \\
\widetilde{\mbox{C1b}} \mbox{:} & \hspace{1mm} \Im\left\{ \widetilde{\mathbf{h}}_k^H \mathbf{Z} \mathbf{A} \mathbf{w}_k \right\} = 0, \hspace{1mm} \forall k.
\end{align}
Next, we exploit the following bilinear transformation lemma to handle the variable coupling between $\mathbf{W}$ and $\mathbf{Z}$. 
\begin{lemma}
\textit{(Bilinear Transformation \cite{6698281})} The matrix equality $\mathbf{B} = \mathbf{C} \mathbf{D}$, where $\mathbf{C} \in \mathbb{C}^{M \times N}$, $\mathbf{D} \in \mathbb{C}^{N \times P}$, holds if and only if there exist $\mathbf{E} \succeq \mathbf{0}$, $\mathbf{F} \succeq \mathbf{0}$ such that the following two matrix inequalities hold
\begin{align}
& \begin{bmatrix}
\mathbf{E} & \mathbf{B} & \mathbf{C} \\
\mathbf{B}^H & \mathbf{F} & \mathbf{D}^H \\
\mathbf{C}^H & \mathbf{D} & \mathbf{I}_{N}
\end{bmatrix} \succeq \mathbf{0}, \label{bilinear_1} \\
& \mathrm{Tr}\left( \mathbf{E} - \mathbf{C}\mathbf{C}^H \right) \leq 0. \label{bilinear_2}
\end{align}
\end{lemma}
\par
Lemma 2 decouples the two coupled optimization variables using one convex constraint \eqref{bilinear_1} and one constraint \eqref{bilinear_2}, which is in the form of a d.c. function. Later, we will show that \eqref{bilinear_2} is actually convex by exploiting the special structure of binary selection variables.
Specifically, we introduce auxiliary variables $\mathbf{Q} \in \mathbb{C}^{M N \widetilde{N} \times K}$ with the $k$-th column being $\mathbf{q}_k$, and the following constraint
\begin{align}
\mbox{C13:} \hspace{1mm} \mathbf{Q} = \mathbf{ZAW}.
\end{align}
% As detailed in Section IV-A, $\mathbf{Q} = \mathbf{A} \mathbf{W}$ can be transformed into constraints C8a and $\overline{\mbox{C8b}}$ shown in \eqref{C8a} and \eqref{C8b}. 
Based on Lemma 2, constraint C13 is equivalently transformed into the following two constraints
\begin{align}
& \mbox{C13a} \mbox{:} \hspace{1mm} 
\begin{bmatrix}
\mathbf{P} & \mathbf{Q} & \mathbf{Z} \\
\mathbf{Q}^H & \mathbf{S} & \mathbf{W}^H\mathbf{A}^H \\
\mathbf{Z}^H & \mathbf{A}\mathbf{W} & \mathbf{I}_{MN}
\end{bmatrix} \succeq \mathbf{0}, \\
& \mbox{C13b} \mbox{:} \hspace{1mm} \mathrm{Tr}(\mathbf{P} - \mathbf{Z}\mathbf{Z}^H) \leq 0,
\end{align}
where $\mathbf{P} \in \mathbb{C}^{M N \widetilde{N}} \succeq \mathbf{0}$ and $\mathbf{S} \in \mathbb{C}^{K} \succeq \mathbf{0}$ are auxiliary variables.
Moreover, we have 
\begin{align}
\mathrm{Tr}\left(\mathbf{Z} \mathbf{Z}^H\right) & = \underset{m \in \mathcal{M}}{\sum} \mathrm{Tr}\left(\mathbf{Z}_m \mathbf{Z}_m^H\right)  \notag \\
& = \underset{m \in \mathcal{M}}{\sum} \underset{n \in \mathcal{N}}{\sum} \mathbf{z}_{m,n}^H \mathbf{z}_{m,n} \notag \\
& = MN,
\end{align}
where the last equality is obtained from constraints C11 and C12.
As a result, constraint $\mbox{C13b}$ can be equivalently expressed as
\begin{align}
\widetilde{\mbox{C13b}} \mbox{:} \hspace{1mm} \mathrm{Tr}(\mathbf{P}) \leq MN.
\end{align}
Accordingly, constraints $\widetilde{\mbox{C1a}}$ and $\widetilde{\mbox{C1b}}$ are rewritten as
\begin{align}
\mywidetilde{\mbox{C1a}}\mbox{:} & \hspace{1mm} \left\lVert 
\begin{array}{c}
\mathbf{Q}^H \widetilde{\mathbf{h}}_k \\ \sigma_k 
\end{array}
\right\rVert \leq \sqrt{1+\frac{1}{\Gamma_k}} \Re\left\{\widetilde{\mathbf{h}}_k^H \mathbf{q}_k\right\}, \hspace{1mm} \forall k \in \mathcal{K}, \\
\mywidetilde{\mbox{C1b}} \mbox{:} & \hspace{1mm} \Im\left\{ \widetilde{\mathbf{h}}_k^H \mathbf{q}_k \right\} = 0, \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
Optimization problem \eqref{bcd_1} is now transformed into
\begin{align} \label{bcd_1_1}
\hspace*{-3mm}\underset{\substack{ \mathbf{w}_k, \mathbf{Z}, \\ \mathbf{Q}, \mathbf{P}, \mathbf{S} }}{\mino} \hspace*{3mm} & f_5  \notag\\
\subto\hspace*{3mm} & \mywidetilde{\mbox{C1a}}, \mywidetilde{\mbox{C1b}}, \widetilde{\mbox{C3}}\mbox{-}\widetilde{\mbox{C5}}, \notag \\
& \mbox{C11}, \mbox{C12}, \mbox{C13a}, \widetilde{\mbox{C13b}},
\end{align}
where the remaining non-convexity originates from binary constraint C12. To tackle this obstacle, we first transform constraint C12 equivalently into the following two constraints
\begin{align}
& \mbox{C12a:} \hspace{1mm} 0 \leq z_{m,n,\widetilde{n}} \leq 1, \hspace*{1mm} \forall \widetilde{n}, \hspace{1mm} \forall n, \hspace{1mm} \forall m, \\
& \mbox{C12b:} \hspace{1mm} \underset{\substack{m,n,\widetilde{n}}}{\sum} \left(- z^2_{m,n,\widetilde{n}} + z_{m,n,\widetilde{n}}\right) \leq 0,
\end{align}
where constraint C12b is a non-convex d.c. function. To deal with this issue, we first penalize it in the objective function by applying the penalty method, resulting in the following problem
\begin{align} \label{bcd_penalty}
\hspace*{-3mm}\underset{\substack{ \mathbf{w}_k, \mathbf{Z}, \\ \mathbf{Q}, \mathbf{P}, \mathbf{S} }}{\mino} \hspace*{3mm} & \overline{f}_5 \overset{\triangle}{=} f_5 + \zeta \underset{\substack{m,n,\widetilde{n}}}{\sum} \left(- z^2_{m,n,\widetilde{n}} + z_{m,n,\widetilde{n}}\right)  \notag\\
\subto\hspace*{3mm} & \mywidetilde{\mbox{C1a}}, \mywidetilde{\mbox{C1b}}, \widetilde{\mbox{C3}}\mbox{-}\widetilde{\mbox{C5}}, \notag \\
& \mbox{C11}, \mbox{C12a}, \mbox{C13a}, \widetilde{\mbox{C13b}},
\end{align}
where $\zeta > 0$ is the penalty parameter to enforce that constraint C12b is satisfied after optimization. 
% Then, an upper-bound on the term $- z^2_{m,n,\widetilde{n}}$ is constructed as follows
% \begin{align}
% - z^2_{m,n,\widetilde{n}} \leq -2 \left(z_{m,n,\widetilde{n}}^{(i-1)}\right) z_{m,n,\widetilde{n}} + \left(z_{m,n,\widetilde{n}}^{(i-1)}\right)^2,
% \end{align}
% where the value of $z_{m,n,\widetilde{n}}^{(i-1)}$ is obtained in the previous iteration. 
An upper-bound on $\overline{f}_5$ is established as follows 
\begin{align}
\overline{f}_5 & \leq f_5 + \zeta \underset{\substack{m,n,\widetilde{n}}}{\sum} \left( \left(-2 \left(z_{m,n,\widetilde{n}}^{(i-1)}\right) + 1 \right)z_{m,n,\widetilde{n}} + \left(z_{m,n,\widetilde{n}}^{(i-1)}\right)^2 \right) \notag \\
& \overset{\triangle}{=} \widetilde{f}_5,
\end{align}
where the value of $z_{m,n,\widetilde{n}}^{(i-1)}$ is obtained in the previous iteration.
Optimization problem \eqref{bcd_penalty} is now transformed into
\begin{align} \label{bcd_1_final}
\hspace*{-3mm}\underset{\substack{ \mathbf{w}_k, \mathbf{Z}, \\ \mathbf{Q}, \mathbf{P}, \mathbf{S} }}{\mino} \hspace*{3mm} & \widetilde{f}_5  \notag\\
\subto\hspace*{3mm} & \mywidetilde{\mbox{C1a}}, \mywidetilde{\mbox{C1b}}, \widetilde{\mbox{C3}}\mbox{-}\widetilde{\mbox{C5}}, \notag \\
& \mbox{C11}, \mbox{C12a}, \mbox{C13a}, \widetilde{\mbox{C13b}},
\end{align}
which is a convex optimization problem and can be solved efficiently.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Update of $\left\{ \bm{\alpha}_m \right\}$}
The sub-problem associated with $\left\{ \bm{\alpha}_m \right\}$ is a feasibility checking problem which is given by
\begin{align} \label{bcd_2}
\underset{\substack{ }}{\mathrm{Find}} \hspace*{3mm} & \bm{\alpha}_m   \notag\\
\subto\hspace*{3mm} & \widetilde{\mbox{C1}}, \mbox{C2}.
\end{align}
Similar to the steps for addressing problem \eqref{alpha_feasibility_continuous}, we update $\bm{\alpha}_m$ by solving the following optimization problem
\begin{align} \label{bcd_alpha_max}
\underset{\substack{ \bm{\alpha}_m }}{\maxo} \hspace*{3mm} & \underset{k \in \mathcal{K}}{\sum} \frac{\left| \widetilde{\mathbf{h}}_k^H\mathbf{Z} \mathbf{A} \mathbf{w}_k \right|^2}{ \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \widetilde{\mathbf{h}}_k^H\mathbf{Z} \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2} \notag\\
\subto\hspace*{3mm} & \mbox{C2:} \hspace{1mm}  \left\| \bm{\alpha}_m \right\|^2_2 \leq 1, \hspace{1mm} \forall m \in \mathcal{M}.
\end{align}
Then, we recast optimization problem \eqref{bcd_alpha_max} as follows
\begin{align} \label{bcd_alpha_frac}
\underset{\substack{ \bm{\alpha}_m, \widetilde{\bm{\psi}} }}{\maxo} \hspace*{3mm} & f_6 \notag\\
\subto\hspace*{3mm} & \mbox{C2}, \mbox{C14},
\end{align}
where $\widetilde{\bm{\psi}} \in \mathbb{R}^{K \times 1}$ is an auxiliary variable whose $k$-th element is $\widetilde{\psi}_k$, and objective function $f_6$ is given by
\begin{align}
f_6 \overset{\triangle}{=} \underset{k \in \mathcal{K}}{\sum} \left( 2 \widetilde{q}_k \widetilde{\psi}_k - \widetilde{q}_k^2 \left( \underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \widetilde{\mathbf{h}}_k^H \mathbf{Z} \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2 \right) \right).
\end{align}
Furthermore, constraint C14 in \eqref{bcd_alpha_frac} is given by
\begin{align}
& \mbox{C14} \mbox{:} \hspace{1mm} \mathrm{Tr}\left( \left( \widetilde{\mathbf{T}}_k \mathbf{A}^{(i-1)} \mathbf{W}_k + \widetilde{\mathbf{T}}_k^T \mathbf{A}^{(i-1)} \mathbf{W}_k^T \right)^T \mathbf{A} \right) \notag \\
& - \mathrm{Tr} \left( \widetilde{\mathbf{T}}_k \mathbf{A}^{(i-1)} \mathbf{W}_k \left(\mathbf{A}^{(i-1)}\right)^T \right) - \widetilde{\psi}_k^2 \geq 0, \hspace{1mm} \forall k,
\end{align}
where $\widetilde{\mathbf{T}}_k \overset{\triangle}{=} \mathbf{Z}^H  \widetilde{\mathbf{h}}_k \widetilde{\mathbf{h}}_k^H \mathbf{Z} $. Variable $\widetilde{q}_k$ is updated according to
\begin{align}
\widetilde{q}_k = \frac{\left| \widetilde{\mathbf{h}}_k^H \mathbf{Z} \mathbf{A} \mathbf{w}_k \right| }{\underset{k' \in \mathcal{K}\setminus \{k\}}{\sum}\left| \widetilde{\mathbf{h}}_k^H \mathbf{Z} \mathbf{A} \mathbf{w}_{k'} \right|^2 + \sigma_k^2}, \hspace{1mm} \forall k \in \mathcal{K}.
\end{align}
\par
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{algorithm}[t]
\caption{BCD-based Algorithm for Solving Problem \eqref{discrete} for Discrete Antenna Movement}
\begin{algorithmic}[1]
\small
\STATE Set iteration index $i=1$, penalty parameter $\zeta > 0$, error tolerance $\widetilde{\varsigma}$. Initialize $\alpha_{m,n}^{(1)} = \frac{1}{\sqrt{N}}$ and $z_{m,n,\widetilde{n}}^{(1)} = 0$
\REPEAT
\STATE Update $\mathbf{w}_k$, $\mathbf{Z}$ by solving problem \eqref{bcd_1_final}
\STATE Update $\bm{\alpha}_m$ by solving problem \eqref{bcd_alpha_frac}
\STATE Set $i \leftarrow i + 1$
\UNTIL $\frac{\left|\widetilde{f}_5^{(i)} - \widetilde{f}_5^{(i-1)}\right|}{\widetilde{f}_5^{(i-1)}} \leq \widetilde{\varsigma}$
\end{algorithmic}
\end{algorithm}
%\cite[Theorem 3.12]{polik2010interior}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\par
The BCD-based algorithm for solving problem \eqref{discrete} for discrete antenna movement is summarized in $\textbf{Algorithm 2}$. The objective function value of problem \eqref{bcd_1_final} is an upper-bound on the objective function value of problem \eqref{bcd_penalty}. This upper-bound is gradually tightened by iteratively solving problem \eqref{bcd_1_final}. Recall that solving \eqref{bcd_alpha_frac} does not directly influence the objective function value of \eqref{discrete}. Hence,
by iteratively solving problems \eqref{bcd_1_final} and \eqref{bcd_alpha_frac}, the objective function value of problem \eqref{discrete} is monotonically non-increasing. Thus, according to \cite{razaviyayn2013unified}, the proposed algorithm is guaranteed to converge to a stationary point of problem \eqref{discrete} within polynomial time.
The computational complexity of Algorithm 2 is dominated by solving problem \eqref{bcd_1_final} whose complexity is given by $\mathcal{O}( M^3N^3\widetilde{N}^3 K^{3.5} + MN\widetilde{N} K^{4.5} )$.
