\title{The Recovery of $\lambda$ from a Hilbert Polynomial}
\author[1]{Joseph Donato \thanks{Corresponding Author}\thanks{jdonato@lanl.gov}}
\affil[1]{Methods and Algorithms Group, XCP-4, X-Computational Physics Division, Los Alamos National Laboratory}
