	\begin{detail}
		Algorithm \ref{alg:mdbb} outlines the pseudocode of our proposed branch-and-bound algorithm. It takes a bipartite graph $G$ and two integers $k$ and $\theta$ as input parameters, and returns a $k$-MDB $D^*$ of $G$. It first initializes $D^*$ as an empty graph, and then starts to search $k$-MDB by invoking the procedure \brb where all vertices in $G$ serve as the candidate set (line 2). 
		\brb holds an instance $(S, C)$ as its parameter, where $S$ denotes the partial set and $C$ denotes the candidate set. Within \brb, the algorithm first determines whether a larger $k$-defective biclique has been found  (lines 5-8). After that, it selects a branching vertex $u$ from $C$ using the new binary branching strategy (lines 9-10) and generates two sub-instance $(S',C'\cup\{u\})$ and $(S, C\setminus\{u\})$ (lines 11-12). Here, $S'$ and $C'$ are the new partial set and new candidate set derived by invoking \upd (line 11), ensuring the candidate set keeps all valid branching vertex (lines 14-15). We next analyze the time complexity of Algorithm \ref{alg:mdbb}.

	\end{detail}

	\begin{algorithm}[!t]
		\caption{The branch-and-bound algorithm}
		\scriptsize
		\label{alg:mdbb}
		\KwIn{Bipartite graph $G=(U,V,E)$, integers $k$ and $\theta$}
		\KwOut{A $k$-MDB of $G$}

		%$D^*\leftarrow$ an initial $k$-defective biclique\;
		$D^*\leftarrow$ an empty graph\;
		\brb{$(\emptyset, \emptyset)$, $(U, V)$}\;
		\Return {$D^*$}\;

		\Proc{\brb{$S=(U_S,V_S)$, $C=(U_C,V_C)$}} {
			\If{$C=\emptyset$} {
				\If{$\lvert E_{G(S)}\rvert >\lvert E_{D^*}\rvert$ \And $\lvert U_S\rvert\ge \theta$ \And $\lvert V_S\rvert\ge \theta$} {$D^*\leftarrow G(S)$\;}
				\Return{}\;
			}

			% Select a branching vertex $u$ from $C$ with the branching strategy.


			$u\leftarrow \mathrm{\arg\max}_{v\in C}\overline{d}_S(v)$\;

			\lIf{$\overline d_S(u)=0$} {
				$u\leftarrow \mathrm{\arg\max}_{v\in C}\overline{d}_C(v)$
			}

			$(S', C')\leftarrow$ \upd{$S$, $C$, $u$}\;
			\brb{$S'\cup \{u\}$, $C'$};\ 
			\brb{$S$, $C\setminus \{u\}$}\;

		}

		\Fn{\upd{$S$, $C$, $u$}} {
			$C'\leftarrow\{v\in C\setminus\{u\}\mid\overline{d}_{S\cup\{u\}}(v)\le k-\overline{d}(S)\}$\;
			$C'_0\leftarrow\{v\in C'\mid\overline{d}_{S\cup\{u\}\cup C'}(v)=0\}$\;
			\Return{$(S\cup C'_0, C'\setminus C'_0)$}\;
		}

	\end{algorithm}

