	%\subsubsection{Time Complexity Analysis}


	\begin{theorem}
		Given a bipartite graph $G=(U,V,E)$ and an integer $k$, the time complexity Algorithm \ref{alg:mdbb} is given by $O(m\alpha_k^n)$, where $\alpha_k$ is the largest real root of equation $x^{2k+5}-2x^{2k+4}+x^3-x^2+1=0$. Specifically, when $k=1,2$ and $3$, we have $\alpha_k=1.911,1.979$ and $1.995$, respectively.
	\end{theorem}



	\begin{proof}
		Let $T(n)$ denote the maximum number of leave instances generated by \brb (i.e. instances with an empty $C$), where $n=\lvert C\rvert=\lvert U_C\rvert+\lvert V_C\rvert$. Since each recursive call of \brb takes $O(m)$ time, the total time complexity of \brb is $O(m\cdot T(n))$. 

		Then, we analyze the size of $T(n)$ based on the binary branching strategy. 
		In each branch of \brb, either a vertex with at least one non-neighbor in $S$ or a vertex with the most non-neighbors in $C$ is selected as the branching vertex. If the vertex $u$ with at least one non-neighbor in $S$ is selected, it results in at least one additional non-edge in $S\cup \{u\}$. Alternatively, if a vertex $v$ with the most non-neighbors in $C$ is selected as the branching vertex, the next-level branch will contain at least $\overline{d}_C(v)$ vertices in $C$ that have non-neighbors in $S\cup \{v\}$, where $\overline{d}_C(v) > 0$. Consequently, we can conclude that in the worst case, adding two vertices from $C$ to $S$ will result in at least one additional non-edge in $S$. After adding at most $2k+1$ vertices from $C$ to $S$, we have $\lvert \overline E_S\rvert =k$ and there exists a vertex $v\in C$ such that $\overline d_S(v)>0$. Based on this, the recurrence is given by $T(n)\le \sum_{i=1}^{2k+1} T(n-i)+T(n-2k-2)$.
		%In the worst case, no vertex is removed from $C$ except the branching vertex. According to the binary branching strategy, if there are no vertices of $C$ with non-neighbor in $S$, any branching vertex $u\in C$ should have at least one non-neighbor in $C$ (otherwise $u$ can be directly added to $S$ according to Fact \ref{fac:rr1}). After adding $u$ to $S$, at least one vertex of $C$ has non-neighbors in $S$. This implies that in the worst case, consecutively adding two vertices from $C$ to $S$ will result in at least one additional non-edge in $S$. After adding at most $2k+1$ vertices from $C$ to $S$, we have that $\lvert \overline E_S\rvert =k$ and there exists a vertex $v\in C$ satisfying $\overline d_S(v)>0$. Based on this, we can derive the following recurrence.


	%	\begin{align} \label{eq:1}

		%\end{align}
		Note that the $(2k+2)$-th level of branching (the term $T(n-2k-2)$) corresponds to a branch that searches for the maximum biclique. In this case, it is evident that any vertex in $C$ selected as the branching vertex will result in at least one additional vertex being removed from $C$. Thus, we yield a recurrence of $T(n-2k-2)=T(n-2k-3)+T(n-2k-4)$ for such a branch. Based on above discussion, we can present the following tighter recurrence.
		\begin{align}
			T(n)\le \sum_{i=1}^{2k+1} T(n-i)+T(n-2k-3)+T(n-2k-4).
		\end{align}
		According to the theory proposed in \cite{RN76}, $T(n)$ can be expressed in the form of $\alpha_k^n$, where the value of $\alpha_k$ derives from the largest real root of equation $x^n=x^{n-1}+x^{n-2}+\cdots+x^{n-2k-1}+x^{n-2k-3}+x^{n-2k-4}$, which can be simplified to $x^{2k+5}-2x^{2k+4}+x^3-x^2+1=0$. Therefore, the theorem is proven.
	\end{proof}

	\begin{lemma}
		Given a bipartite graph $G=(U,V,E)$, the time complexity of Algorithm \ref{alg:mdbb} for finding a $0$-MDB of $G$ is $O(m\times 1.618^n)$.
	\end{lemma}
	\begin{proofsketch}
		When $k=0$, the vertex $v\in C$ with maximum $\overline d_C(v)$ is selected as the branching vertex. Moving $v$ from $C$ to $S$ results in the deletion of $v$'s non-neighbors in $C$, leading to the recurrence $T(n)\le T(n-1)+T(n-2)$, which yields $T(n)=1.618^n$.
	\end{proofsketch}

	\subsection{A Novel Pivoting-based Algorithm} \label{sec:mdbp}

	We observe that Algorithm \ref{alg:mdbb} may still generate numerous unnecessary sub-instances. Consider an instance $(S, C)$ and a branching vertex $v\in C$ with $\overline d_S(v)=0$. In Algorithm \ref{alg:mdbb}, if $v$ and all non-neighbors of $v$ have been excluded from the current instance, the remaining vertices cannot form any $k$-MDB. This is because any $k$-defective biclique derived from these remaining vertices can always be expanded by including $v$. Consecutively, Algorithm \ref{alg:mdbb} may produce many $k$-defective bicliques that are not maximum. To address the problem and further improve the efficiency, we propose a novel pivoting-based algorithm in this section. We formalize above insights into the following lemma.

	\begin{lemma}
		\label{lem:piv}
		Given an instance $(S,C)$ and any vertex $v\in C$ with $\overline d_S(v)=0$, the $k$-MDB of instance $(S,C)$ must contain either $v$ or a vertex in $\overline N_C(v)$.
	\end{lemma}

	%\begin{proofsketch}
	%	This can be proven by contradiction. If there is a $k$-MDB $D$ derived from instance $(S,C\setminus\{v\}\setminus \overline N_C(v))$, then $v$ can always be added to $D$ to form a larger $k$-defective biclique $D\cup\{v\}$ since $v$ has no non-neighbor in $D$, which indicates that $D$ is not the maximum.
	%\end{proofsketch}



	%\textbf{Branching Strategy}
	Based on Lemma \ref{lem:piv}, we develop a pivoting strategy that provides a new way to generate sub-instances. The details are presented as follows. 

	\noindent\textbf{Pivoting strategy.} Consider an instance $(S, C)$ and a vertex $u\in C$ with $\overline d_S(u)=0$. Let $u$ be the \textit{pivot vertex}. Assume $\overline N_C(u)=\{v_1,v_2,\dots,v_{r}\}$, where $r=\overline d_C(u)$. The pivoting strategy treats each vertex in $\{u\}\cup \overline N_C(u)$ as a branching vertex and generates exactly $r+1$ sub-instances. The first sub-instance is given by $(S\cup\{u\}, C\setminus\{u\})$, and for $i\ge 2$, the $i$-th sub-instance is given by $(S\cup\{v_{i-1}\}, C\setminus\{u, v_1,v_2,\dots,v_{i-1}\})$. 

	With this strategy, $S$ is expanded only with the vertex $u$ and vertices in $\overline N_C(u)$, avoiding redundant sub-instances that would lead to non-maximum $k$-defective biclique. Next, we consider the selection of the pivot vertex. Let $C_0\subseteq C$ be the set of vertices fully connected to $S$, i.e., $C_0=\{v\in C\mid\overline d_S(v)=0\}$. According to the pivoting strategy, any vertex from $C_0$ can serve as a pivot vertex. To minimize the number of sub-instances, the vertex $u\in C_0$ with the fewest non-neighbors in $C$ is chosen as the pivot vertex. 

	In the case where $C_0$ is empty, every vertex in $C$ has at least one non-neighbor in $S$, making the pivoting strategy inapplicable. Fortunately, as discussed in Sec. \ref{sec:mdbb}, continuously branching $k$ times by adding vertices from $C$ to $S$ will result in $S$ containing at least $k$ non-edges. Moreover, $C$ becomes an empty set after this process, which significantly reduces unnecessary computations. Motivated by this observation, we integrate the pivoting strategy with the binary branching strategy to develop a novel pivoting-based branching strategy as outlined below.



	\noindent\textbf{Novel pivoting-based branching strategy.} Given an instance $(S, C)$, let $C_0=\{v\in C\mid\overline d_S(v)=0\}$. The new sub-instances of $(S, C)$ are generated in the following way:
	\begin{itemize}
		\item If $C_0$ is empty or $\lvert C\setminus C_0\rvert>k-\lvert\overline E_S\rvert$, let $u=\mathrm{\arg\max}_{v\in C} \overline{d}_S(v)$ be the branching vertex and generate two sub-instances: $(S\cup\{u\}, C\setminus\{u\})$ and $(S, C\setminus\{u\})$.
		\item Otherwise, let $u=\mathrm{\arg\min}_{v\in C_0}\overline{d}_C(v)$, and then:
		\begin{itemize}
			\item If $\overline d_C(u) > k-\lvert\overline E_S\rvert > 0$, generate two sub-instances with $u$ as the branching vertex: $(S\cup\{u\}, C\setminus\{u\})$ and $(S, C\setminus\{u\})$.
			\item Otherwise, assume $\overline N_C(u)=\{v_1,v_2,\dots,v_{r}\}$, where $r=\overline d_C(v)$, and generate $\overline d_C(u)+1$ sub-instances with $u$ as the pivot vertex, where the first sub-instance is given by $(S\cup\{u\}, C\setminus\{u\})$, and for $i\ge 2$, the $i$-th sub-instance is given by $(S\cup\{v_{i-1}\}, C\setminus\{u, v_1,v_2,\dots,v_{i-1}\})$.
		\end{itemize}  
	\end{itemize}


