		\begin{detail}
			Algorithm \ref{alg:mdbp} outlines the pseudocode of the proposed pivot-based algorithm. It begins by searching for $k$-MDB by invoking the procedure \brp with an empty partial set $S$ and the entire vertex set of $G$ as the candidate set $C$ (line 2). The algorithm returns the global variable $D^*$ as the final $k$-MDB after \brp is processed (line 3). Within \brp, the algorithm first updates $D^*$ if a larger $k$-defective biclique is found (lines 5-7). Then, it generates new sub-instances based on the pivoting-based branching strategy (lines 8-22). Specifically, if $C_0=\emptyset$ or $\lvert C\setminus C_0\rvert>k-\lvert\overline E_S\rvert$, the vertex $u= \mathrm{\arg\max}_{v\in C}\overline{d}_S(v)$ is selected as the branching vertex (line 11), and two new sub-instances are generated (line 13). Otherwise, the algorithm assigns $u=\mathrm{\arg\min}_{v\in C_0}\overline{d}_C(v)$. If $\overline d_C(u)>k-\lvert \overline E_S\rvert$, two sub-instances are generated with $u$ as the branching vertex (lines 16-18). Otherwise, $\overline d_C(u)+1$ new sub-instances are generated with $u$ and all $u$'s non-neighbors in $C$ as branching vertex (lines 20-22). When a branching vertex is added to $S$, the algorithm adopts the \upd procedure presented in Algorithm \ref{alg:mdbb} to update the current instance (lines 12, 17 and 21). Below, we analyze the time complexity of Algorithm \ref{alg:mdbp}.
		\end{detail}

			\begin{algorithm}[!t]
			\caption{The pivoting-based algorithm}
			\scriptsize
			\label{alg:mdbp}
			\KwIn{Bipartite graph $G=(U,V,E)$, integers $k$ and $\theta$}
			\KwOut{A $k$-MDB of $G$}

			%$D^*\leftarrow$ an initial $k$-defective biclique\;
			$D^*\leftarrow$ an empty graph\;
			\brp{$(\emptyset, \emptyset)$, $(U, V)$}\;
			\Return {$D^*$}\;

			\Proc{\brp{$S=(U_S,V_S)$, $C=(U_C,V_C)$}} {
				\If{$C=\emptyset$} {
					\If{$\lvert E_{G(S)}\rvert >\lvert E_{D^*}\rvert$ \And $\lvert U_S\rvert\ge \theta$ \And $\lvert V_S\rvert\ge \theta$} {$D^*\leftarrow G(S)$\;}
					\Return{}\;
				}

				$C_0\leftarrow \{v\in C\mid\overline d_{S}(v)= 0\}$\;

				%$u\leftarrow \mathrm{\arg\min}_{v\in C_0}\overline{d}_C(v)$\;
				%$\overline d_S(C) \leftarrow \sum_{v\in C\setminus C_0}\overline d_S(v)$\;
				%$\overline d_C(C) \leftarrow \sum_{v\in C}\overline d_C(v)$\;


				%\If{$C_0=\emptyset $ \Or $\overline d_S(C)> k-\lvert \overline E_S\rvert$ \newline \Or $(\overline d_S(C)> k-\lvert \overline E_S\rvert$ \And $\exists v\in C\setminus C_0,\, \overline d_C(v)>0)$ } {
					\If{$C_0= \emptyset$ \Or $\lvert C\setminus C_0\rvert >k-\lvert \overline E_S\rvert$} {
						$u\leftarrow \mathrm{\arg\max}_{v\in C}\overline{d}_S(v)$\;
						$(S', C')\leftarrow$ \upd{$S$, $C$, $u$}\;
						\brp{$S'\cup \{u\}$, $C'$};\ \brp{$S$, $C\setminus \{u\}$}\;
					}
					\Else {
						$u\leftarrow \mathrm{\arg\min}_{v\in C_0}\overline{d}_C(v)$\;
						\If {$\overline d_C(u)>k-\lvert \overline E_S\rvert>0$} {
							$(S', C')\leftarrow$ \upd{$S$, $C$, $u$}\;
							\brp{$S'\cup \{u\}$, $C'$};\ \brp{$S$, $C\setminus \{u\}$}\;
						}
						\Else {
							\For{$v\in \{u\}\cup\overline{N}_C(u)$}{
								$(S', C')\leftarrow$ \upd{$S$, $C$, $v$}\;
								\brp{$S'\cup \{v\}$, $C'$};\ $C\leftarrow C\setminus \{v\}$\;
							}
						}
					}

				}

			\end{algorithm}

		%\textbf{Time Complexity Analysis}


		\begin{theorem}
			\label{thm:mdbp}
			Given a bipartite graph $G=(U,V,E)$ and an integer $k$, the time complexity of Algorithm \ref{alg:mdbp} is given by $O(m\beta_k^n)$, where $\beta_k$ is the largest real root of equation $x^{2k+5}-2x^{2k+4}+x^{k+3}-2x+2=0$. Specifically, when $k=1,2$ and $3$, we have $\beta_k=1.717, 1.856$ and $1.931$, respectively.
		\end{theorem}

		\begin{proof}
			In Algorithm \ref{alg:mdbp}, Let $T(n)$ denote the maximum number of leave instances generated by \brp, where $n=\lvert C\rvert =|U_C|+|V_C|$. It is easy to verify that finding the vertex with most (least) non-neighbors in $S$ ($C$) takes at most $O(m)$ time. Then, each recursive call of \brp takes $O(m)$ time, and thus \brp takes $O(m\cdot T(n))$ time.
			We next focus on analyzing the size of $T(n)$. Based on the pivoting-based branching strategy, there are three cases that need to be discussed:
			\begin{enumerate}
				\item If $C_0=\emptyset$ or $\lvert C\setminus C_0\rvert > k-\lvert\overline E(S)\rvert$, \brp continuously applies the binary branching strategy. After moving at most $k$ vertices from $C$ to $S$, $S$ contains $k$ non-edges. At this point, at least one vertex in $C$ will be removed as it has non-neighbors in $S$. Therefore, the recurrence for this case is given by
				%\begin{align}
				$T(n)\le \sum_{i=1}^{k+1} T(n-i)$.
				%\end{align}
				\item If $k-\lvert\overline E_S\rvert=0$, \brp degenerates into maximum biclique search and continuously applies the pivoting strategy. Let $r=\overline d_C(u)$, the recurrence for this case is given by $T(n)\le T(n-r-1)+\sum_{i=1}^{r}T(n-r-i)$. If $r\le1$, we have $T(n)\le 2T(n-2)$. If $r\ge 2$, let $T(n)=\gamma_r^n$ according to the existing theory \cite{RN76}, where $\gamma_r$ is the largest real root of equation $x^n=x^{n-r-1}+\sum_{i=1}^{r} x^{n-r-i}$. The value of $\gamma_r$ is monotonically decreasing with respect to $r$ when $r\ge 2$. By solving the equation we have $\gamma_2=1.395<\sqrt{2}$. As a result, we can always say $T(n)\le 2T(n-2)$ for this case.

				%Since $\beta^{n-r-1}+\sum_{i=1}^r \beta^{n-r-i}=\frac{2\beta^{n-r}-\beta^{n-r-1}-\beta^{n-2r}}{\beta-1}\le\frac{2\beta^{n-r}-2\beta^{n-r-1}}{\beta-1}\le2\beta^{n-2}$, we have $T(n)\le 2T(n-2)$. Therefore, the recurrence for this case is given by 
				%\begin{align} \label{eq:4}
				%$T(n)\le 2T(n-2)$.
				%\end{align}



				\item Otherwise, let $u=\mathrm{\arg\min}_{v\in C_0}\overline{d}_C(v)$.  
				If $\overline d_C(u)\le k-\lvert\overline E(S)\rvert$, \brp performs the pivoting strategy with $u$ as the pivot vertex. This strategy generates at most $ \overline{d}_C(u)+1 \le k+1$ sub-instances. Therefore, the recurrence for this case is given by $T(n)\le \sum_{i=1}^{k+1} T(n-i)$.
				Otherwise, \brp uses $u$ to perform binary branching strategy. In the next-level branching, we have $|C\setminus C_0| > k- \lvert\overline E(S \cup \{u\})\rvert$, as $\overline d_C(u) > k-\lvert\overline E(S)\rvert$. In this case, the sub-branch (the term $T(n-1)$) will continuously perform the binary branching strategy as discussed in case (1). Consequently, the recurrence for this case is given by $T(n)\le\sum_{i=1}^{k+1} T(n-i)+T(n-2k-2)$. Note that the term $T(n-2k-2)$ degenerates to maximum biclique search, and we can derive that $T(n-2k-2) = 2 T(n-2k-4)$ as discussed in case (2). Therefore, the final recurrence for this case is given by 
				%\begin{align} 
					$T(n)\le \sum_{i=1}^{k+1}T(n-1)+2T(n-2k-4)$. 
				%\end{align}
			\end{enumerate}
			\hspace{1em} By combining the above analysis, the worst-case recurrence is given by
			\begin{align} 
				\setlength\abovedisplayskip{0pt}
				\setlength\belowdisplayskip{0pt}
			T(n)\le \sum_{i=1}^{k+1}T(n-1)+2T(n-2k-4). 
			\end{align}

			Based on the existing theorem proposed in \cite{RN76}, we denote by $T(n)=\beta_k^n$, where $\beta_k$ is the largest real root of equation $x^n=x^{n-1}+x^{n-2}+\cdots+x^{n-k-1}+2x^{n-2k-4}$. The equation is equivalent to $x^{2k+5}-2x^{2k+4}+x^{k+3}-2x+2=0$. Consequently, the theorem is proven.
		\end{proof}
		%{\color{blue} In the proof of Theorem \ref{thm:mdbp}, Case (2) facilitates the analysis of the time complexity of Algorithm \ref{alg:mdbp} for the specific case where $k=0$, as detailed in the following lemma.
		\begin{lemma}
			Given a bipartite graph $G=(U,V,E)$, the time complexity of Algorithm \ref{alg:mdbp} for finding a $0$-MDB of $G$ is $O(m\cdot1.414^n)$. 
		\end{lemma}	
		\begin{proofsketch}
			When setting $k=0$, Algorithm \ref{alg:mdbp} will always execute the pivoting-based branching strategy (lines 20-22), corresponding to a recurrence of $T(n) < 2T(n-2)$ according to the proof of Theorem \ref{thm:mdbp}. Therefore, we have $T(n)=1.414^n$.
		\end{proofsketch}	


		\noindent\textbf{Discussion.}
		It is worth noting that the branch-and-bound and pivoting techniques has been widely applied on many cohesive subgraph models such as the $k$-defective clique \cite{RN2, RN3, RN4}, the $k$-biplex \cite{RN71, RN72} and the biclique \cite{RN45, RN46, RN44}. However, our binary branching strategy and pivoting-based branching strategy are significantly different from all these existing solutions. 

		Compared to the state-of-the-art maximum $k$-defective clique algorithm in \cite{RN2}, which achieves a non-trivial time complexity by utilizes a condition to restrict the scenarios of pivoting, directly applying this approach to our pivoting-based algorithm would degrade the time complexity to $O^*(2^n)$. In contrast, we employ a more refined pivoting strategy that considers both the number of non-edges between $S$ and $C$ (lines 10-13 in Algorithm \ref{alg:mdbp}) and the number of pivot vertex's non-neighbors (lines 15-18 in Algorithm \ref{alg:mdbp}), thereby effectively bounding the time complexity. 

		Compared to the state-of-the-art pivoting-based maximum biplex search algorithm in \cite{RN71}, which achieves a time complexity of $O(m\gamma_k^n)$, with $\gamma_k=1.754$ when $k=1$, our algorithm \mdbp reaches a better time complexity. This is mainly because the algorithm in \cite{RN71} only considers prioritizing $k$ non-neighbors of $S$, which is similar to our binary branching strategy in Sec. \ref{sec:mdbb}. By contrast, our pivoting-based branching strategy also bounds the case that fewer than $k$ non-neighbors are between $S$ and $C$, which reduces the size of branching tree and thereby improves the time complexity (see the proof of Theorem \ref{thm:mdbp}).

		Compared to the maximal biclique algorithm in \cite{RN45}, our pivot vertex selection approach is much different. During the pivoting process, \cite{RN45} considers the common neighbors, and selects pivot vertex in a heuristic topological order from only one side, which may not be always optimal. In contrast, our pivoting-based branching strategy selects pivot vertex from both side through deterministic condition, which always generates fewest new sub-branches in each recursion.

