	%\end{proofsketch}
	In practice, Algorithm \ref{alg:cnred} performs efficiently although its time complexity is $O(d\cdot m)$. This is because in real-world graphs, most vertices have degrees much smaller than $d$. As a result, the actual runtime of the algorithm often does not reach this worst-case time complexity.

	\begin{algorithm}[!t]
		\caption{\protect \cnred{$G$, $k$, $\theta$}}
		\scriptsize
		\KwIn{Bipartite graph $G=(U,V,E)$, integers $k$ and $\theta$}
		\KwOut{A reduced bipartite graph}
		\label{alg:cnred}
		$\mathcal{O}\leftarrow$ the ascending degree order of $U\cup V$\;
		\For{$u\in \mathcal{O}$} {
			%\lIf{$u\in U(G)$}{$\theta_u\leftarrow \theta_U$; $\theta_v\leftarrow \theta_V$}
