			%Assume $\theta_u$ represents the threshold for $u$'s side, and $\theta_v$ for the other side, between $\theta_U$ and $\theta_V$\;
			\For{$v\in N(u)$} {
				\For{$w\in N(v)$} {
					$cn(w)\leftarrow 0$\;
				}
			}
			\For{$v\in N(u)$} {
				\For{$w\in N(v)$} {
					$cn(w)\leftarrow cn(w)+1$\;
				}
			}
			%$\nu(u)\leftarrow 0$\;
			\For{$v\in N(u)$} {
				$N'\leftarrow \left\{w\in N(v)\mid cn(w)\ge\theta-k\right\}$\;
				%\For{$w\in N(v)$ s.t. $cn(w) \ge \theta_v-k$} {
					%	Mark $u$ and $w$ as compatible\;
					%	$d\leftarrow d+1$\;
					%	\lIf{$d\ge \theta_u-k$}{\Break}
					%}

				\lIf{$\lvert N'\rvert < \theta-k$} {
					$E\leftarrow E\setminus (u,v)$
				}
				%\ElseIf{$\nu(u)\ge \theta_v-k$} {\Break}
			}
			\lIf{$d(u) < \theta-k$} {$U\leftarrow U\setminus u$}
			\lFor{$v\in N(u)$ s.t. $d(v)<\theta-k$} {
				$V\leftarrow V\setminus v$
			}
		}

		\Return{$G$}\;

	\end{algorithm}







