\section{Group actions, orbits, invariants}\label{sect-intro}
%%%%%%
We start with standard and simplest definitions, and then  make adjustments necessary  to work with local smooth  and rational actions. 
%
\begin{definition}[action]\label{def-act}
An  \emph{action}  of a group $\gva$  on a set $\zva$ is a map $\act\colon  \gva \times \zva \to \zva $  satisfying the following properties\footnote{Here, $\cdot$ denotes the  group operation. The abbreviation  $\alpha(\g,\pz)=\g\pz$ is often used in the literature and  we use it in Figure~\ref{fig-rho}.}:

\begin{enumerate}
    \item[i.] \label{ai} \emph{Associativity:}  $ \act(\g_1 \cdot  \g_2, \pz) = \act(\g_1, \act (\g_2, \pz ))$, $\forall \g_1, \g_2\in \gva$  and  $\forall \pz\in \zva$.
\item[ii.]\label{aii} \emph{Action of the identity element:} 	 $\act(e,\pz) = \pz$, $\forall  \pz \in \zva$.  \end{enumerate}


\end{definition}
%%%
\begin{definition}[orbit]\label{def-orb}  The \emph{orbit} of $\pz\in\zva$ under an action $\alpha$ is a set
%%%%
\beq\label{ovaz}\ova_{\pz}=\left\{\apz\in \zva|\exists \g\in\gva:\, \apz=\alpha(\g,\pz)\right\}.\eeq
An  action is called  \emph{transitive} if  $\ova_{\pz}=\zva$ for some (and, therefore, for all) $\pz$. 
\end{definition}
%%
%
Since  orbits partition $\zva$ into equivalence classes, many  classification problems  can be restated as problems of orbit classification.  
%%%%
\begin{example}\label{ex-act-orb}For $\gva =\fld R=\{t\}$, with the addition as the group operation, and $\zva={\fld R}^2=\{(x,y)\}$, consider four actions:
\begin{align}
\label{a1} \act_1(t,(x,y)) &=\left(x +ty, \, y\right),\\
 \label{a2}\act_2(t,(x,y)) &=\left(e^t \,x, \, e^ t \, y\right),\\
\label{a3} \act_3\left(t,(x,y)\right)&=\left(x\cos t-y\sin t, \, x\sin t+y\cos t\right),\\
\label{a4} \act_4(t,(x,y)) &=\left(e^t \,\left(x\cos t-y\sin t\right), \, e^ t \, \left( x\sin t+y\cos t\right)\right) 
 \end{align}
%
Under $\alpha_1$, the orbit of any point on the $x$-axis  is the  point itself and the orbit of any other point is the horizontal line through the point.  Under  $\alpha_2$, the orbit of the origin is the origin itself and the orbit of any other point is the open ray, whose vertex is at the origin, passing through the point.  Under $\alpha_3$,  the orbit of the origin  is the  origin itself and  the orbit of any other point is the circle centered at the origin  passing through the point. Figure~\ref{fig:orb} shows the orbits under these three actions. Drawing the orbits under $\alpha_4$ is left for the reader.
 \end{example}
 %%%%%%
  %%%%
\begin{definition}[stabilizer]\label{def-stab} The \emph{stabilizer} of $\pz\in\zva$ under an action $\alpha$ is the set $\gva_{\pz}=\{\g\in \gva\,|\, \alpha(\g,\pz)=\pz\}$. The action is called \emph{free} if the stabilizer of every point is $\{e\}$.
\end{definition}
%%%%%%%%%%
It is easy to show that $\gva_{\pz}$ is a subgroup\footnote{An alternative terms  used for the stabilizer is the \emph{isotropy group}  of $\pz$.} 
of $\gva$. The intersection $\gva_{\zva}=\cap_{\pz\in \zva} \gva_{\pz}$ is a normal subgroup of $\gva$, called the  \emph{global stabilizer}. The induced action  of the quotient group $\gva\backslash \mathcal \gva_{\zva}$ has the same orbits as the action of $\gva$  and trivial global stabilizer. Actions with trivial global stabilizer are called \emph{effective}.
%%%%
\begin{example} None of the actions in \exr{ex-act-orb} are free. 
For the action $\alpha_3$, the stabilizer of the origin is $\fld R$, while the stabilizer of any other point is  a proper  subgroup  $\mathcal H=\{2\pi n\, |\, n\in \fld Z\}$, which is, therefore, the global stabilizer.  The quotient $\gva\backslash \mathcal H\cong SO_2(\fld R)$ is the special orthogonal group.  The induced action of $SO_2(\fld R)$ is  free away from the origin.
\end{example}
%%%
\begin{definition}[invariants]\label{def-inv} A function $f$ with the domain $\zva$ is called invariant\footnote{Although ``invariant'' here is used as an adjective, it is also often used as a noun. For instance, the  term ``rational invariant'' is often used instead of  ``rational invariant function''.} under an action $\act$ if it is constant along each orbit:
\beq\label{invf}f\left(\alpha (\g,\pz)\right)=f(\pz), \qquad \forall (\g,\pz)\in \gva\times\zva. \eeq
\end{definition}
A constant function on $\zva$ is trivially an invariant for any action, but it is not useful for describing the orbit-space. Ideally, we would like to find an invariant function, or a set of invariant functions,  that takes distinct values  on distinct orbits. Such set is called  \emph{separating}. More, generally: 
%%%
\begin{definition}[separating set]\label{def-sep} Assume $\{\zva_\tau\,|\, \tau\in \mathcal T \}$, where $\mathcal T$ is some index set, is a partition of a set $\zva$:
$$\zva=\displaystyle{\cup_{\tau\in \mathcal T} \zva_\tau} \text{ and  } \zva_{\tau_1}\cap \zva_{\tau_2}=\emptyset, \text{ when } \tau_1\neq\tau_2.$$  A subset $\mathcal F$ of functions on $\zva$ \emph{separates the partition} if for any $\pz_1,\pz_2\in \zva$:
\begin{align*} \exists f\in \mathcal F, \text{ s.t. }f( \pz_1)\neq  f(\pz_2)& \Longleftrightarrow  \\&\exists \tau_1\neq \tau_2\in \mathcal{T} \text{ s.t. } \pz_1\in \zva_{\tau_1} \text{ and }\pz_2\in \zva_{\tau_2}.
\end{align*}
\end{definition}
