\begin{document}

\maketitle

\begin{abstract}
Previous work has shown that the languages recognized by average-hard attention transformers ($\AHAT$s) and softmax-attention transformers ($\SMAT$s) are within the circuit complexity class $\TC^0$.
However, these results assume limited-precision arithmetic: using floating-point numbers with $O(\log n)$ bits (where $n$ is the length of the input string), \citeauthor{strobl2023averagehard} showed that $\AHAT$s can be approximated in $\LOGSPACE$-uniform $\TC^0$, and \citeauthor{merrill-2023-majority} showed that $\SMAT$s can be approximated in $\DLOGTIME$-uniform $\TC^0$.
Here, we improve these results, showing that $\AHAT$s with no approximation, $\SMAT$s with $O(\poly(n))$ bits of floating-point precision, and $\SMAT$s with at most $2^{-O(\poly(n))}$ absolute error are all in $\DLOGTIME$-uniform $\TC^0$.
\end{abstract}

\section{Introduction}

\begin{table}[t]
