\section{Spectral Clustering in the DCH Models}
%\vspace{-5pt}
Let $\b N_T$ be the $n\times n$ matrix whose $(i,j)$th element denotes the number of events that node $i$ sends to node $j$ until time $T$. Recall that we allow node $i$ to send events to itself. The diagonal elements $(\b N_T)_{ii}$ denote the events $i$ sends to itself. We call this asymmetric (due to directed events) and weighted matrix the \emph{count matrix}. 

The first step of our estimation procedure in the DCH models is to obtain the community assignments from the spectral clustering method (described in Algorithm \ref{alg:spectral_clustering}) applied to this count matrix. We derive an upper bound on the error rates of community detection using this method for count matrices generated by a model in the class of DCH models. 
The upper bound is non-asymptotic in $n$ and $T$ and provides explicit dependence on $n$, $T$, and other model quantities. This upper bound then leads to results on consistency of spectral clustering when $T \to \infty$. In order to interpret these dependencies on model quantities better, we obtain the bounds under a simplified special case of the DCH models.


We define the notations $\|\cdot \|_2, \|\cdot \|_{\infty}, \|\cdot \|_{1}, \rho(\cdot)$ to denote the spectral norm, maximum absolute row sum, maximum absolute column sum norm, and the spectral radius of a matrix, respectively, while $\|\cdot \|$ denotes the Euclidean norm of a vector. 


\begin{algorithm}[t]
\caption{Spectral Clustering on the Count Matrix}
\label{alg:spectral_clustering}
\textbf{Input:} Count matrix $\mathbf{N}_T$; number of clusters $K$

\textbf{Output:} Membership vector $\boldsymbol{z}$

\begin{algorithmic}[1]
\State Compute $\mathbf{X}_L, \mathbf{X}_R \in \mathbb{R}^{n \times K}$ as the top $K$ left and right singular vectors of $\mathbf{N}_T$.
\State Form matrix $\mathbf{X} = \left(\mathbf{X}_L \mid \mathbf{X}_R\right) \in \mathbb{R}^{n \times 2K}$ by column-wise concatenation.
\State Define index set $\mathcal{I} = \left\{ i : \| \mathbf{X}_{i\cdot} \| > 0 \right\}$.
\State Extract rows: $\mathbf{X}^+ = (\mathbf{X}_{\mathcal{I}\cdot})$.
\State Normalize rows to unit length: $\mathbf{X}^{+*}_{ij} =\frac{\mathbf{X}^+_{ij}}{\|\mathbf{X}^+_{i,.}\|}$.
\State Apply $(1+\varepsilon)$-approximate $k$-means to rows of $\mathbf{X}^{+*}$ to get $K$ clusters.
\State Assign nodes not in $\mathcal{I}$ to the first cluster.
\State \Return membership vector $\boldsymbol{z}$.
\end{algorithmic}
\end{algorithm}




\subsection{Non-asymptotic Results for General DCH Models}

We adopt a result from \cite{khabou2021malliavin} which provides a Gaussian concentration result for multivariate Hawkes processes using the Malliavin-Stein method in our context in the following proposition. Let $\mathcal{C}^2(\mathbb R^{n^2})$ denote the class of twice differentiable functions of $n^2$ dimensional real vectors. For a function $g \in \mathcal{C}^2(\mathbb R^{n^2})$, define $\|g\|_{Lip}= \sup_{\bm x \neq \bm y}\frac{|g(\bm x)- g(\bm y)|}{\|\bm x-\bm y\|}$, and $M_2(g) = \sup_{\bm x \neq \bm y} \frac{\|\nabla g(\bm x) - \nabla g(\bm y)\|}{\|\bm x-\bm y\|}$, where $\bm x,\bm y \in \mathbb R^{n^2}$. For any vector $\b x$, define the operator $\diag(\b x)$ as an operator that makes a diagonal matrix with the elements of the vector $\b x$. Further define $\b R=(\b I-\b \Gamma)^{-1}$. Then, the following proposition is a consequence of Theorem 1.1 in \cite{khabou2021malliavin}.

\begin{proposition} Define the distance $d_2$ between two random vectors $X$ and $Y$ as 
\[
d_2 (X,Y) = \sup_{f \in \mathcal{H}} |E[f(X)] - E[f(Y)]|,
\]
where  $\mathcal{H} = \{g \in \mathcal{C}^2(R^{n^2}): \|g\|_{Lip} \leq 1, M_2(g) \leq 1\}$. Let $n$ be a fixed quantity that does not change with $T$ and assume $\rho(\b \Gamma) <1$.
Define \[
Y_T = \frac{\operatorname{vec} (\b N_T) - \b R \operatorname{vec} (\b \mu) T}{\sqrt{T}}.
\]
Let $G \sim N_{n^2}(0, \b R \diag (\b R \operatorname{vec}(\b \mu)) \b R^T)$. 
Then there exists a constant $C(n)$ that does not depend on $T$, but possibly depends on $n$, such that 
\[
d_2 (Y_T, G) \leq \frac{C}{\sqrt{T}},
\]
for any $T$.
\label{prop:normal}
\end{proposition}
The above proposition provides a bound for the $d_2$ distance, which has also been called the ``smooth Wasserstein distance'' in the literature \citep{gaunt2023bounding}, between a suitably transformed count vector from a DCH model and a Gaussian vector with an appropriate covariance matrix. Note that, in the above proposition, the $n^2 \times n^2$ covariance matrix of the zero-mean Gaussian vector $G$ does not depend on $T$. Further,  $d_2(Y_T,G) \to 0$ implies that $Y_T$ converges to $G$ in distribution (Remark 6 in \cite{khabou2021malliavin}, Remark 2.16 in \cite{giovanni2010multi}). However, to make further progress on bounding the spectral norm difference of the count matrix from its expection, we require explicit bounds on the Kolmogorov distance between the vectors, $d_K(Y_T,G)$. The following proposition that follows from the result in \cite{gaunt2023bounding} with $m=2$ provides that.   
\begin{proposition}
Suppose $\sigma=\min_{1\leq j\leq n^2} (\b R \diag (\b R \operatorname{vec}(\b \mu)) \b R^T)_{jj}$. We verify that $\sigma>0$ and $d_2(Y_T,G) \leq \frac{\sqrt{4 \log n}+2}{2\sigma}$ for sufficiently large $T$. Then, 
\[
d_K(Y_T,G) \leq 2 \left ( \frac{\sqrt{4 \log n}+2}{\sigma}\right)^{2/3} (4 C(n))^{1/3}T^{-1/6}.
\]
\label{Kdist}
\end{proposition}

Now, we are ready to state our main results. The following theorem provides a bound on the matrix spectral norm of the difference between the count matrix and its expectation as a function of $n$ and $T$. The probability with which the bound holds is a function of $T$, and the bound can be turned into a high probability bound by letting $T \to \infty$.
\begin{theorem}
\label{thm:spectral_norm_bound}
Let $\b N_T$ be the $n \times n$ count matrix of a temporal network generated from a DCH model with parameters $\b \mu, \b \Gamma$. Let $\mu_{\max} = \max_{i,j}\mu_{ij}$. Assume the following. (1) The spectral radius $\rho(\boldsymbol\Gamma) =\sigma^*<1$, 
(2)  For any block pair $(a,b)$, the maximum absolute row and column sums for the submatrices $\b \Gamma_{ab \rightarrow ab}, \b \Gamma_{ab \rightarrow ba}, \b \Gamma_{ba \rightarrow ab}, \b \Gamma_{ba \rightarrow ba}$ are identical and are upper bounded by $\gamma_{\max}>0$ for all $(a,b)$ pairs. 
Define $\E \b N_T = \operatorname{vec}^{-1}\left((\b R\operatorname{vec}(\b \mu)T\right)$.
Then, for all $n>1$ and $T>1$ we have, with probability at least $1-\exp(-\log n \log T)-\frac{\kappa(n)}{T^{1/6}}$, for some $\kappa(n)>0$ which is a function of $n$ but not of $T$,
\[
\sqrt{\frac{T}{\log T}}\left\|\frac{\boldsymbol{N}_{T} -\E \b N_T}{T} \right\| \leq  3(1-\sigma^*)^{-3}\sqrt{n (1 + \gamma_{\max})^3\mu_{\max}(1+2 \log n)} ).
\]
\end{theorem}
The proof of this theorem is given in Appendix \ref{sec11}. The first assumption states that $\rho(\b \Gamma)$, the spectral radius of $\b \Gamma$, is bounded away from 1, which is a necessary condition for the stability of the multivariate Hawkes process. This assumption also ensures the existence of $(\b I - \b \Gamma)^{-1}$.
The second assumption provides control over the amount of dependence in the mutually exciting Hawkes processes. The assumption of identical row and column sums of the submatrices for any block pair is part of the definition of the DCH model as discussed earlier. The parameter $\gamma_{\max}$ upper bounds the total amount of excitation in the conditional intensity function that the node pair $i,j$ can receive from (or send to) all node pairs which exert an influence on it (which consists of all node pairs in block pairs $(a,b)$ and $(b,a)$). The upper bound in the above theorem provides explicit dependence on key model quantities including $n, T, \mu_{\max}$, and $\gamma_{\max}$.



Next, we note that the expected count matrix for the DCH model can be written as a block matrix (which has identical values in the same block).  Note the the matrix $\E \b N_T =\tN=\operatorname{vec}^{-1}\left(\b R\operatorname{vec}(\b \mu)T\right)$.  One can write $ \tN $ as $\Z\B\Z^T$ where $\b Z\in \{0,1\}^{n\times K}$ is as defined before and $\B\in\mathbb{R}^{K\times K}$ is a nonnegative matrix (Theorem 4.1 in \cite{soliman2022multivariate} with the assumptions of the DCH model). The lemma below shows that the column concatenation of singular vectors of $\tN$ can be used to identify the communities.






\begin{lemma}
\label{lem:row_length_X}
For $\tN $ defined above, let $\tN = \t{\b X}_L \b\Lambda \t{\b X}_R^T$ be its singular value decomposition (SVD) where $ \t{\b X}_L, \t{\b X}_R \in \mathbb{R}^{n\times K}$ and $\b \Lambda \in \mathbb{R}^{K\times K}$. Let $\t{\b X} = (\t{\b X}_L|\t{\b X}_R)\in\mathbb{R}^{n\times 2K}$, which is a column concatenation of $\t{\b X}_L$ and $\t{\b X}_R$. Then we have $\t{\b X} = \b Z \b Y$, where $\b Y \in \mathbb{R}^{K\times 2K}$, $\|\b Y_{i\cdot}\| = \sqrt{2n_i^{-1}}$ and $\|{\b Y}_{i\cdot}  - {\b Y}_{j\cdot}\|=\sqrt{2(n_{i}^{-1}+n_{j}^{-1})}$ for any $1\leq i \leq j \leq K$. Moreover, let $\t{\b X}^*$ be the row normalized version of $\t{\b X}$, i.e., ${\t{\b X}}^*_{ij} ={\t{\b X}}_{ij} /  \|\sum_{j} {\t{\b X}}_{ij}\|$. Then $\t{\b X}^*=\b Z\b Y^*$, where $\b Y^*$ is the row normalized version of $\b Y$, and $\|{\b Y}^*_{i\cdot}  - {\b Y}^*_{j\cdot}\|=\sqrt{2}$ for any $1\leq i \leq j \leq K$.
\end{lemma}

The proof of this lemma is given in Appendix \ref{l4proof}. It is clear from Lemma \ref{lem:row_length_X} that $z_i = z_j$ if and only if $\t{\b X}_{i\cdot}^*=\t{\b X}_{j\cdot}^*=\b Y_{z_i\cdot}^*$. Recall $z_i$ gives the community label for $i$ and hence if $z_i=q$, then $\b Y_{z_i\cdot}^*$ denotes the $q$th row of $\b Y^*$. Therefore, applying some clustering algorithm (e.g., k-means) on the rows of the matrix $\t{\b X}^*$ can return a perfect clustering result. However, we cannot get $\t{\b X}^*$ in practice since $\tN$ is not observed. 
A variation of the Davis-Kahan Theorem, which we state  and prove in Appendix \ref{sec:davis_kahan}, lets us derive an upper bound on the misclustering rate if we apply $(1+\varepsilon)$-approximate k-means algorithm (\cite{kumar2004simple}) on the rows of $\t{\b X}^*$. We define the misclustering error rate as 
$r=\inf _{\Pi} \frac{1}{n} \sum_{i=1}^{n} 1\left(z_{i} \neq \Pi\left(\hat{z}_{i}\right)\right)$
where we take the infimum over all permutations $\Pi(\cdot)$ of the community labels. We further define $n_{\max} = \max_{1\leq a\leq K} n_{a}$, the number of nodes in the largest community.  The following theorem is the  main result of this paper.

\begin{theorem}
\label{thm:misclustering_rate}
Let $\b N_T$ be the count matrix of a temporal network generated from a DCH model with parameters $\b \mu, \b \Gamma$. We use $ \lambda_1 \geq \dots \geq \lambda_K >0$ to denote the top $K$ singular values of $\frac{\E{\b N}_T}{T}$. Under the assumptions of Theorem \ref{thm:spectral_norm_bound}, the misclustering rate of community detection using Algorithm \ref{alg:spectral_clustering} applied to $\b N_T$ is
\begin{align*}
%    \begin{split}
        r
        &\leq \left(\frac{\log T}{T}\right) \frac{1440(2+\varepsilon)^2 n_{\max} K}{ \lambda_{K}^{2}}\left( 
        (1-\sigma^*)^{-6} {(1 + \gamma_{\max})^3\mu_{\max}(1+2 \log n)}\right).
        %\\
%    \end{split}
\end{align*}
with probability at least $1-\exp(-\log n \log T)- \frac{\kappa(n)}{T^{1/6}}$ for any $n>K$ and $T>1$.

\end{theorem}


The proof of this theorem is provided in Appendix \ref{t5proof}. The above result provides a scaling for the misclustering rate  that involves $n, K, T$ and the parameter $\gamma_{\max}$, which controls the amount of dependence across pairs of Hawkes processes.  We also note that, while this result is non-asymptotic in $n$ and $T$, we can also let $T \to \infty$, and then the upper bound holds with probability at least $1-o(1)$. In particular, the upper bound implies that $ r \overset{p}{\to}0$ as $T \to \infty$. In order to understand the dependence of the error rate on the model parameters more clearly, we consider a simplified special case of a DCH model next.


%\vspace{-10pt}
\subsection{Results for Specific DCH Models: MULCH,  SR, and CHIP}
\label{sec:simple_mulch}
%\vspace{-5pt}
We define a \textit{simplified symmetric MULCH model (SS-MULCH)}, which is a special case of the MULCH model \citep{soliman2022multivariate} defined in Section \ref{sec:dch_examples} and is part of the DCH class of models. In this SS-MULCH model, the within community parameters are the same and the between community parameters are the same, i.e., for any $1\leq a,b\leq K$ and $a\neq b$,
\begin{equation}
\label{eq:symmetric_general_model}
\begin{split}
M_{aa} = \mu_1, ~\alpha^{n}_{aa} =\alpha^{n}_1,~\alpha^{r}_{aa} =\alpha^{r}_1,~ \alpha^{tc}_{aa} =\alpha^{tc}_1, ~ \alpha^{ac}_{aa} =\alpha^{ac}_1, ~ \alpha^{gr}_{aa} =\alpha^{gr}_1,~ \alpha^{ar}_{aa} =\alpha^{ar}_1,\\
M_{ab} = \mu_2, ~\alpha^{n}_{ab} =\alpha^{n}_2,~\alpha^{r}_{ab} =\alpha^{r}_2,~ \alpha^{tc}_{ab} =\alpha^{tc}_2, ~ \alpha^{ac}_{ab} =\alpha^{ac}_2, ~ \alpha^{gr}_{ab} =\alpha^{gr}_2,~ \alpha^{ar}_{ab} =\alpha^{ar}_2.
\end{split}
\end{equation}
We do not add restrictions on the decay parameters $\beta$ here since it will not influence our results. We assume all blocks are of equal size, i.e., containing  $(n/K)$ nodes. First, from the construction of $\b \Gamma_{n^2 \times n^2}$ matrix, we can infer that, for any $1\leq a\leq K$, the block matrix $\b \Gamma_{(a,a),(a,a)}$ has identical row sum $ \gamma_1$, and for any $1\leq a < b\leq K$, the block matrix $\b \Gamma_{(a,b),(b,a)}$ has identical row sum $ \gamma_2$. Given that every block contains $n_a = \frac{n}{K}$ nodes, a row in $\b \Gamma_{(a,a),(a,a)}$ contains  $n_a^2=(\frac{n}{K})^2$ elements while a row in $\b \Gamma_{(a,b),(b,a)}$ contains $2n_a n_b = 2(\frac{n}{K})^2$ elements. In the SS-MULCH model, we can compute the row sums as follows. The row sum for $\b \Gamma_{(a,a),(a,a)}$ is 
\[
         \gamma_1 = \alpha_1^n + \alpha_1^r +(n^2/K^2-2)(\alpha_1^{ac}+\alpha_1^{tc} +\alpha_1^{gr} + \alpha_1^{ar}),
         \] 
         The row sum for $\b \Gamma_{(a,b),(b,a)}$ is given by 
% \begin{equation*}
\[\gamma_2 
         = \gamma_{ab\rightarrow ab} + \gamma_{ba\rightarrow ab}
        = \alpha_2^n + \alpha_2^r +(n^2/K^2-1)(\alpha_2^{ac}+\alpha_2^{tc} + \alpha_2^{gr}+\alpha_2^{ar}).
        \]
% \end{equation*}

Since $\b \Gamma$ is a block diagonal matrix, we know that $\sigma^* = \rho(\b\Gamma) = \max_{1\leq a\leq b\leq K}\rho(\b \Gamma_{(a,b), (b,a)})$. Then, using Proposition \ref{lem:bound_eig} (in Appendix \ref{sec:props_lemmas}) and noting that the row sums are identical, we can further see that $\rho(\b \Gamma_{(a,a),(a,a)}) = \gamma_1$ and $\rho(\b \Gamma_{(a,b),(b,a)}) = \gamma_2$. Therefore, $ \sigma^*= \max\{ \gamma_1, \gamma_2\}$. By the definition of the $\gamma_{\max}$ in Theorem \ref{thm:spectral_norm_bound}, we note that we can set $\gamma_{\max}$ such that $\max\{ \gamma_1, \frac{\gamma_2}{2}\} \leq \gamma_{\max} \leq \max\{ \gamma_1, \gamma_2\}$. Consequently, $\sigma^*/2 \leq \gamma_{\max} \leq \sigma^*$. In order to ensure stability of the process, we need to further assume $\sigma^* <1$. 
With these results we have the following corollary.

\begin{corollary}
\label{cor:simplified_model_misclustering_error}
For the simplified symmetric MULCH (SS-MULCH) model, under the same assumptions as in Theorem \ref{thm:misclustering_rate}, the misclustering rate is
\begin{align*}
   r \leq  \frac{ cK^2\mu_{\max}\left(1-\sigma^{*}\right)^{-6}\left(1+\gamma_{\max }\right)^3}{((1 -   \gamma_1)^{-1}\mu_1- (1 -   \gamma_2)^{-1}\mu_2)^2} 
    \left(
        \frac{\log T (1+2 \log n)}{nT}  
        \right),
\end{align*}
for a constant $c>0$, with probability at least $1-\exp(-\log n \log T)- \frac{\kappa(n)}{T^{1/6}}$.
\end{corollary}


 Note that since the above relation between $\gamma_{\max}$ and $\sigma^*$ implies that $\sigma^* \leq 2\gamma_{\max}$, assuming $\gamma_{\max}<1/2$ guarantees $\sigma^*<1$ ensuring the stability of the process. With this assumption, $ (1-\sigma^*)^{-1}$ is a constant that does not depend on $n, T$.
  We define a function $
  h(\gamma_1,\gamma_2,\mu_1,\mu_2) = \left( (1-\gamma_1)^{-1} -(1-\gamma_2)^{-1}\frac{\mu_2}{\mu_{1}}\right)^2$. We assume $n$ is large enough that $2 \log n >1$, and without loss of generality assume $\mu_1>\mu_2$ and hence $\mu_{\max}=\mu_1$.
  Then from Corollary \ref{cor:simplified_model_misclustering_error}, we have
\begin{align}
\label{eq:r_simple_symmetric_model}
   r\leq \frac{c (1+\gamma_{\max})^3}{h(\gamma_1,\gamma_2,\mu_1,\mu_2)(1-\sigma^*)^6}\left(\frac{K^2\log n \log T}{ nT\mu_{\max}} \right),
\end{align}
where $c$ absorbs numerical constants that do not depend on model parameters. First we note that $\gamma_{\max}$ which upper bounds the total influence a node pair receives from other node pairs appears in the upper bound. In particular the misclustering rate upper bound increases as $\gamma_{\max}$ increases. If $\gamma_{\max}$ becomes close to 1 and consequently $\sigma^*$ becomes close to 1, then the misclustering rate bound blows up. We note that $r$ also depends on $h(\gamma_1,\gamma_2,\mu_1,\mu_2)$. This means if the expected counts of within and between block are indistinguishable, then the misclustering error rate can be very large. In addition, we note that the upper bound increases quadratically with increasing $K$, and decreases with increasing $n$, $T$, and $\mu_{\max}$. We observe some of these dependencies in our finite sample simulations as well in Section \ref{sec:exp_spectral_clustering}.

Now, turning our attention to asymptotic rates, we let $T \to \infty$, while keeping $n$ fixed. To simplify our presentation and focus on the dependency on $n, K, \mu_{\max}$ and $T$, we assume $h(\gamma_1,\gamma_1,\mu_1,\mu_2)$ does not vanish and is a constant as $T \to \infty$. Then 
\begin{equation}
\label{eq:misclustering_rate_symmetric_general_model}
    r \lesssim \frac{K^2\log n \log T}{ nT\mu_{\max}}, \text{ with probability } 1-o(1).
\end{equation}
Note that the expected density of the count matrix varies as $\mu_{\max}T$ when the jump and decay parameters remain constant as a function of $T$. Therefore, consistent clustering requires $\mu_{\max} >> (\frac{K^2 \log n }{n}) \frac{\log T}{T}$. 


Notice that in this model, the parameters are ``symmetric" because the parameters for directed block pair $(a,b)$ are the same as the parameters for directed block pair $(b,a)$ (i.e., $\mu_{ab} = \mu_{ab}, \b\alpha_{ab} = \b\alpha_{ba}$, where $\b \alpha_{ab} = \{\alpha_{ab}^n,\alpha_{ab}^r,\alpha_{ab}^{ac},\alpha_{ab}^{tc},\alpha_{ab}^{gr},\alpha_{ab}^{ar}\}$), and hence we must let $\gamma_{\max}  < 1$ to ensure the stability condition ($ \sigma^*<1$) in our discussion above. However, in the ``asymmetric" case, we can have $\gamma_{\max} > 1$. However, in that case $\t{ \lambda}_K$ will have a more complicated form than the result used in Corollary \ref{cor:simplified_model_misclustering_error}. 

Consider a subset of the SS-MULCH model that only consists of self excitation and reciprocal excitation; that is, $\alpha_i^{tc} =\alpha_i^{ac}=\alpha_i^{gr}=\alpha_i^{ar}=0$ for $i=1,2$. 
It is thus a simplified symmetric case of the SR model we introduced in Section \ref{sec:sr_model}. 
Then we have $\gamma_1 = \alpha_{1}^n + \alpha_{1}^r, \gamma_2=\alpha^{n}_2+\alpha^{r}_2$. As long as $\max\{\gamma_1, \gamma_2\} <1$, the result in \eqref{eq:r_simple_symmetric_model} holds and provides an upper bound on the misclustering rate in this case.

\paragraph{Comparison with Prior Results on CHIP Model:}
The CHIP model \citep{arastuie2020chip} only involves self excitation, which also satisfies our conditions, so our results can still be applied on it directly.  
 Unlike \cite{arastuie2020chip}, our results in this paper are non-asymptotic and hold for all $n$ and $T$. While \cite{arastuie2020chip} relied on asymptotic convergence of (univariate) Hawkes process counts to Gaussian limits as $T \to \infty$, we achieve non-asymptotic results by explicitly obtaining a form of the probability with which our upper bound holds. Further, in the DCH models, including MULCH and SR, we allow for more excitation types, so the entries in the count matrix can be dependent, and thus, our misclustering error rate is more general.  The form of the result in \eqref{eq:r_simple_symmetric_model} in terms of dependencies on $n$ and $T$ also qualitatively matches the upper bound for spectral clustering on multilayer and discrete time SBM, e.g., as in \cite{lei2022bias} and \citet{paul2020spectral}.                                   

\paragraph{Relation to Community Detection in Weighted Networks:} We note that, in many application settings involving static networks, the network edges are weighted and directed counts. We put forth the proposed DCH model as a statistical generative model for such ``count" networks. Even though the DCH model is a statistical model for ``observed" relational events data, it can be thought of as an implicit generative model in situations when only a static network with the counts are observed.  Our theoretical results in Theorems \ref{thm:spectral_norm_bound} and \ref{thm:misclustering_rate} and the discussions in this section provide useful indicators of the accuracy of spectral clustering for a weighted network.





%\vspace{-10pt}
\section{Parameter Estimation in the Restricted SR Model}
\label{sec:gmm_estimation}
%\vspace{-10pt}
For the models in the DCH family, the parameters can be estimated from the event times by maximizing the multivariate Hawkes process log likelihood function. However, directly maximizing the likelihood function is slow and hard to scale to large datasets. For some simpler models within the DCH family, it is possible to develop estimators based on the Generalized Method of Moments (GMM) approach using relatively lower-order moments of the aggregate counts. This approach might not be appropriate for more complex models that require higher-order moments since the higher-order sample moments are highly unstable. However, a researcher might be willing to trade off model fit with computational efficiency. 
For example, \cite{arastuie2020chip} propose a moment-based estimator for the baseline parameters $\b M$ and jump parameters $\b \Gamma$ in the CHIP model, which utilizes only self excitation.

We develop a GMM procedure for the restricted version of the SR model proposed in Section \ref{sec:restricted_sr}, which shares a reciprocal excitation parameter $\alpha_{ab}^r$ between block pairs $(a,b)$ and $(b,a)$.
The GMM for this restricted SR model can efficiently and accurately estimate $\b M$ and $\b \Gamma$, so that we only need to maximize the likelihood function if we want to estimate the decay parameters $\b \beta$. Therefore, the GMM step reduces the parameter dimension when maximizing the likelihood function, making the algorithm faster.

\cite{achab2017uncovering} proposed a GMM method for multivariate Hawkes processes. 
Our method and theoretical results below differ from those of \cite{achab2017uncovering} in terms of the information utilized to compute the sample moments. While \cite{achab2017uncovering}'s method estimates the parameters from a single multivariate Hawkes process by estimating sample mean and covariance from the count time series, we leverage i.i.d.~replicates of bivariate Hawkes processes at the level of node pairs in a block pair to estimate those quantities. Therefore, our results are of a different nature.  Further, while \cite{achab2017uncovering} \textit{assumed} the identification condition (Assumption 1 in Theorem 2.1) necessary for GMM procedure to work, we explicitly \textit{prove} it under the restricted SR model in Lemma \ref{lem:id}. In general, one needs to verify that for a multivariate Hawkes process the identification condition will be satisfied by the parameters of the process. We view that not all models under the DCH family will satisfy the identification condition, and therefore, the GMM is not feasible for all models. However, as we show in Lemma \ref{lem:id}, the restricted SR model satisfies the conditions.


In the restricted SR model defined in Section \ref{sec:restricted_sr}, for block pairs $(a,b)$ and $(b,a)$ with $a\neq b$, we have the following set of unknown baseline and excitation parameters:  $M_{ab},M_{ba}, \alpha^n_{ab}, \alpha^n_{ba},\alpha^r_{ab}$.
Recall that $\operatorname{vec}(\b N_t)\in \mathbb{R}^{n^2}$ is the vector form of the count matrix  at time $t$ ordered according to the set $\mathcal{A}$.
From the results of \cite{achab2017uncovering}, for node pairs $(i,j)$  in $\mathcal{A}$, we can define the first and second order integrated cumulants by 
\[\Lambda_{ij} \, d t =\mathbb{E}\left(d  (\b N_{t})_{ij}\right)\]
and 
\[C_{ij,ji} \, d t =\int_{\tau \in \mathbb{R}}(\mathbb{E}\left(d (\b N_{t})_{ij} \; d (\b N_{t+\tau})_{ji}\right)-\mathbb{E}\left(d (\b N_{t})_{ij}\right) \mathbb{E}(d (\b N_{t+\tau})_{ji})),\]
where $\b \Lambda$ is the mean intensity of the Hawkes process, and $\b C$ is the integrated covariance density. \cite{achab2017uncovering} showed that there is an explicit relationship between these integrated cumulants and the parameters of the multivariate Hawkes process. 


In the restricted SR model, we have the following cumulant relationship equations for the block pair parameters. Define 
\begin{equation*}
\b M_{(a,b),(b,a)}=\begin{pmatrix}
M_{ab}  \\
M_{ba} \\
\end{pmatrix}
\text{ and }
\,\b \Gamma_{(a,b),(b,a)} = \begin{pmatrix}
\alpha^n_{ab} & \alpha^r_{ab} \\
\alpha^r_{ab} & \alpha^n_{ba} \\
\end{pmatrix}.     
\end{equation*}
Clearly, estimating the parameters of the SR model is equivalent to estimating the parameter matrices $\b M$ and $\b \Gamma$ for all $(a,b), (b, a)$ pairs.

Define $\b R_{(a,b),(b,a)} = \left(\b I_{2 \times 2} -\b \Gamma_{(a,b),(b,a)}\right)^{-1}.$ Then, for any $(i,j)$ such that $X(i,j)=(a,b)$, we abuse notation slightly to let $\Lambda_{ij}=\Lambda_{ab}$ and $C_{ij,ji}=C_{ab,ba}$ and write the following relations for the $(i,j)$ and $(j,i)$ node pairs together:
\begin{gather}
\b \Lambda_{(a,b),(b,a)} = \left(\begin{array}{l}
\Lambda_{ab} \\
\Lambda_{ba}
\end{array}\right)= \b R_{(a,b),(b,a)} \b M_{(a,b),(b,a)}, \label{eqlambda}\\
\b C_{(a,b),(b,a)}=\begin{pmatrix}
C_{ab,ab} & C_{ab,ba} \\
C_{ba,ab} & C_{ba,ba} \\
\end{pmatrix}
= \b R_{(a,b),(b,a)} \text{ diag}(\b \Lambda_{(a,b),(b,a)})\b  R_{(a,b),(b,a)}^T.
\label{eqC}
\end{gather}



Therefore, for each block pair $(a,b),(b,a)$, if we can estimate the population cumulants $\b \Lambda_{(a,b),(b,a)}$ and $\b C_{(a,b),(b,a)}$, then we can solve the above set of equations and solve for $\b M_{(a,b),(b,a)}$ and $\b \Gamma_{(a,b),(b,a)}$. This estimation method is widely known as the Generalized Method of Moments (GMM) \citep{hall2004generalized}. Recall that, for each block pair $(a,b),(b,a)$, we observe a collection of bivariate counting processes given by $\{(\b N_t)_{ij}: t \in [0,T], X(i,j)=(a,b)\}$. Then, we define the corresponding sample moments as follows:
\begin{equation}
\label{eq:GMM_sample_statistics}
\begin{gathered}
\widehat{\Lambda}_{ab}=  \sum_{X(i,j)=(a,b) } \frac{(\b N_T)_{ij}}{Tn_{ab}}, \quad \quad 
\widehat{\Lambda}_{ba}=  \sum_{X(i,j)=(b,a) } \frac{(\b N_T)_{ij}}{Tn_{ab}}, \\
\widehat{C}_{ab,ab} =\sum_{X(i,j)=(a,b) } \frac{1}{Tn_{ab}}\left((\b N_T)_{ij} - \widehat{\Lambda}_{ab}\right)^2,\\
\widehat{C}_{ba,ba} =\sum_{X(i,j)=(b,a) } \frac{1}{Tn_{ab}}\left((\b N_T)_{ij} - \widehat{\Lambda}_{ba}\right)^2,\\
\widehat{C}_{ba,ab}=\widehat{C}_{ab,ba}=\sum_{X(i,j)=(a,b)}   \frac{1}{Tn_{ab}}\left((\b N_T)_{ij} - \widehat{\Lambda}_{ab}\right)\left((\b N_T)_{ji} - \widehat{\Lambda}_{ba}\right).\\
\end{gathered}
\end{equation}
Here, $n_{ab}=n_a n_b$ is the number of pairs of nodes with one node being in community $a$ and the other node in community $b$. Note that, unlike the method in \cite{achab2017uncovering}, the above sample moments only uses aggregate counts at time $T$ and takes sample means over $n_{ab}$ pairs of Hawkes processes. 

Solving the cumulant relationship equations directly may be difficult, so we use a least squares method to solve it. We define the function $\b g_n(\b N, \b M_{(a,b),(b,a)}, \b \Gamma_{(a,b),(b,a)} ) \in \mathbb{R}^{5}$ such that the components are defined as
\begin{gather*}    g_{n1}(\cdot,\cdot,\cdot)   =  \Lambda_{ab} - \widehat \Lambda_{ab},  \quad 
    g_{n2}(\cdot,\cdot,\cdot) =  \Lambda_{ba} - \widehat \Lambda_{ba}, \\  
    g_{n3}(\cdot,\cdot,\cdot)   =  C_{ab,ab} - \widehat C_{ab,ab},\quad
    g_{n4}(\cdot,\cdot,\cdot)  =  C_{ba,ba} - \widehat C_{ba,ba},\quad
    g_{n5}(\cdot,\cdot,\cdot) = C_{ab,ba} - \widehat C_{ab,ba}.
\end{gather*}
Then, our GMM estimator $(\h{\b M}_{(a,b),(b,a)}, \h{\b \Gamma}_{(a,b),(b,a)})$ is the minimizer of the following optimization problem:
\begin{equation}
\label{eq:GMM_minization}
\underset{\b \Theta_{(a,b),(b,a)}}{\min}
    \b  g_n(\b N, \b M_{(a,b),(b,a)}, \b \Gamma_{(a,b),(b,a)} )^T \b g_n(\b N, \b M_{(a,b),(b,a)}, \b \Gamma_{(a,b),(b,a)} ),
\end{equation}
where $\b \Theta_{(a,b),(b,a)} $ is the feasible parameter space in the restricted SR model given by
\begin{align}
\label{eq:restricted_SR_feasible_set}
\bigg \{\b M_{(a,b),(b,a)}, \b \Gamma_{(a,b),(b,a)} : \rho({\b G}_{(a,b),(b,a)})\leq \sigma^*<1, M_{ab},M_{ba} >0,\! \text{ and }  \alpha^n_{ab}, \alpha^n_{ba},\alpha^r_{ab} \geq 0  \bigg \}.
\end{align}
Here, $\rho({\b \Gamma}_{(a,b),(b,a)})\leq \sigma^*<1$ is the stability condition as defined before. For notational convenience, henceforth we will use $\b \theta$ to denote $\b M$ and $\b \Gamma$ together.  

\subsection{Results for the Restricted SR Model}
\label{sec:sr_theory}
For the restricted SR model, we can explicitly state the stability condition in terms the parameters of the model as below:
\begin{lemma}
\label{lem:stability}
(Stability condition for the restricted SR model) The restricted SR model is stable if, for any block pair $(a,b)$, the $\b \Gamma_{(a,b),(b,a)}$ matrix has spectral radius $\rho\left(\b \Gamma_{(a,b),(b,a)}\right) < 1$, which is equivalent to $\alpha^n_{ab}  \leq \sigma^*< 1, \alpha^n_{ba} \leq \sigma^*<1$, and $\alpha^r_{ab} \leq \sigma^*<\sqrt{ {(\sigma^*-\alpha^n_{ab})(\sigma^*-\alpha^n_{ba})}}$.
\end{lemma}




Let $\b \theta_0 = \{\b M_0, \b \Gamma_0\} \in \b \Theta$ be the true parameters. Further, let  $\b g_0 (\b \Theta)$ be the population version of the GMM function defined in \eqref{eq:GMM_sample_statistics} obtained by replacing $\hat{\b \Lambda}$ with $\b \Lambda_0$ and $\hat{\b C}$ with $\b C_0$, where $\b \Lambda_0$ and $\b C_0$ are in turn obtained from \eqref{eqlambda} and \eqref{eqC} with $\b M_0$ and $\b \Gamma_0$. The next lemma shows that the true parameter can be identified from this population function $\b g_0$.
\begin{lemma}
\label{lem:id}
    (Identification result) For the restricted SR model, $\b g_0(\b \theta)=\b 0$ if and only if $\b \theta = \b \theta_0$  for all block pairs $(a,b)$.
\end{lemma}

Next, we show that the GMM estimator will converge in probability to the true parameters under an asymptotic regime where $T\rightarrow \infty$ and $n_{ab}\rightarrow \infty$ for any block pair $(a,b)$. Note that our procedure leverages the availability of event counts from $n_{ab}$ bivariate Hawkes processes to construct the sample moments, and hence, our asymptotic framework is in terms of both increasing $T$ and $n_{ab}$. However, we emphasize that we do not require the Hawkes process counts to converge to a limiting Gaussian distribution, which may not hold for growing dimension Hawkes processes or simultaneously for infinitely many bivariate Hawkes processes unless $T$ grows much faster than the dimension or number of Hawkes processes.  Since the parameters are estimated by block pair, we prove the result for any generic block pair $(a,b)$. 
(We switch notation to use superscripts to denote block pairs when we also have the subscript $0$ to denote the true parameter, e.g., ${\b M}_{0}^{(a,b),(b,a)}$.)
The theorem is proved in Section \ref{sec:app_gmm_proofs} by verifying the sufficient conditions laid out in \cite{newey1994large} for the GMM estimator to be consistent.

\begin{theorem}
\label{thm:gmm}
Consider any block pair $(a,b)$ in the restricted SR model. Let the parameter space $\b \Theta_{(a,b),(b,a)}$ defined in \eqref{eq:restricted_SR_feasible_set} be compact and contain the true parameters ${\b M}_{0}^{(a,b),(b,a)}$, $\b \Gamma_{0}^{(a,b),(b,a)}$. Then the estimator $(\h{\b M}_{(a,b),(b,a)}, \h{\b \Gamma}_{(a,b),(b,a)})$ defined in \eqref{eq:GMM_minization} will converge to the true parameters
in probability as $T\rightarrow \infty$ and $n_{ab}\rightarrow \infty$.
\end{theorem}

Notice that the dimension of parameters in each block is 5, which is equal to the dimension of $\b g$, so it is possible that $\b g_0(\b \theta_0)=0$ has a unique solution. 
In Lemma \ref{lem:id}, we show that to be the case for the restricted SR model. For the unrestricted SR model and the MULCH model, which have more parameters, this estimating procedure with just the first two moments cannot ensure a unique solution. For those models, an alternative is to consider higher order cumulants as in \cite{achab2017uncovering}. However, the estimators of higher order cumulants may have large variance, and thus, the final estimation from the GMM procedure might be less accurate. Further, it is not immediately clear if the identification condition similar to our Lemma \ref{lem:id}, which the results of \cite{achab2017uncovering} require to hold for a given multivariate Hawkes process, will hold for unrestricted SR or MULCH models.



%\vspace{-10pt}

\subsection[Estimating beta and Local Likelihood Refinement]{Estimating $\b \beta$ and Local Likelihood Refinement}
\label{sec:refinement}
After the $\b \Gamma$ parameters are estimated from the GMM procedure described above, we can estimate $\b \beta$ by maximum likelihood, if desired. 
(An alternative to estimating $\b \beta$ is to assume fixed $\b \beta$ \citep{bacry2015hawkes} or a weighted sum of multiple $\b \beta$ values, as in MULCH and other similar temporal network models \citep{soliman2022multivariate, yang2017decoupling, huang2022mutually}.) 
If we are estimating $\b \beta$, we plug in the GMM estimates of $\b \Gamma$ into the likelihood equation. The likelihood now becomes a function only of $\b \beta$, which is then estimated through maximum likelihood.

We also propose a local likelihood refinement algorithm for the SR model to further improve the community detection and parameter estimation accuracy given the initial estimates of the community assignments and the parameters. Similar procedures are used in the SBMs \citep{gao2017achieving,chen2022global} and Hawkes process network models \citep{junuthula2019block,soliman2022multivariate} literature for obtaining an improved community assignment after the spectral clustering. However, in densely dependent settings, e.g., the MULCH model \citep{soliman2022multivariate}, it is nearly impossible to implement the refinement algorithm on a large dataset due the computational limitation. In contrast, in the SR model, we are able to write the change in log likelihood due to one refinement step in a computationally efficient manner, and consequently, the refinement algorithm can be scaled to large datasets.

The refinement procedure for node $i$ utilizes the initial community assignments \textit{for all other nodes} and Hawkes process parameter estimates to compute the likelihood of node $i$ belonging to the different blocks. Then we assign the node to the block which maximizes the likelihood. We start with the first node (arbitrary order) and repeat this procedure until community assignment of all nodes have been refined. Finally, we re-estimate the parameters using the new community assignment. The full refinement procedure is summarized in Algorithm \ref{algrefine}.
In the SR model, computing the likelihood for node $i$ given the community assignment of all other nodes only involves computing Hawkes process likelihood for events from $i$ and to $i$. Therefore, this computation includes a very small amount of events and thus it is computationally efficient and practical. 
%In practice, we can run the refinement algorithm multiple times to get better results.



% \captionlistentry{}
% \label{alg:spectral_clustering}
%
\begin{algorithm}[t]
\caption{Local refinement procedure to update community assignments in the SR model. For the restricted SR model, set $\alpha_{ba}^r = \alpha_{ab}^r$ and $\beta_{ba}^r = \beta_{ab}^r$.}
\label{algrefine}
\textbf{Input:} Events time data $\b{E}$; number of blocks $K$; initial Hawkes process parameters $\boldsymbol{\Theta} = (\boldsymbol{M}, \boldsymbol{\alpha}, \boldsymbol{\beta})$; initial community assignment $\boldsymbol{z}$

\textbf{Output:} New membership vector $\boldsymbol{z}$; new Hawkes process parameters $\boldsymbol{\Theta}$

\begin{algorithmic}[1]
\For{each node $i$}
    \State Update membership $z_i$ by:
    \begin{align*}
    z_i &= \argmax_{a \in \{1,\dots,K\}} \sum_{b=1}^K \sum_{\substack{j:z_j=b \\ j\neq i}} \bigg\{
    - M_{ab}T - M_{ba}T \\
    &- \sum_{t_s \in T_{ij}} \left[\alpha_{ab}^{n}\left(1-e^{-\beta^n_{ab}(T-t_s)}\right) + \alpha_{ba}^{r}\left(1-e^{-\beta^r_{ba}(T-t_s)}\right) \right] \\
    &- \sum_{t_s \in T_{ji}} \left[\alpha_{ab}^{r}\left(1-e^{-\beta^r_{ab}(T-t_s)}\right) + \alpha_{ba}^{n}\left(1-e^{-\beta^n_{ba}(T-t_s)}\right)\right] \\
    &+ \sum_{t_s \in T_{ij}} \ln\left[M_{ab} + \alpha_{ab}^{n}\beta^n_{ab} R^{ij \rightarrow ij}_{ab,n}(t_s)
    + \alpha_{ab}^{r}\beta^r_{ab} R^{ji \rightarrow ij}_{ab,r}(t_s)\right] \\
    &+ \sum_{t_s \in T_{ji}} \ln\left[\mu_{ba} + \alpha_{ba}^{n}\beta^n_{ba} R^{ji \rightarrow ji}_{ba,n}(t_s)
    + \alpha_{ba}^{r}\beta^r_{ba} R^{ij \rightarrow ji}_{ba,r}(t_s)\right]
    \bigg\}
    \end{align*}
where $ R^{ij \rightarrow ij}_{ab,n}(t_s) = \sum_{\substack{t_r \in T_{ij}\\ t_r < t_s}} e^{-\beta^n_{ab}(t_s - t_r)}, \quad 
        R^{ji \rightarrow ij}_{ab,r}(t_s) = \sum_{\substack{t_r \in T_{ji}\\ t_r < t_s}} e^{-\beta^r_{ab}(t_s - t_r)}$, and $R^{ji \rightarrow ji}_{ba,n}(t_s)$, $R^{ij \rightarrow ji}_{ba,r}(t_s)$ are defined similarly.
\EndFor
\State Use updated $\boldsymbol{z}$ to re-estimate Hawkes parameters $\boldsymbol{\Theta}$ via GMM and MLE.
\State \Return updated $\boldsymbol{z}$ and $\boldsymbol{\Theta}$
\end{algorithmic}
\end{algorithm}



