\section{Proof of \Cref{thm:FullB_Ctrl_Guarantee}} \label{app:FullB_Ctrl_Guarantee}
    By construction in \Cref{alg:LI_Schedule_FullB}, the elements of set $\calT^{(i)}$ corresponds to linearly independent columns in matrix $\begin{bmatrix}
    \matA^{K-1}\matB & \matA^{K-2}\matB & \ldots & \matA^{i}\matB
\end{bmatrix}$. To ensure controllability, i.e., $\rank{\matR_{\calG_0}}=n$, we need to prove that $\lv \calT^{(0)} \rv = n$ and it is enough to prove the required result for the case of $K = \lceil \frac{n}{s}\rceil$. To this end, it suffices to show that $\lv \calT^{(1)} \rv \geq n-s$ since $\rank{\matB}=n$. The remaining $s$ elements can then be added to $\calT^{(0)}$, corresponding to linearly independent columns from $\matB$, thereby making $\lv \calT^{(0)} \rv = n$. Furthermore, in \Cref{alg:LI_Schedule_FullB}, the number of linearly independent columns selected until any iteration index $i$~is (See \Cref{prop:MaxLIColumns})
    \begin{equation}
        %\lv \calT^{(K-1)} \rv = \min\lc \rank{\matA^{K-1}\matB},s \rc, \\
        %\lv \calT^{(K-2)} \rv = \min\lc \rank{\matA^{K-2}\matB},s+\lv \calT^{(K-1)} \rv \rc, \\
        %\text{Similarly, } 
        \lv \calT^{(i)} \rv = \min \lc \rank{\matA^{i}\matB}, \lv \calT^{(i+1)} \rv + s \rc.
    \end{equation}
    This is because we only add linearly independent columns in each iteration and $\lv \calI(i) \rv = l(i)$.

    Rewriting $\lv\calT^{(i)}\rv$ using above recursive relation, we get %the following
    \begin{multline}
        \lv\calT^{(i)}\rv = \min \{ \rank{\matA^i\matB}, \rank{\matA^{i+1}\matB}+s \\ ,\ldots, \rank{\matA^{K-1}\matB}+(K-i-1)s, (K-i)s \}.
    \end{multline}
    Therefore, for $i=1$, we have %the following
    \begin{multline} \label{eq:T1Cardinality}
        \lv\calT^{(1)}\rv = \min \{ \rank{\matA\matB}, \rank{\matA^{2}\matB}+s ,\ldots, \\ \rank{\matA^{j}\matB}+(j-1)s,\ldots, \\ \rank{\matA^{K-1}\matB}+(K-2)s, (K-1)s \}.
    \end{multline}
    Now, to establish that $ \lv\calT^{(1)}\rv\geq n-s$, it is enough to show that each term inside the minimum operator in \eqref{eq:T1Cardinality} is at least $n-s$. Starting with the last term $(K-1)s$, we have
    \begin{equation} \label{eq:MinInputGuarantee}
        \lb K-1 \rb s = \lb \left \lceil\frac{n}{s}\right\rceil - 1\rb s \geq n-s. 
    \end{equation}
    Now, we show that the remaining terms in \eqref{eq:T1Cardinality} are at least $n-s$. We use Sylvester's rank inequality
    %\begin{equation*}
      %  $\rank{\matX\matY} \geq \rank{\matY} + \rank{\matX} - n$
    %\end{equation*}
   % with $\matX = \matA$, $\matY = \matA^{i-1}\matB$ and for any $i \geq 1$, 
   to arrive at
    \begin{equation}
        \rank{\matA^i\matB} \geq \rank{\matA^{i-1}\matB} + \rank{\matA} - n.
    \end{equation}
    Since $s \geq \rank{\matA} - n$, we have
    \begin{equation} \label{eq:AkBinequality}
        \rank{\matA^i\matB} \geq \rank{\matA^{i-1}\matB} - s.
    \end{equation}
    Applying \eqref{eq:AkBinequality} recursively $i-2$ times, we derive
    \begin{equation}
        \rank{\matA^i\matB} \geq \rank{\matA\matB} - (i-1)s.
    \end{equation}
    Finally, since $\rank{\matA\matB} = \rank{\matA}$ and $\rank{\matA} \geq n-s$, we deduce that
    \begin{equation} \label{eq:AkB_Lower_Bnd}
        \rank{\matA^i\matB} + (i-1)s \geq n-s.
    \end{equation}

    Combining \eqref{eq:AkB_Lower_Bnd}, \eqref{eq:MinInputGuarantee} and \eqref{eq:T1Cardinality}, we get $\lv \calT^{(1)} \rv \geq n-s$. Hence, $\lv\calT^{(0)}\rv=n$, or  $\rank{\matR_{\calG_0}}=n$, completing the proof. \hfill \qedb

