\section{Proof of \Cref{thm:noise_algo_guarantee}}
\label{app:KF_based_alg}
We define $\vecd(k) = \vecx(k) - \vecx_f$. Our goal is to obtain an upper bound on $\bbE \{ \lVert \vecd (k) \rVert^2 \}$. First, from \eqref{eq:state_noise}, we have 
\begin{equation}
 \vecd(k) %&=  \matA \vecx(k-1)  + \matB \vecu(k-1) - \vecx_f + \vecv(k-1)\\
% \begin{split}
     \!=\! \matA \hat{\vecx}(k-1) \!+\! \matB \vecu(k-1) \!-\! \vecx_f \!+\! \matA\vecz(k-1) \!+\! \vecv(k-1),
 %\end{split}
\end{equation}
where $\hat{\vecx}(k)$ is the Kalman filter based estimate as defined in \Cref{line:kalman_est} of \Cref{alg:sparse_control_noise} and the state error $\vecz(k) \triangleq \vecx(k) - \hat{\vecx}(k)$. Since the noise $\vecv(k-1)$ has zero mean and is independent of all the other terms, taking the expectation of $\lV \vecd(k) \rV^2$ over $\{\vecv(i), \vecw(i)\}_{i=0}^{k-1}$, we derive
\begin{multline}\label{eq:step1}
 \mathbb{E} \lc \Vert \vecd(k) \Vert^2\rc = \mathbb{E} \lc\Vert \matA \hat{\vecx}(k-1) + \matB \vecu(k-1) - \vecx_f \Vert^2 \rc \\
 + 2\mathbb{E} \lc\lb \matA \hat{\vecx}(k-1) + \matB \vecu(k-1)\rb^{\T}  \matA \vecz(k-1)\rc \\- 
2\mathbb{E} \lc \vecx_f^{\T} \matA \vecz(k-1)\rc + \mathbb{E} \lc\Vert \matA \vecz(k-1) \Vert^2 \rc + \trace{\bs{\Sigma}_v}.
\end{multline}
We now analyze each of the terms on the right-hand side. We observe that, as the process and measurement noises are Gaussian, $\lc\vecx(i),\vecy(i)\rc_{i=1}^{k}$ is jointly Gaussian. Hence, the Kalman filter yields MMSE estimates. So, we deduce %the following
\begin{align} \label{eq:zero_bias}
    \bbE \lc\vecz(k-1)\rc = \zero, \quad \bbE \lc \vecz(k-1)|\lc\vecy(i)\rc_{i=1}^{k-1} \rc = \zero.
\end{align}
This observation allows us to deal with all the terms in \eqref{eq:step1} that are linear in $\vecz(k-1)$. Since $\vecx_f$ and $\matA$ are deterministic, from \eqref{eq:zero_bias}, we have
\begin{equation}\label{eq:step1_sub1}
   \mathbb{E} \lc \vecx_f^{\T} \matA \vecz(k-1)\rc=\vecx_f^{\T}\matA\mathbb{E} \lc \vecz(k-1)\rc=\zero.
\end{equation}
Further, we note that $\matA \hat{\vecx}(k-1) + \matB \vecu(k-1)$ is a function of the past measurements $\vecy(i)$, $i=1,2,\ldots,k-1$, and again from \eqref{eq:zero_bias}, the following term equals $\zero$,
\begin{multline*}
    \mathbb{E} \lc\lb\matA \hat{\vecx}(k-1) + \matB \vecu(k-1) \rb^{\T} \matA \vecz(k-1)\rc = \\
    \mathbb{E} \!\lc\!\lb\matA \hat{\vecx}(k-1) \!+\! \matB \vecu(k-1) \rb^{\T}\!\matA\mathbb{E}\! \lc \vecz(k-1)|\!\lc\vecy(i)\rc_{i=1}^{k-1}\!\rc\!\rc\!.
\end{multline*}
Combining \eqref{eq:step1_sub1} and the above, we simplify \eqref{eq:step1} as
\begin{multline}
 \mathbb{E} \lc \Vert \vecd(k) \Vert^2\rc = \mathbb{E} \lc\Vert \matA \hat{\vecx}(k-1) + \matB \vecu(k-1) - \vecx_f \Vert^2 \rc \\
 + \mathbb{E} \lc\Vert \matA \vecz(k-1) \Vert^2 \rc + \trace{\bs{\Sigma}_v}.\label{eq:step_main1}
\end{multline}
Next, we simplify the first term of the above equation using the exponentially decaying property of the residual norm of the OMP algorithm in \eqref{eq:omp_guarantee} as follows:
\begin{align} 
    &\mathbb{E} \lc\Vert \matA \hat{\vecx}(k-1) + \matB \vecu(k-1) - \vecx_f \Vert^2 \rc  \notag \\
    &\leq  \xi^s(\matB) \mathbb{E} \lc \Vert \matA \hat{\vecx}(k-1) - \vecx_f \Vert^2 \rc\\
    %&=\xi^s(\matB)\mathbb{E} \lc \Vert \matA \vecx(k-1) - \vecx_f - \matA \vecz(k-1)\Vert^2 \rc,\notag\\
    &= \xi^s(\matB)\mathbb{E} \lc \Vert \matA \vecx(k-1) \!-\! \vecx_f \Vert^2 \rc\! +\! \xi^s(\matB)\mathbb{E}\lc \Vert \matA \vecz(k\!-\!1) \Vert^2 \!\rc\notag \notag \\
    &\quad+ 2\xi^s(\matB)\mathbb{E}\lc \vecx(k-1)^{\T} \matA^{\T} \matA \vecz(k-1) \rc,\label{eq:step3}
\end{align}
which follows from \eqref{eq:step1_sub1}. Using $\vecx(k-1)=\vecd(k-1)+\vecx_f$,% yields
\begin{multline}
    \mathbb{E}\! \lc \Vert \matA \vecx(k-1) - \vecx_f \Vert^2 \rc \!=\! \mathbb{E} \!\lc \Vert \matA \vecd(k-1) +\matA\vecx_f - \vecx_f \Vert^2\rc \\
    \leq 2\Vert \matA \Vert^2\mathbb{E} \lc \Vert\vecd(k-1)\Vert^2\rc +2\Vert\matA\vecx_f - \vecx_f \Vert^2,\label{eq:step3_sub1}
\end{multline}
due to the Cauchy-Schwarz inequality. Similarly, using $\vecx(k-1)= \hat{\vecx}(k-1)+\vecz(k-1)$, we rewrite the last term of \eqref{eq:step3} as
\begin{align}
\mathbb{E}\lc \vecx(k-1)^{\T} \matA^{\T} \matA \vecz(k-1) \rc %\notag\\
%&\hspace{-4cm}= \mathbb{E}\lc \hat{\vecx}(k-1)^{\T} \matA^{\T} \matA \vecz(k-1) \rc+ \mathbb{E}\lc \Vert \matA \vecz(k-1) \Vert^2 \rc,\notag\\
%&\hspace{-4cm}
=  \mathbb{E}\lc \Vert \matA \vecz(k-1) \Vert^2 \rc.\label{eq:step3_sub2}
\end{align}
where the last step is due to \eqref{eq:zero_bias}. Combining \eqref{eq:step_main1}, \eqref{eq:step3}, \eqref{eq:step3_sub1}, and \eqref{eq:step3_sub2}, and defining $\chi = 2 \xi^{s}(\matB) \Vert \matA \Vert^2$, we arrive at
\begin{align}
 \mathbb{E} \lc \Vert \vecd(k) \Vert^2\rc \notag\\
 &\hspace{-1.8cm}\leq \chi\mathbb{E} \lc \Vert\vecd(k-1)\Vert^2\rc
 +(1+ 3\xi^s(\matB))\mathbb{E}\lc \Vert \matA \vecz(k-1) \Vert^2\rc\notag\\
 &+ 2\xi^s(\matB)\Vert\matA\vecx_f - \vecx_f \Vert^2+\trace{\bs{\Sigma}_v},\\
 & \hspace{-1.8cm}= \chi^k  \Vert \vecd(0) \Vert^2+ \lb1 + 3\xi^s(\matB) \rb\sum_{i=0}^{k-1}  \chi^{k-i-1}  \mathbb{E} \Vert \matA \vecz(i) \Vert^2\notag\\
 & \hspace{-1.5cm} +\sum_{i=1}^k \chi^{i-1} \ls 2 \xi^s(\matB)\Vert \matA \vecx_f - \vecx_f \Vert^2+ \trace{\bs{\Sigma}_v}  \rs.
\label{eq:recus_sum_expansion}
\end{align}
We note that $\chi < 1$ since $s \geq \max\{ -\frac{\log(2\Vert \matA \Vert^2)}{\log(\xi(\matB))}, 0 \}$ by assumption. So, the first term of \eqref{eq:recus_sum_expansion} is a decreasing function of $k$, which is lower bounded by 0. Hence, we can always find an integer $k_1$ such that
\begin{equation} \label{eq:bound_1}
\chi^{k} \Vert \vecd(0) \Vert^2  \leq \frac{\eta}{3},
\end{equation}
for all $k \geq k_1$. 
%If $\vecx(0)$ is unknown and drawn from Gaussian distribution we will have $\mathbb{E} \Vert \vecd(0) \Vert^2$. We have $\vecz(0)=\zero$ if $\vecx(0)$ is known, as $\hat{\vecx}(0)=\vecx(0)$. 
Also, for the second term of \eqref{eq:recus_sum_expansion}, we note that 
\begin{equation}\label{eq:az_norm}
    \mathbb{E} \Vert \matA \vecz(i) \Vert^2 = \trace{\matA \matP_i \matA^{\T} } .
\end{equation}
Substituting \eqref{eq:bound_1} and \eqref{eq:az_norm} into \eqref{eq:recus_sum_expansion} gives
\begin{multline}\label{eq:bound_last}
    \hspace{-5mm}\mathbb{E} \lc \Vert \vecd(k) \Vert^2\rc <  \frac{\eta}{3}+ \lb1 + 3\xi^s(\matB) \rb\sum_{i=0}^{k-1}  \chi^{k-i-1}  \trace{\matA \matP_i \matA^{\T} }\\
 +\frac{ 2 \xi^s(\matB)\Vert \matA \vecx_f - \vecx_f \Vert^2+ \trace{\bs{\Sigma}_v} }{1-2 \xi^{s}(\matB) \Vert \matA \Vert^2},
\end{multline}
where we use the property that, for any integers $0\leq i_i\leq i_f$, 
\begin{equation}\label{eq:gp_prop}
    \sum_{i=i_i}^{i_f} \chi^{i} <\sum_{i=0}^{\infty} \chi^{i} = \frac{1}{1-\chi},
\end{equation}
because $0<\chi<1$. Now, to establish the desired bound in \eqref{eq:noise_algo_guarantee}, it remains analyze the second term in~\eqref{eq:bound_last}. To this end, we use \eqref{eq:KF_cnvg_1} and \eqref{eq:KF_cnvg_2}  to obtain $\lim_{i\to\infty}\matP_i=\matP$. The limit $\matP$ exists when the system $(\matA,\bs{\Sigma}_v^{1/2},\matC)$ is controllable and observable. Hence, we can find an integer $k_2$ satisfying 
 \begin{equation}\label{eq:bound_2}
     \trace{\matA \matP_i \matA^{\T} } < \trace{\matA \matP \matA^{\T} }+ \frac{\eta(1-\chi)}{3(1+\xi^s(\matB)) },
 \end{equation}
 for all  $i \geq k_{2}$. Therefore, for $k>k_2$, the second term of \eqref{eq:bound_last} simplifies as follows:
\begin{align}
\sum_{i=0}^{k-1} \chi^{k-i-1} \trace{\matA \matP_i \matA^{\T}}  \notag\\
&\hspace{-3.8cm}\leq\!\sum_{i=0}^{k_2-1}   \chi^{k-i-1}  \trace{\!\matA \matP_i \matA^{\T}\!} \!+ \max_{i\geq k_2} \trace{\!\matA \matP_i \matA^{\T}\!} \!\sum_{i = k_2}^{k-1} \!\chi^{k-i-1} \nonumber \\
&\hspace{-3.8cm}\leq \!\sum_{i=0}^{k_2-1}   \chi^{k-i-1}  \trace{\!\matA \matP_i \matA^{\T}\!} \!+\frac{\trace{\!\matA \matP \matA^{\T}\!}}{1- \chi} + \frac{\eta}{3(1+\xi^s(\matB)) },\label{eq:step4_sub3}
\end{align}
due to \eqref{eq:gp_prop} and \eqref{eq:bound_2}. Next, we use $\chi < 1$ to choose an integer $k_3>k_2$ such that
\begin{equation*}
    \chi^{k_3-k_2}\sum_{i=0}^{k_2-1}  \chi^{k_2-i-1}  
\trace{\matA \matP_i \matA^{\T}} < \frac{\eta }{3\lb1+3\xi^s(\matB)\rb}. 
\end{equation*}
Hence, for all $k>k_3$, we bound the first term of \eqref{eq:step4_sub3} as
\begin{multline}
\sum_{i=0}^{k_2-1}  \chi^{k-i-1}  \trace{\matA \matP_i \matA^{\T}}\leq \sum_{i=0}^{k_2-1}   \chi^{k_3-i-1}  \trace{\matA \matP_i \matA^{\T}}  \\
< \frac{\eta }{3\lb1+3\xi^s(\matB)\rb}.\label{eq:step4_sub4}
\end{multline}
Now \eqref{eq:step4_sub3} and \eqref{eq:step4_sub4} jointly lead to
\begin{multline}\label{eq:Az_norm_bound}
    \lb1 + 3\xi^s(\matB) \rb\sum_{i=0}^{k-1}  \chi^{k-i-1}  \trace{\matA \matP_i \matA^{\T}}\\
    <\frac{1 + 3\xi^s(\matB)}{1-  2\xi^s(\matB) \Vert \matA \Vert^2 }\trace{\matA \matP \matA^{\T}} +\frac{2\eta }{3}.
\end{multline}
Combining \eqref{eq:bound_last} and \eqref{eq:Az_norm_bound}, we arrive at \eqref{eq:noise_algo_guarantee}.  Hence, the proof is complete.
 \hfill \qedb

