\section{Code for scatterers} \label{apx:scatter}
MATLAB code for producing each of the scatterers used in our examples is supplied below. We use Chebfun~\cite{Chebfun} because it nicely handles the computation derivatives and normal directions, as well as plotting, in subsequent stages. All code used in our experiments, including a gallery command for scatterers, can be found at~\cite{TFAW}. 

\begin{enumerate}

    \item smooth C-curves (as in \Cref{fig:c_curveplots}): 
     \begin{verbatim}
a = 3;      % bigger = sharper corners
b = 2.8;    % smaller = narrower cavity opening
c = .1;     % larger = fatter all around
d = 1;      % rotation parameter

t = chebfun('t', [0, 2*pi]);
r = 3+c*tanh(a*cos(t));
th = b*sin(t);

gam = d*exp(1i*th).*r;

    \end{verbatim}
\item Crescents (as in \Cref{fig:crescent}):
    \begin{verbatim}
r = 5;              % size param
th = exp(1i*pi/2);  % angle param
p = 1i;            % relative shift
a1 = .24; a2 = .9;  % crescent shape params
d = 3;             % controls distance between crescents

t = chebfun('t', [0, pi],'splitting','on');
cres = @(t) exp(-2i*t)- a1/(exp(-2i*t)+a2) + d/2; % displaced crescent

gam = cres(t);
gam = join(gam+p, -cres(pi+t));
gam = r*th*gam;

    \end{verbatim} 
\item Keyhole domain (as in \Cref{fig:poleplot} and \Cref{fig:cornerskey}): 
    \begin{verbatim}
r = 2;      % inner rad
R = 3;      % outer rad
e = .3;     % thickness param
theta = pi; % controls rotation
c = [-R+e*1i -r+e*1i -r-e*1i -R-e*1i];

t = chebfun('t',[0 2*pi/4],'splitting','on');
l = @(t,a,b) a + (t/(2*pi)*4)*(b-a); % line segment
circ = @(t,a,b) a.^(1 - t/(2*pi)*4) .* b.^(t/(2*pi)*4); % circle segment

gam = join(l(t,c(1),c(2)),circ(t,c(2),c(3)),l(t,c(3),c(4)),circ(t,c(4),c(1)));
gam = exp(1i*(pi+theta)) * gam;

    \end{verbatim}      
\item Radiator domain (as in \Cref{fig:gasket_magplots} and bottom row of \Cref{fig:cornersrad}):
    \begin{verbatim}
% Define parameters
r = 1.5;            % radii small circs.
R = 5;              % radius large outer circ.
e = .8;
outr = .8;
deltatheta = .15;
n = 6-1;            % n-1 = number of sm. circs. 
Btheta = 5*pi/4;    % controls rotations

% Define inner smaller circle centers
thetastilde = 2 * (0:n) * pi / (n+1); 
thetas = [thetastilde(thetastilde >= pi),thetastilde(thetastilde < pi)];

centers = (R + r) / 2 * exp(1i * thetas); 

% Remove center point at -(R+r)/2
thetas(real(centers) == -(R + r)/2) = [];
centers(real(centers) == -(R + r)/2) = [];
n = length(centers);

% Define main keyhole points
c = [-R - e*1i, -r - e*1i];
for i1 = 1 : n
    theta = thetas(i1);
    cent = centers(i1);
    c = [c,r*exp((theta-deltatheta)*1i),cent +...
    outr * exp((theta+r/outr*deltatheta+pi)*1i),cent +...
    outr * exp((theta-r/outr*deltatheta+pi)*1i),...
    r*exp((theta+deltatheta)*1i)];
end

c = [c, -r + e*1i, -R + e*1i];
NN = length(c);
a = 2*pi/NN;

% Define parameter for curve
t = chebfun('t', [0, a], 'splitting', 'on');
l = @(t,c1,c2) c1 + (t/a)*(c2-c1); % line segment
circ1 = @(t,c1,c2) c1.^(1 - t/a) .* c2.^(t/a); % circle segment
circ2 = @(t,c,th) c + outr * exp(1i * ((1 - t/a) * th(1) + (t/a) * th(2)));

gam1 = l(t,c(1),c(2));
for i1 = 2:4:(length(c)-4)
    gam1 = join(gam1, circ1(t,c(i1),c(i1+1)));
    gam1 = join(gam1, l(t,c(i1+1),c(i1+2)));

    cent = centers(ceil(i1/4));
    angle_start = angle(c(i1+2) - cent);
    angle_end = angle(c(i1+3) - cent);
    if abs(angle_end-angle_start)<pi
        angle_end = angle_end + 2*pi;
    end
    angles = [angle_start,angle_end];

    gam1 = join(gam1, circ2(t,cent,angles));
    gam1 = join(gam1, l(t,c(i1+3),c(i1+4)));

end

gam1 = join(gam1, circ1(t,c(end-2),c(end-1)));
gam1 = join(gam1, l(t,c(end-1),c(end)));
gam1 = join(gam1, circ1(t,c(end),c(1)));

tfull = chebfun('t', [0, 2*pi], 'splitting', 'on');
gam = exp(1i*(pi+Btheta))*gam1(2*pi-tfull);
\end{verbatim}
\end{enumerate}








