\section{Derivation of eq. (\ref{eq_eps_mean_var})}\label{sect_appendix_proof}

Here we assume the function $v(t, x)$ is sufficiently smooth with converging Taylor series.
We also assume that $ \lVert \eta \rVert \ll 1$, which has high probability when $\Delta t \ll 1$.

In the third-order Taylor series of $\epsilon \Delta t$ at $(t, x)$, terms with an odd order of $\eta$ are canceled out.
It follows that
\begin{align}
\begin{split}
    \varepsilon ={}&{} \left( \frac{1}{2}\partial_{tt}v + \frac{1}{2} \mu^T \nabla\nabla v \mu + \mu^T \nabla \partial_t v \right) \Delta t^2 + \\
    {}&{}+ \left( \frac{1}{2} \eta^T \sigma^T \nabla \nabla v \sigma \eta - \frac{1}{2} \mathrm{Tr}[\sigma \sigma^T \nabla \nabla v] \Delta t \right) \\
    {}&{} + \left( \frac{1}{6} \partial_{ttt} v + \frac{1}{2}\mu^T \nabla \partial_{tt} v + \frac{1}{2} \mu^T \nabla \nabla \partial_t v \mu \right) \Delta t^3 \\
    {} & {} + \frac{1}{2} \eta^T \sigma^T \nabla \nabla \partial_t v \sigma \eta \Delta t \\
    {}&{} + tail_4 \\
    :={}&{} e_1 + e_2 + e_3 + e_4 + tail_4.
\end{split}
\end{align}
The terms $e_1$ and $e_3$ are deterministic.
For the term $e_2$, let $\delta = \Delta t^{-1/2} \eta$, and $H = \sigma^T \nabla \nabla v \sigma$.
Diagonalize the real matrix $H$ with an orthogonal matrix $U$ by
\begin{equation}
H = U^T \Sigma_H U, \quad \Sigma_H = \mathrm{diag}(\sigma_H^1, \cdots, \sigma_H^d), \quad U^T = U^{-1}.
\end{equation}
Then, $U \delta \sim \mathcal{N}(0, I_d)$, and one can easily tell that
\begin{equation}
\mathbb{E}\left[ \frac{\Delta t}{2} \delta^T H \delta \right] = \frac{\Delta t}{2} \mathrm{Tr}[H], \quad
\mathrm{Var}\left( \frac{\Delta t}{2} \delta^T H \delta \right) = \frac{\Delta t^2}{2} \mathrm{Tr}[H^2],
\end{equation}
so
\begin{equation}
    \mathbb{E}[e_2] = 0, \quad \mathrm{Var}(e_2) = \frac{1}{2} \mathrm{Tr}[(\sigma^T \nabla \nabla v \sigma)^2] \Delta t^2.
\end{equation}
Similarly for $e_4$,
\begin{equation}
    \mathbb{E}[e_4] = \frac{1}{2} \mathrm{Tr} [\sigma^T \nabla \nabla \partial_t v \sigma] \Delta t^2,\quad 
    \mathrm{Var}(e_4) = \frac{1}{2} \mathrm{Tr} [(\sigma^T \nabla \nabla \partial_t v \sigma)^2] \Delta t^4.
\end{equation}
For the $tail_4$ term, it is straightforward that
\begin{equation}
    tail_4 = \mathcal{O}(\Delta t^4 + \lVert x^+ - x \rVert^4 + \lVert x^- - x \rVert^4 ) = \mathcal{O}( \Delta t^4 + \lVert \mu \Delta t \rVert^4 + \lVert \sigma \eta \rVert^4),
\end{equation}
so
\begin{equation}
    \mathbb{E}[tail_4] = \mathcal{O}(\Delta t^2), \quad \mathrm{Var}(tail_4) = \mathcal{O}(\Delta t^4).
\end{equation}
In summary,
\begin{equation}
    \mathbb{E}[\varepsilon \Delta t] = \mathbb{E}[e_1] + \cdots + \mathbb{E}[e_4] + \mathbb{E}[tail_4] = \mathcal{O}(\Delta t^2),
\end{equation}
and
\begin{equation}
    \mathrm{Var}(\varepsilon \Delta t) \le 5 \left( \mathrm{Var}(e_1) + \cdots + \mathrm{Var}(e_4) + \mathrm{Var}(tail_4) \right) = \mathcal{O}(\Delta t^2).
\end{equation}
As $\Delta t \to 0$, the variance of $\varepsilon \Delta t$ is dominated by the contribution of the term $e_2$.

