\section{Proofs from Section \ref{sec:DefRevDef}}


The proof of Lemma \ref{lem:wcycle} relies on the following results from \cite{AlankoDPP21}:
\begin{theorem}[{\cite[Theorem 4.3]{AlankoDPP21}}]\label{th:Wheeler} Let $\La$ be a regular language   and let $\mt D_\La$ be its minimum trimmed DFA. Then  $\La\not \in \Wh(\preceq)$ if and only if all of the following hold:
\begin{enumerate}
    \item there exists a pair of equally-labeled   cycles $\mt C_p, \mt C_q$ (say labeled by $\gamma \in \Sigma^+$) in $\mt D_\La$  starting respectively from  states $p\neq q$;
    \item there exist two words $\alpha, \beta$ with $\alpha\in I_p, \beta\in I_q $ such that $\gamma$ is not a suffix of $\alpha $ and  $\gamma$ is not a suffix of $\beta$;
\item   either $\alpha, \beta \prec \gamma$ or $\gamma \prec \alpha, \beta$. 
\end{enumerate}
\end{theorem}

\begin{lemma*}[\ref{lem:wcycle}]  
  Let $\La$ be a regular language,   let $\preceq$ be an order of the alphabet, and let  $\mt D_\La$ be the minimum trimmed DFA accepting $\La$. Then, 
    $\La\notin \Wh(\preceq)$ if and only if $\mt D_\La^2$ contains a cycle $(p_1, q_1) \rightarrow
    (p_2, q_2) \rightarrow \cdots \rightarrow (p_k, q_k) \rightarrow (p_1, q_1)$ such that
 the following hold: (i) $p_1 \neq q_1$, and (ii) $p_1 \intro  q_1$.
 \end{lemma*}

 \begin{proof}
  Suppose $\La$ is not  Wheeler w.r.t. $\preceq$. Then, by Theorem \ref{th:Wheeler} there are:  
\begin{enumerate}
    \item a  pair of equally labeled   cycles $\mt C_p, \mt C_q$ (say labeled by $\gamma$) in $\mt D_\La$  starting starting respectively from  states $p\neq q$;
    \item two words $\alpha, \beta$ with $\alpha\in I_p, \beta\in I_q $ such that $\gamma$ is not a suffix of $\alpha $ or $\beta$;
\item   either $\alpha, \beta \prec \gamma$ or $\gamma \prec \alpha, \beta$. 
\end{enumerate} Let $p_1=p,q_1=q$ and consider the $\gamma$-cycle       $(p_1, q_1) \rightarrow
    (p_2, q_2) \rightarrow \cdots \rightarrow (p_k, q_k) \rightarrow (p_1, q_1)$  in $\mt D_\La^2$.
Then it is   sufficient to prove that  $p_1\intro q_1$. 
Suppose w.l.o.g. that $\alpha\prec \beta$. If 
  $\alpha, \beta \prec \gamma$ then $\alpha\gamma, \alpha \gamma^2\in I_{p_1}$, $\beta \gamma \in I_{q_1}$ and $\alpha\gamma \prec\beta\gamma$ while  $\beta\gamma\prec \alpha \gamma^2$.   If $\gamma \prec \alpha, \beta$ then 
  $\beta\gamma, \beta\gamma^2\in I_{q_1}$, $\alpha\gamma \in I_{p_1}$ and 
  $\beta\gamma\succ \alpha\gamma$ and $\alpha\gamma  \succ \beta\gamma^2$ (the last disequality holds because $\gamma $  is not a suffix of $\alpha$).
Hence in both cases we obtain   $p_1\intro q_1$. 

\medskip

Suppose now that we have two states $p_1\neq q_1$ with  $p_1\intro q_1$  in $\mt D_\La$  from which two   cycles labeled by the same word $\gamma$ start.  From  $p_1\intro q_1$ we know that there are $\alpha, \alpha'\in I_{p_1}$, $\beta, \beta'\in I_{q_1}$ with $\alpha \prec \beta $ and $\beta'\prec \alpha'$. By using a power of $\gamma$, if necessary, we may suppose that $\gamma$ is not a suffix of $\alpha, \beta, \alpha', \beta'$. If $\gamma \prec \alpha$  or $\alpha'\prec \gamma$ then the conditions of Theorem \ref{th:Wheeler}    are satisfied (with $\alpha', \beta'$ playing the role of $\alpha, \beta$ in the second case).
Otherwise, we have $\alpha \prec \alpha'$. Then, either  $\beta\prec \gamma$ or   $\gamma \prec \beta$ holds. In the first case we have $\alpha,  \beta \prec \gamma$ while in the second case we have $\gamma \prec \beta, \alpha'$, so that, in both cases we fulfill the  conditions of Theorem ~\ref{th:Wheeler}. 
\end{proof}


\begin{lemma*}[\ref{lem:3cycles}]
    If the minimum trimmed automaton $\mt D_\La$ of a language $\La$ contains three equally labeled cycles starting from three different states, then $\La\not \in \EW$.
\end{lemma*}
\begin{proof} Suppose $\mt D_\La$ contains three different states $p,q,r$ which are the starting point  of three   cycles labeled by the same word $\gamma$. Let $\zeta_1, \zeta_2,\zeta_3$ be words reaching $p,q,r$ from the starting state. Using a power of $\gamma$, if necessary, we may suppose that $\gamma$ is not a suffix of   $\zeta_i$, for all $i=1,2,3$. 
     Fix an arbitrary order $\preceq$ of the alphabet. Then  
  there must be two indices $i,j\in \{1,2,3\}$ such that $\zeta_i,\zeta_j$ are either both bigger or both smaller than 
 $\gamma$. By Theorem ~\ref{th:Wheeler},  we have   $\La\not \in \Wh(\preceq)$ and by the generality of the choice of $\preceq$ it follows $\La\notin \EW$.
\end{proof}

 \begin{lemma*}[\ref{lem:Sigma^*}] 
  $\La\in \DEF$   iff  $\La$ is finite,  or  $\La\in \UW$ and  $\pf\La=\Sigma^*$.   
\end{lemma*}

\begin{proof} 
If $\La\in \DEF$ then $L=F \cup \Sigma^*G$ for finite sets $F,G$.  Hence, $\pf\La=\Sigma^*$ if $\La$ is not finite. Moreover, $\La\in \UW$ by Lemma~\ref{lem:slt_are_uw} as definite languages are strictly locally testable.  

Conversely, suppose that $\La$ is finite or  $\La\in \UW$ and $\pf\La=\Sigma^*$. If $\La$ is finite then $\La\in \DEF$  and we are done. 
If $\La\in \UW$ and $\pf\La=\Sigma^*$, consider the minimum    automaton  $\mt D_\La=(Q,q_0, \dots)$ recognizing $\La$. Since $\pf\La=\Sigma^*$, the automaton $\mt D_\La$ is complete and   trimmed. We first prove that $\La\in \SLT$. Suppose, by way of a contradiction, that this is not the case. Then, by   Lemma~\ref{lem:caron},  we have that $\mt D_\La$ contains two states $p\neq q$ which are both the starting point of a cycle labeled by a string $\delta\in \Sigma^+$. Let $\alpha\neq  \beta$ be words reaching $p,q$ from the initial state, respectively. If $k$ is such that     $|\delta^k|>|\alpha|, |\beta|$, we are sure  that     no power of $\delta^k$ is  a suffix of    $\alpha$ or  $ \beta $.

Let $\gamma=\delta^k$ and consider the sequence $q_0,q_1,q_2, \dots, q_i, \dots$   that we obtain,  in $\mt D_\La$, reading the powers of $\gamma$ starting from the initial state
\[q_0 \rightarrow ^\gamma q_1 \rightarrow ^\gamma q_2  \rightarrow^\gamma \dots \rightarrow^\gamma q_i  \rightarrow^\gamma\dots \rightarrow^\gamma q_j  \rightarrow^\gamma\dots \]
(here we are using the hypothesis $\pf\La=\Sigma^*$: this path has to be in $\mt D_\La$).
 Then, there exist $i, j$ with $i<j$ such that $q_i=q_j$.  
 Notice that   $\rho=\gamma^{j-i}$ labels   cycles from the states $p,q$ and $r=q_i$;   if $\nu=\gamma^i$, by using an higher power of $\gamma$ if necessary, we may suppose that  $\rho$ is not a suffix of $\nu$. 
%Notice that $\nu\neq \alpha, \beta$ since, by construction, no power of $\gamma$ is  a suffix of    $\alpha$ or  $ \beta $.

 We now consider two cases:
 \begin{enumerate}
     \item $r\neq p, r\neq q$.   In this case  we have three       cycles labeled $\rho$ starting from      three different  $\mt D_\La$-states $p,q,r$.  By Lemma~\ref{lem:3cycles} we obtain     $\La\notin \EW$, contradicting $\La\in \UW$.   

 \item $r=p$ or $r=q$. Suppose w.l.o.g. that $r=p$.  In this case we have that $\nu=\gamma^i$ reaches $r$  and, since  $\rho$ is a bigger power of $\gamma $,    $\nu$ is always co-lexicographically smaller than $ \rho$ w.r.t. any order of the alphabet. Moreover, we know that $\rho$ is  not a suffix of $\beta$. This implies that we can always find an order $\preceq$ of the alphabet such that $\beta\prec \rho$: if $\beta$ is not  a suffix of $\rho$  (otherwise we already have $\beta \prec \rho$) then,  since $\rho$ is not a suffix of $\beta$ either,   we may consider       the first letters  $x,y$ from the right in $\beta, \rho$, respectively,   marking a difference between the two words;  we may then consider an order $\preceq$ having  $x\prec y$ in order to obtain $\beta\prec \rho$ and $\nu\prec \rho$ (the last one always holds).  

 Hence, we have two states $r,p$  which are both the starting point of a cycle labeled $\rho$ and are reached by strings smaller than $\rho$. This implies $\La\not \in \Wh(\preceq)$, contradicting $\La\in \UW$.
 \end{enumerate}



This proves that  $\La\in \SLT$, hence, there are  finite sets $H,K,W,F$ such that 
 \[\La=F\cup \left [(H\Sigma^* \cap \Sigma^* K) \setminus \Sigma^* W \Sigma^*\right ]. \]
 We now prove that, since $\pf\La=\Sigma^*$, we have $\La\in \DEF$.
 We have that  $\epsilon \not \in W$, otherwise $ \Sigma^* W \Sigma^*=\Sigma^*$, and  $L=F$ would be  a finite set, contradicting $\pf\La=\Sigma^*$.

To conclude the proof  we   check that  $\epsilon \in H$  (so that $H\Sigma^*=\Sigma^*$) and $W=\emptyset$. 
 Since    $\La\subseteq F \cup  H\Sigma^*$, all words in $\La$ which are longer than $\max\Set{|\alpha|}{\alpha \in F}$  must have have a prefix in the finite set $H$, contradicting $\pf\La=\Sigma^*$ unless $\epsilon \in H$.
Suppose, by way of a contradiction, that    $\xi \in W$, and     consider a word $\beta$, longer than $\max\Set{|\alpha|}{\alpha \in F}$, such that   $\beta$ contains $\xi$ as a prefix. Hence,  $\beta \in W\Sigma^*$ and, since $\pf\La=\Sigma^*$, there exists  $\delta\in \Sigma^*$ such that $ \beta\delta \in \La$. However, since $ \beta\delta \not \in F$ (it is too long), we should  have $ \beta \delta \not \in  \Sigma^* W \Sigma^*$,   contradicting  $\beta \in W\Sigma^*$.
Hence, $W=\emptyset$ and  $ \La=F\cup  \Sigma^* K\in  \DEF$.   
\end{proof}


\begin{lemma*}[\ref{lemma:esiste}]
Let  $|\Sigma|\geq 2$ and let  $\La\in \UW$. If $\pf\La\neq \Sigma^*$, the following are equivalent:
\begin{enumerate}
    \item there exists an order $\preceq$ such that $\overline \La\not \in \Wh(\preceq)$;
\item   $ \pf\La\cap \pf{\overline\La}$ is an infinite set. 
   \end{enumerate}
\end{lemma*}
\begin{proof}
    ($1\Rightarrow 2$)~If there exists an order $\preceq$ such that $\overline \La\not \in \Wh(\preceq)$ but  $\La\in \UW$, then, in particular, $\La\in \Wh(\preceq)$.
    Since $\overline \La\not \in \Wh(\preceq)$, then  $\overline \La\not \in \SLT$. By Lemma~\ref{lem:caron}, $\mt  D_{\overline \La}$   must contain two equally labeled cycles (say, with label    $\gamma$) starting from two different states $p,q$. 
    One of them, say $p$, must be different from  the absorbing state $\overline q$ for $\overline \La$ (see the discussion on minimum complete or trimmed DFA for a language and its complement). Since     all words arriving in   $p$ are in $\pf\La\cap \pf{\overline\La}$,  we have  
      $\alpha \gamma^* \in \pf\La\cap \pf{\overline\La}$ and     $ \pf\La\cap \pf{\overline\La}$ is infinite.
%\item 

($2\Rightarrow 1$)~Suppose  $ \pf\La\cap \pf{\overline\La}$ is infinite.   Since  $\pf\La \neq \Sigma^* $ implies  
$\pf{\overline\La} \setminus \pf\La \neq \emptyset $, in $\mt D_{\overline \La} $ 
there is an absorbing final state $\overline q$. Let  $\beta$ be a word arriving in $\overline q$ in $\mt D_{\overline \La} $.  From the hypothesis we get that 
$\beta \neq \epsilon$ (otherwise $\overline {\La}=\Sigma^*$ would  contradict $ \pf\La\cap \pf{\overline\La}\neq \emptyset$),  and, since $ \pf\La\cap \pf{\overline\La}$ is infinite,    in $\mt D_{\overline {\La}}$ there must be   a cycle not passing through $\overline q$.  Let $p\neq \overline q$ be on this cycle,    $\alpha$  be a word arriving in $p$,   and  $\gamma\neq \epsilon$ be a label of  a  cycle starting from $p$ and avoiding $\overline q$. 
We may suppose w.l.o.g.\ that $\gamma$ is not a suffix of $\alpha$ (if so, just consider a power of $\gamma$ instead of $\gamma$). Notice that there is a cycle labeled $\gamma$ both from $p$ and from $\overline q$ ($\overline q$ is an absorbing state, hence there are cycles starting from $\overline q$ labeled by any word).

We claim  that there exists an alphabet order $\preceq$ such that $p\intro \overline q$.
Consider two cases:
\begin{enumerate}
 \item $\alpha \dashv \gamma$. Let  $g$ be the last letter of $\gamma$ and let  $x\in \Sigma$ with  $x\neq g$. Fix an order $\preceq $ of the alphabet such that $x\prec g$.  Since   $\alpha$ arrives in $p$  and $ \beta x$ arrives in $\overline q$   we have either $\alpha \prec \beta x$ or $\alpha \succ \beta x$. In the first case,   we may consider the words
$\alpha \prec \beta x \prec  \alpha \gamma$, while if $\alpha \succ \beta x$  
we may consider the words
$\beta x \prec \alpha \prec \beta x \gamma$.
In both cases the words witness that $p\intro \overline q$.
\item $\alpha \not \dashv \gamma$. Then there is an order $\preceq$ of the alphabet such that $ \gamma\prec \alpha$ holds. If $\preceq$ is such an order, then, since we already supposed $\gamma \not \dashv \alpha$,  we have $\beta \gamma \prec \alpha \prec \beta \alpha$, witnessing $p\intro \overline q$.
 \end{enumerate}
 This proves the claim. Since a cycle labeled $\gamma$ starts from both $p$ and $\overline q$,   in $\mt D^2_{\overline \La} $ there is a cycle starting from $(p,\overline q)$, with $p\neq \overline q$ and $p\intro \overline q$, and Lemma~\ref{lem:wcycle} applied to $\overline \La$ yields 
 $\overline \La\not \in \Wh(\preceq)$.  
 %\end{enumerate} 
 \end{proof}


