\begin{lemma*} [\ref{lem:Pgeq2}]   
    Let $p, q \in Q$ with $p \neq q$. Then, $p \intr q$ if and only if $|P[p, q]| \geq 2$.
\end{lemma*}
\begin{proof}
    $(\Rightarrow)$ If $p \intr q$, then there exists an order $\preceq$ and strings $\alpha, \alpha' \in I_p$ and
    $\beta, \beta' \in I_q$ such that $\alpha \prec \beta$ and $\beta' \prec \alpha'$.
    If $\alpha$ is a suffix of $\beta$, then $(\dashv, \dashv) \in P[p, q]$. Otherwise, there exist 
    $a, b \in \Sigma$, with $a \prec b$, and a string $\gamma \in \Sigma^*$ such that $a\gamma \dashv \alpha$ and $b\gamma \dashv \beta$, and thus $(a, b) \in P[p,q]$. Similarly, for $\beta' \prec \alpha'$ we have either 
    $(\vdash, \vdash) \in P[p,q]$ or there exists  $a', b' \in \Sigma$, with $b' \prec a'$  and $(a', b')$ in $P[p, q]$. Furthermore, if such $a,b,a',b'$ exists, we must have $(a,b) \neq (a',b')$ because  
    $a \prec b$ and $b' \prec a'$. Hence, $|P[p,q]| \geq 2$.



$(\Leftarrow)$   Let $(a, b) \neq (a',b')$ be two elements in $P[p, q]$. 
Suppose  $\{(a, b), (a',b')\}\cap\{(\dashv, \dashv)\}=\emptyset$.  One of the pairs, say $(a,b)$,  must be different from $(\vdash, \vdash)$.   

  If $(a',b')=(\vdash, \vdash)$, then  any total order $\preceq$ on $\Sigma$ for which $a \prec b$ is such that 
 $p \intro q$. Otherwise, any total order $\preceq$ on $\Sigma$ for which $a \prec b$ and $b' \prec a'$ is such that 
 $p \intro q$. Similarly, if  $\{(a, b), (a',b')\}\cap\{(\vdash, \vdash)\}=\emptyset$ then there exists $\preceq$ such that         $p \intro q$.
Finally, if  $\{(a, b), (a',b')\}=\{(\dashv, \dashv), (\vdash, \vdash)\}$ then  $p\intro q$ holds for any order $\preceq$ of the alphabet $\Sigma$.
\end{proof}



\begin{lemma*}[\ref{lemma:P-table-geq2}]
    Let $p, q \in Q$, with $p \neq q$. Then $|P[p, q]| \geq 2$ iff $|P_{\lambda'}[p, q]| \geq 2$. 
\end{lemma*}

\begin{proof}
    $(\Rightarrow)$ We prove the statement by contraposition. Suppose $|P_{\lambda'}[p, q]| < 2$,  hence $(P_{\lambda'}[p, q] \setminus \{(\dashv, \dashv), (\vdash,\vdash)\})
    \subseteq \{(a, b)\}$, for some $a,b\in \Sigma$. Then, for every pair $p', q' \in Q$ such that there exists $\gamma \in \Sigma^*$
    for which $p = \delta(p', \gamma)$ and $q = \delta(q', \gamma)$ it holds $\lambda'(p') \subseteq \{a\}$ and
    $\lambda'(q') \subseteq \{b\}$. Now recall that $\lambda'(p')$ and $\lambda'(q')$ where chosen as a maximal subset of $\lambda(p')$ and $\lambda(q')$ with at most two elements and thus also   $\lambda(p') \subseteq \{a\}$ and
    $\lambda(q') \subseteq \{b\}$ must hold, from which it follows that $(P[p, q] \setminus  \{(\dashv, \dashv), (\vdash,\vdash)\})\subseteq \{(a, b)\}$. Then $|P[p, q]| < 2$ since 
    $(\dashv, \dashv)\in P[p, q] $ implies $(\dashv, \dashv)\in P_{\lambda'}[p, q] $ and the same holds for $(\vdash, \vdash)$. 

    $(\Leftarrow)$ Since $P_{\lambda'}[p, q] \subseteq P[p, q]$, the result is immediate. 
\end{proof}


