\title{NeuroSym-BioCAT: Leveraging Neuro-Symbolic Methods for Biomedical Scholarly Document Categorization and Question Answering}

\author[1]{Parvez Zamil}
\author[2,*]{Gollam Rabby}
\author[3]{Md. Sadekur Rahman}
\author[1,2]{Sören Auer}
\affil[1]{TIB—Leibniz Information Centre for Science and Technology, Hannover, Germany}
