\section{Appendix A}\label{sec:AppendixA}

We determine $K_\text{p}$ and $K_\text{i}$ using the \textit{algebra on the graph} technique from \cite{Maksimovic2001}. To do so, we first set the cross-over frequency $\omega_{\phi_\text{m}}=2\pi f_{\phi_\text{m}}$ where $f_{\phi_\text{m}}=255$~Hz (more than 200 times smaller than the switching frequency $f_\text{s}$) and the phase-margin $\phi_\text{m}=50\degree$ as a arbitrary compromise between stability margin, overshoot, and settling time. From those desired values, we first calculate the phase and magnitude of $G_\text{c}(s)$ given by
% \begin{align}
    $\angle{G_{\text{c}}(\omega_{\phi_\text{m}})}=-(\angle{}G(\omega_{\phi_\text{m}})+(180\degree-\phi_\text{m}))$ and
    $|G_{\text{c}}(\omega_{\phi_\text{m}})|_\text{dB}=-|G(\omega_{\phi_\text{m}})|_\text{dB}$.
% \end{align}
We then find the ratio $\alpha$ and compute $K_\text{p}^\prime$ of an intermediate controller with $K_\text{i}^\prime=1$ as
\begin{align}
    \alpha=\frac{K_\text{i}}{K_\text{p}} =& \frac{\omega_{\phi_\text{m}}}{\text{tan}(\angle{}G_\text{c}(\omega_{\phi_\text{m}})+90\degree)}\notag\\
    K_\text{p}^{\prime}=&\frac{1}{\alpha}\text{.}\notag
\end{align}
We finally calculate the magnitude of $G_\text{c}^\prime(s)$ to find $K_\text{p}$ and $K_\text{i}$, and verify if a PI-controller with those parameters is feasible:
\begin{align}
    |G_{\text{c}}^\prime(\omega_{\phi_\text{m}})|_\text{dB}=&20\log\left[\frac{\sqrt{(\omega_{\phi_\text{m}}K_\text{p}^\prime)^2+(K_\text{i}^\prime)^2}}{\omega_{\phi_\text{m}}}\right]\notag\\
    K_{i}=&10^{-|G(\omega_{\phi_\text{m}})|_\text{dB}-|G_\text{c}^\prime(\omega_{\phi_\text{m}})|_\text{dB}/20}\notag\\
    K_\text{p}=&\frac{K_\text{i}}{\alpha}\text{.}\notag
\end{align}

