  \\
  \Op^+                                   & : \tpv \to \tpv \\
  (\app_{\Op}, \lambdap_{\Op})              & : \impl{A} \tmv{\Op^+(A)} \cong \Op_{\beh}(\tmv{A}) \\
  \\
