                                   & (\isof{x_0}{(\isof{a}{\tmv{A}}) \to \tmc{X(\eta_{\Cl}(a))}}) \to \\
                                   & (\isof{x_1}{(\isof{z}{\beh}) \to \tmc{X(\star(z))}}) \to \\
                                   & ((\isof{a}{\tmv{A}}) \to (\isof{z}{\beh}) \to x_0(a) = x_1(z)) \to \\
                                   & \tmc{X(a)} \\
