  (a =_{\tmv{A}} b) \cong \tmv{\eqty{A}{a}{b}}\\
  \\
  \nat                             & : \tpv                                                                                    \\
  \zero                            & : \tmv{\nat}                                                                              \\
  \mathsf{suc}                     & : \tmv{\nat} \to \tmv{\nat}                                                               \\
  \mathsf{ind}                     & : (\isof{n}{\tmv{\nat}}) \to (\isof{X}{\tmv{\nat} \to \tpc}) \to \tmc{X(\zero)} \to       \\
                                   & ((\isof{n}{\tmv{\nat}}) \to \tmc{X(n)} \to \tmc{X(\suc{n})}) \to \tmc{X(n)}               \\
