\subsubsection{Modalities}

The computability structure of the open modality, being a reader monad, displays a similar pattern as the $\Pi$ type as they are both encoded using the framework-level function space. That is, the semantics of object-level open modality $\Op^+$ is given by the meta-level open modality $\Op_{\beh}A \isdef \beh \to A$. 

\iblock{
    \mrow{\Label{\blue{\M}.\blue{\Op^+}} : \extTy{\blue{\tpv} \to \blue{\tpv}}{z}{\syn}{\red{\Op^+}}}
    \mrow{\Label{\blue{\M}.\blue{\Op^+}} A = \glueEx{\syn}{\red{\Op^+}A}{\glue{a}{\red{\tmvp}(\red{\Op^+}A)}{\extTy{\beh \to \blue{\tmvp}(A)}{z}{\syn}{\red{\app_{\Op}}~a}}}}
    \mrow{}
    \mrow{\Label{\blue{\M}.\blue{\lambdap_{\Op}}} : \extTy{(\beh \to \blue{\tmvp}(A)) \to \blue{\tmvp}(\blue{\Op^+}A)}{z}{\syn}{\red{\lambdap_{\Op}}}}
    \mrow{\Label{\blue{\M}.\blue{\lambdap_{\Op}}}~f = \glueEx{\syn}{\red{\lambdap_{\Op}}~f}{f}}
    \mrow{}
    \mrow{\Label{\blue{\M}.\blue{\app_{\Op}}} : \extTy{\blue{\tmvp}(\blue{\Op^+}A) \to \beh \to \blue{\tmvp}(A)}{z}{\syn}{\red{\app_{\Op}}}}
    \mrow{\Label{\blue{\M}.\blue{\app_{\Op}}}~a~z = (\pi_\bullet a)~z}
}

Similarly the semantics of object-level closed modality $\Cl^+$ is conveniently given by the closed modality $\Cl_{\beh}$ in the meta language of synthetic Tait computability.

\iblock{
    \mrow{\Label{\blue{\M}.\blue{\Cl^+}} : \extTy{\blue{\tpv} \to \blue{\tpv}}{z}{\syn}{\red{\Cl^+}}}
    \mhang{\Label{\blue{\M}.\blue{\Cl^+}} A = \glueEx{\syn}{\red{\Cl^+}A}{\glue{a}{\red{\tmvp}(\red{\Cl^+}A)}{\delta}}}{
        \mrow{\kw{where}}
        \mrow{\delta = \closed_{\syn}((ba : \closed_{\beh}(\blue{\tmvp}(A))) \times \try{ba}{\lambda(a' : \blue{\tmvp}(A)). \open_{\syn}(a = \red{\eta_{\Cl}}(a'))}{\beh}{\open_{\syn}(a = \red{\star}(\_))})}
    }
}

The two clauses of the try is identified under $\beh$ because of the $\red{\mathsf{law}_{\Cl}} : \red{\eta_{\Cl}}(a) = \red{\star}(z)$ equation. 

\iblock{
    \mrow{\Label{\blue{\M}.\blue{\eta_{\Cl}}} : \extTy{\blue{\tmvp}(A) \to \blue{\tmvp}(\blue{\Cl^+}(A))}{z}{\syn}{\red{\eta_{\Cl}}}}
    \mrow{\Label{\blue{\M}.\blue{\eta_{\Cl}}}~a = \glueEx{\syn}{\red{\eta_{\Cl}}~a}{\eta_{\closed_{\syn}}(\eta_{\closed_{\beh}}(a), \eta_{\open_{\syn}}(\checkmark : \red{\eta_{\Cl}}(a) = \red{\eta_{\Cl}}(a)))}}
    \mrow{}
    \mrow{\Label{\blue{\M}.\blue{\star}} : \extTy{\beh \to \blue{\tmvp}(\blue{\Cl^+}(A))}{z}{\syn}{\red{\star}}}
    \mrow{\Label{\blue{\M}.\blue{\star}}~z = \glueEx{\syn}{\red{\star}~z}{\eta_{\closed_{\syn}}(\star_{\beh}(z), \eta_{\open_{\syn}}(\checkmark : \red{\star}(z) = \red{\star}(\_))) }}
}

The equation $\blue{\mathsf{law}_{\Cl}}$ holds directly by the meta-level $\mathsf{law}$ for closed modality. The induction principle for closed modality is modeled by the try construct of meta-level closed modality. 


\subsubsection{Equality types}
Since the extensional equality type $\textsf{eq}$ is a value type in \calf{}, it behaves no differently from the usual equality type in Martin-L\"of type theory. The computability structure of equality types is then exactly the same as one given in \citet[\S 4.4.1.4]{sterling>thesis}.

\subsubsection{Natural numbers}
As a final ingredient, we define the computability structure for the $\nat$ type, which is the subject of the canonicity result. This roughly follows \citet{buchholtz-schipp>2024}, adjusting to a call-by-push-value setting, and fixing a slight bug in that work.
\iblock{
    \mrow{\Label{\blue{\M}.\blue{\nat}} : \extTy{\blue{\tpv}}{z}{\syn}{\red{\nat}}}
    \mrow{\Label{\blue{\M}.\blue{\nat}} = \glueEx{\syn}{\red{\nat}}{\glue{e}{\red{\tmvp}(\red{\nat})}{\closed_{\syn}((n : \mathbb{N}) \times \open_{\syn}(e = \red{\sucp}^n(\red{\zero})))}}}
    \mrow{}
    \mrow{\Label{\blue{\M}.\blue{\zero}} : \extTy{\blue{\tmvp}(\blue{\nat})}{z}{\syn}{\red{\zero}}}
    \mrow{\Label{\blue{\M}.\blue{\zero}} = \glueEx{\syn}{\red{\zero}}{\eta_{\closed_{\syn}}(0, \eta_{\open_{\syn}}(\checkmark : \red{\zero} = \red{\zero}))}}
    \mrow{}
    \mrow{\Label{\blue{\M}.\blue{\sucp}} : \extTy{\blue{\tmvp}(\blue{\nat}) \to \blue{\tmvp}(\blue{\nat})}{z}{\syn}{\red{\sucp}}}
    \mhang{\Label{\blue{\M}.\blue{\sucp}}~e = \glueEx{\syn}{\red{\sucp}~e}{\mapp_{\closed_{\syn}}(\theta)(\pi_\bullet e)}}{
        \mrow{\kw{where}}
        \mrow{\theta : (n : \mathbb{N}) \times \open_{\syn}(\red{\sucp}^n(\red{\zero})) \to (n : \mathbb{N}) \times \open_{\syn}(\red{\sucp}^n(\red{\zero}))}
        \mrow{\theta~(n,p) = (1+n, \eta_{\open_{\syn}}(\checkmark : \red{\sucp}(e) = \red{\sucp}^{1+n}(\red{\zero})))}
    }
    \mrow{}
    \mhang{\Label{\blue{\M}.\blue{\indp}} : \{ (e : \blue{\tmvp}(\blue{\nat}))}{
        \mrow{\to (X : \blue{\tmvp}(\blue{\nat}) \to \blue{\tpc})}
        \mrow{\to \blue{\tmcp}(X~\blue{\zero})}
        \mrow{\to ((n : \blue{\tmvp}(\blue{\nat})) \to \blue{\tmcp}(X~n) \to \blue{\tmcp}(X~(\blue{\sucp}(n))))}
        \mrow{\to \blue{\tmcp}(X~e) \mid \syn \hookrightarrow \red{\indp} \} }
    }
    \mhang{\Label{\blue{\M}.\blue{\indp}}~e~X~e_0~e_1 = \try{\pi_\bullet e}{\lambda (n, p). \omega(n)}{\syn}{\red{\indp}~e~X~e_0~e_1}}{
        \mrow{\kw{where}}
        \mrow{\omega : (n : \mathbb{N}) \to \blue{\tmcp}(X~(\blue{\sucp}^n(\blue{\zero})))}
        \mrow{\omega (0) = e_0}
        \mrow{\omega (1+n) = e_1~(\blue{\sucp}^n(\blue{\zero}))~(\omega (n))}
    }
}

\begin{remark}
    In \citet{buchholtz-schipp>2024}, the definition of $\blue{\indp}$ is slightly erroneous in that in therein $p : \open_{\syn}(e = \red{\sucp}^n(\red{\zero}))$ goes into the meta-level induction $\omega$, but it is an equation about the term $e : \blue{\tmvp}(\blue{\nat})$ which never changes. The correct definition is as we have shown above. The role of proof $p$ here is to make sure $\omega(n)$ has the correct type $\blue{\tmcp}(X~e)$.
\end{remark}




\subsection{Fundamental theorem}\label{sec:fundamental}
We may finally conclude that the computability structure $\blue{\M}$ is a model of \calf{} in the sense that it satisfies the signature $\Sigma_{\calf{}}$. In particular, the computability structure $\blue{\M}$ restricts to the syntactic model $\red{\M}$ under the syntactic phase. Furthermore there are structure-preserving homomorphisms $\textsf{\red{blu}\blue{ify}} : \red{\M} \to \blue{\M}$ and $\eta_{\open_{\syn}} : \blue{\M} \to \red{\M}$ such that $\eta_{\open_{\syn}} \circ \textsf{\red{blu}\blue{ify}} = \textsf{Id}$:
%
\[\begin{tikzcd}[cramped,sep=small]
	{\textcolor{red}{\textsf{M}}} &&&& {\textcolor{blue}{\textsf{M}}} \\
	\\
	\\
	\\
	&&&& {\textcolor{red}{\textsf{M}}}
	\arrow["{\textsf{\textcolor{red}{blu}\textcolor{blue}{ify}}}", from=1-1, to=1-5]
	\arrow["{\textsf{Id}}"', from=1-1, to=5-5]
	\arrow["{\eta_{\open_{\syn}}}", from=1-5, to=5-5]
\end{tikzcd}\]
We recall our theorem statement, stating in the language of $\red{\M}$:
\begin{theorem}[Canonicity]
  For every term $e : \red{\tmcp}(\red{\F}(\red{\nat}))$, there exists $c : \costty$ and $n : \mathbb{N}$ such that $e = \red{\stepp}^c(\red{\retp}(\red{\sucp}^n(\red{\zero})))$.
\end{theorem}

\section{Interpreting the computability structure}\label{sec:interpretation}

The aforementioned theorem can be stated in the language of category of judgments $\mathcal{C}$:
\begin{theorem}[Canonicity]
    In the category of judgments of \calf{} $\mathcal{C}$, for every morphism $e : \red{\terminal_{\mathcal{C}}} \to \red{\tmcp}(\red{\F}(\red{\nat}))$, there exists $c : \costty$ and $n : \mathbb{N}$ such that there is a morphism $p : \red{\terminal_{\mathcal{C}}} \to e = \red{\stepp}^c(\red{\retp}(\red{\sucp}^n(\red{\zero})))$.
\end{theorem}

The proof strategy is as follows: we find a locally Cartesian closed category $\mathcal{E}$ and a locally Cartesian closed functor $\textsf{\red{blu}\blue{ify}} : \mathcal{C} \to \mathcal{E}$ according to the definition of $\blue{\M}$. The morphism $e : \red{\terminal_{\mathcal{C}}} \to \red{\tmcp}(\red{\F}(\red{\nat}))$ is then sent to a morphism $\textsf{\red{blu}\blue{ify}}(e) : \blue{\terminal_{\mathcal{E}}} \to \blue{\tmcp}(\blue{\F}(\blue{\nat}))$ in $\mathcal{E}$. The canonicity theorem is then proved by examining this morphism in $\mathcal{E}$.

The recipe of synthetic Tait computability is that the computability result can be constructed from a comma category $\mathcal{E} \isdef \presheaf{\mathcal{I}} \downarrow N_\rho$ where 
\iblock{
    \mrow{N_\rho : \mathcal{C} \to \presheaf{\mathcal{I}}}
    \mrow{N_\rho(X) = \homsetAlt{\mathcal{C}}{\rho-}{X}}
}
$N_\rho$ is a nerve functor from the category of judgments $\mathcal{C}$ introduced earlier to a chosen presheaf category $\presheaf{\mathcal{I}}$ along the shape $\rho : \mathcal{I} \to \mathcal{C}$. This category is called the \emph{Artin Gluing} of $N_\rho$. For example, in the case of the canonicity proof of ordinary Martin-L\"of type theory, the category $\mathcal{I}$ is chosen to be $\textbf{1}_{\textbf{Cat}}$ and shape $\rho : \textbf{1}_{\textbf{Cat}} \to \mathcal{C}$ is the terminal functor that sends everything to $\textbf{1}_{\mathcal{C}}$.

The semantics of \calf{} \cite[\S 5]{niu-sterling-grodin-harper>2022} (or more generally, semantics of phased type theory) is given by a two-world Kripke semantics, that is, presheaves on the “walking arrow” category $\mathcal{I} \isdef \{ \circ \to \bullet \}$, where $\circ$ is the behavioral world (the $\beh$avioral phase) and $\bullet$ is the cost-sensitive world (the ambient ``true'' phase). Therefore the nerve functor $N_\rho$ is given by the following:
\iblock{
    \mrow{\rho : \mathcal{I} \to \mathcal{C}}
    \mrow{\rho(\circ) = \red{\beh}}
    \mrow{\rho(\bullet) = \red{\terminal_{\mathcal{C}}}}
    \mrow{\rho(\circ \to \bullet) = ~! : \red{\beh} \to \red{\terminal_{\mathcal{C}}}}
}
The anti-monotonicity property of Kripke semantics, which says that a judgment holds under the ``true'' phase $\cdot \vdash A$ (as a morphism $\red{\terminal_{\mathcal{C}}} \to \red{A}$) implies it also holds under the behavioral phase $\beh \vdash A$ (as a morphism $\red{\beh} \to \red{A}$), is captured by the fact that pre-composing every morphism $a : \red{\terminal_{\mathcal{C}}} \to \red{A}$ with the unique morphism $! : \red{\beh} \to \red{\terminal_{\mathcal{C}}}$ gives a morphism $a ~\circ~ ! : \red{\beh} \to \red{A}$.

To be explicit, objects of the comma category $\mathcal{E} \isdef \presheaf{\mathcal{I}} \downarrow N_\rho$ are
%
\[
    \Biggl \langle \red{A} \in \mathcal{C}, \Presheaf[f]{S^{\bullet} \in \set}{S^\circ \in \set}, \Presheaff{g^\bullet : S^\bullet \to \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}{g^\circ : S^\circ \to \homset{\red{\beh}}{\red{A}}} \Biggr \rangle
\]

such that the following diagram commutes:
%
\[\begin{tikzcd}[cramped,sep=small]
	{S^\bullet} &&& {\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}} \\
	\\
	\\
	{S^\circ} &&& {\homset{\red{\beh}}{\red{A}}}
	\arrow["{g^\bullet}", from=1-1, to=1-4]
	\arrow["f"', from=1-1, to=4-1]
	\arrow["{- \circ !}", from=1-4, to=4-4]
	\arrow["{g^\circ}", from=4-1, to=4-4]
\end{tikzcd}\]
where the morphism $-\circ !: \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}} \to \homset{\red{\beh}}{\red{A}}$ is pre-composition with the unique morphism $! : \red{\beh} \to \red{\terminal_{\mathcal{C}}}$.

Informally an object should be understand as having a syntactic part $\red{A}$ from the category of judgments $\mathcal{C}$, and a semantic part $S^\bullet$ (representing proofs in the cost-sensitive phase) and $S^\circ$ (representing proofs in the behavioral phase) from the presheaf $\Psh{\mathcal{I}}$, and a pair of functions $g^\bullet$ and $g^\circ$ that makes sure that the syntax and semantics agree. 

Morphisms in this category are three tuples $\red{a} : \red{A} \to \red{B}$, $h^\bullet : S^\bullet \to T^\bullet$, and $h^\circ : S^\circ \to T^\circ$ such that the following squares commute: 
%
\[\begin{tikzcd}[cramped,sep=small]
	{S^\bullet} &&& {T^\bullet} & {S^\circ} &&&& {T^{\circ}} \\
	\\
	\\
	{\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}} &&& {\homset{\red{\terminal_{\mathcal{C}}}}{\red{B}}} & {\homset{\red{\beh}}{\red{A}}} &&&& {\homset{\red{\beh}}{\red{B}}}
	\arrow["{h^\bullet}", from=1-1, to=1-4]
	\arrow["{g^\bullet}"', from=1-1, to=4-1]
	\arrow["{k^\bullet}", from=1-4, to=4-4]
	\arrow["{h^{\circ}}", from=1-5, to=1-9]
	\arrow["{g^\circ}"', from=1-5, to=4-5]
	\arrow["{k^{\circ}}", from=1-9, to=4-9]
	\arrow["{\homset{\red{\terminal_{\mathcal{C}}}}{\red{a}}}"', from=4-1, to=4-4]
	\arrow["{\homset{\red{\beh}}{\red{a}}}"', from=4-5, to=4-9]
\end{tikzcd}\]

In particular there is a forgetful functor $\pi_\circ : \mathcal{E} \to \mathcal{C}$ that forgets the semantic part. Its action on objects is given by $\pi_\circ(\red{A}, S^\bullet, S^\circ, g^\bullet, g^\circ) = \red{A}$ and on morphisms by $\pi_\circ(\red{a}, h^\bullet, h^\circ) = \red{a}$.

Importantly, since the category of judgments $\mathcal{C}$ is locally cartesian closed, the Artin Gluing of a left-exact functor $N_\rho$ is also locally cartesian closed. This means that the internal language of $\mathcal{E}$ is a rich extensional dependent type theory, which is the language of synthetic Tait computability, that is capable of interpreting $\blue{\M}$. Normal dependent type theory constructs can be interpreted into arbitrary locally Cartesian closed categories \cite{seely>1984,hofmann>1994}, and we will show extra structures of synthetic Tait computability can be interpreted in $\mathcal{E}$ as well. What remains is to see what exactly is the morphism $\textsf{\red{blu}\blue{ify}}(e) : \blue{\terminal_{\mathcal{E}}} \to \blue{\tmcp}(\blue{\F}(\blue{\nat}))$ in this interpretation. 

\subsection{Interpreting phases and modalities}
\subsubsection{Phases} 
As phases are propositions, they are interpreted as distinguished subterminal objects. In particular, we have:
\begin{align*}
    \interp{\syn} &\isdef \Biggl \langle \red{\terminal_{\mathcal{C}}}, \Presheaf{\initial_{\set}}{\initial_{\set}}, \Presheaff{! : \initial_{\set} \to \homset{\red{\terminal_{\mathcal{C}}}}{\red{\terminal_{\mathcal{C}}}}=\terminal_{\set}}{! : \initial_\set \to \homset{\red{\beh}}{\red{\terminal_{\mathcal{C}}}}=\terminal_{\set}}  \Biggr \rangle \\ 
    \interp{\beh} &\isdef \Biggl \langle \red{\beh}, \Presheaf{\initial_{\set}}{\terminal_{\set}}, \Presheaff{! : \initial_{\set} \to \homset{\red{\terminal_{\mathcal{C}}}}{\red{\beh}}}{! : \terminal_{\set} \to \homset{\red{\beh}}{\red{\beh}}=\terminal_{\set}} \Biggr \rangle
\end{align*}

We can check that both $\interp{\syn}$ and $\interp{\beh}$ are indeed subterminal objects in $\mathcal{E}$.

The syntactic part $\pi_\circ$ of $\interp{\beh}$ is exactly $\red{\beh}$, validating \cref{ax:beh} that $\beh : \extTy{\univ_j}{z}{\syn}{\red{\beh}}$.

\subsubsection{Modalities}
The modalities $\open_{\syn}$ and $\closed_{\syn}$ are interpreted as the exponential functor $(-)^{\interp{\syn}}$ and pushout along projections of $A \times \interp{\syn}$ respectively. 

\begin{align*}
    \interp{\open_{\syn}} \Biggl \langle \red{A}, \Presheaf{S^\bullet}{S^\circ}, \Presheaff{g^{\bullet}}{g^\circ} \Biggr \rangle & \isdef \Biggl \langle \red{A}, \Presheaf{\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}{\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}, \Presheaff{\textsf{id} : \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}} \to \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}{- \circ ! : \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}} \to \homset{\red{\beh}}{\red{A}}} \Biggr \rangle \\
    \interp{\closed_{\syn}} \Biggl \langle \red{A}, \Presheaf{S^\bullet}{S^\circ}, \Presheaff{g^{\bullet}}{g^\circ} \Biggr \rangle & \isdef \Biggl \langle \red{\terminal_{\mathcal{C}}}, \Presheaf{S^\bullet}{S^\circ}, \Presheaff{! : S^\bullet \to \homset{\red{\terminal_{\mathcal{C}}}}{\red{\terminal_{\mathcal{C}}}}=\terminal_{\set}}{! : S^\circ \to \homset{\red{\beh}}{\red{\terminal_{\mathcal{C}}}}=\terminal_{\set}} \Biggr \rangle
\end{align*}

In particular, we observe that any $\closed_\syn$-modal objects have trivial first and third components, and the only interesting part is the semantic presheaf $S^\bullet \to S^\circ$.

\subsubsection{Strict glue types}
To determine the interpretation of the strict glue type $\glue{x}{\red{A}}{B(x)}$, we observe that 
\begin{enumerate}
    \item $\red{A}$ is $\open_{\syn}$-modal, so its interpretation must be of the form $$\interp{\red{A}} = \Biggl \langle \red{A}, \Presheaf{\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}{\homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}}, \Presheaff{\textsf{id}}{- \circ !} \Biggr \rangle .$$
    \item For each closed term of type $\red{A}$, as a morphism $\red{a} : \red{\terminal_\mathcal{C}} \to \red{A}$, we have that $B(\red{a})$ is $\closed_\syn$-modal, so its interpretation must be of the form $$\interp{B(\red{a})} = \Biggl \langle \red{\terminal_{\mathcal{C}}}, \Presheaf{S_{\red{a}}^\bullet}{S_{\red{{a}}}^\circ}, \Presheaff{!}{!} \Biggr \rangle.$$
\end{enumerate}

Gluing them together, keeping in mind that strict glue type behaves like a $\Sigma$ type, we have:
\[
    \interp{\glue{x}{\red{A}}{B(x)}} = \Biggl \langle \red{A}, \Presheaf{
        \{ (\red{a}, b) \mid \red{a} \in \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}, b \in S_{\red{a}}^\bullet \}}{
        \{ (\red{a}, b) \mid \red{a} \in \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}, b \in S_{\red{a}}^\circ \}}, 
        \Presheaff{\pi_1}{(- \circ !)\circ \pi_1} \Biggr \rangle
\]
where 
$$(- \circ !) \circ \pi_1 : \{ (\red{a}, b) \mid \red{a} \in \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}, b \in S_{\red{a}}^\circ \} \to \homset{\red{\beh}}{\red{A}}$$ is the pre-composition of every $\red{a} \in \homset{\red{\terminal_{\mathcal{C}}}}{\red{A}}$ with the unique morphism $! : \red{\beh} \to \red{\terminal_{\mathcal{C}}}$.

\subsection{Interpreting other type structures}
As mentioned above, the eventual goal is to find the object corresponding to $\blue{\tmcp}(\blue{\F}(\blue{\nat}))$. We recall: 
\iblock{
    \mhang{\blue{\tmcp}(\blue{\F}(\blue{\nat})) = \glue{e}{\red{\tmcp}(\red{\F}(\red{\nat}))}{\closed_{\syn}((n : \mathbb{N}, bc : \closed_{\beh}\costty) \times \alpha)}}{
        \mrow{\alpha = \try{bc}{\lambda (c : \costty). \open_{\syn}(e = \red{\stepp}^c(\red{\retp}(\red{\sucp}^n(\red{\zero}))))}{\beh}{\open_{\syn}(e = \red{\retp}(\red{\sucp}^n(\red{\zero})))}}
    }
}

Notably the second component of $\blue{\tmcp}(\blue{\F}(\blue{\nat}))$ is $\closed_{\syn}$-modal, so its interpretation will have a trivial syntax part $\red{\terminal_{\mathcal{C}}}$; the only interesting part is the semantic presheaf, which we denote as $\interpAlt{-}$. Common types such as $\mathbb{N}$ and $\costty$ are interpreted as constant presheaves; $\Sigma$ types are interpreted in the usual way in a presheaf category. $\open_{\beh}$ erases the cost-sensitive part of the presheaf and $\closed_{\beh}$ trivializes the behavioral part of the presheaf. 

\begin{align*}
    \interpAlt{A} &\isdef \Presheaf{\interpAlt{A}^\bullet}{\interpAlt{A}^\circ} & 
    \interpAlt{\mathbb{N}} &\isdef \Presheaf[\text{id}]{\mathbb{N}}{\mathbb{N}} &
    \interpAlt{\costty} &\isdef \Presheaf[\text{id}]{\costty}{\costty} & \\
    \interpAlt{\beh} &\isdef \Presheaf{\initial_{\set}}{\terminal_{\set}} & 
    \interpAlt{\open_{\beh}A} &\isdef \Presheaf[\text{id}]{\interpAlt{A}^\circ}{\interpAlt{A}^\circ} &
    \interpAlt{\closed_{\beh}A} &\isdef \Presheaf[!]{\interpAlt{A}^\bullet}{\terminal_{\set}} &
\end{align*}

We have the interpretation of $\try{e}{f}{\beh}{g} : B$ as morphisms between presheaves:

\begin{multicols}{3}
    %

    \[
    \interpAlt{e : \closed_{\beh} A} = 
    \begin{tikzcd}[cramped,sep=tiny]
