\caption{Framework for globally solving the rate maximization problem in closed form.}
\label{fig:framework}
\end{figure}

\subsection{From Admittance to Scattering Parameters Representation}

In Section~\ref{sec:system}, we have characterized the microwave networks of the \glspl{milac} at the transmitter and receiver through their admittance parameters, also known as Y-parameters, i.e., their admittance matrices $\mathbf{Y}_F$ and $\mathbf{Y}_G$, respectively.
This choice has been made since the admittance matrix of a \gls{milac} is closely related to the tunable admittance components in its microwave network.
Nevertheless, according to microwave theory \cite[Chapter~4]{poz11}, there exist multiple equivalent representations that can be used to characterize a microwave network.
For example, in addition to the Y-parameters, a multiport microwave network can also be characterized by the S-parameters, through its scattering matrix.
In detail, a generic $N$-port microwave network with admittance matrix $\mathbf{Y}\in\mathbb{C}^{N\times N}$ can be equivalently characterized by its scattering matrix $\boldsymbol{\Theta}\in\mathbb{C}^{N\times N}$ given by
\begin{equation}
\boldsymbol{\Theta}=\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}\left(Y_0\mathbf{I}_N-\mathbf{Y}\right),\label{eq:T(Y)}
\end{equation}
as a function of $\mathbf{Y}$, where $Y_0=Z_0^{-1}$ and $Z_0$ is the reference impedance used to compute the scattering matrix, which is typically set to $Z_0=50~\Omega$ \cite[Chapter~4]{poz11}.
By developing the matrix product in \eqref{eq:T(Y)}, we obtain
\begin{align}
\boldsymbol{\Theta}
=&Y_0\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}-\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}\mathbf{Y}\\
=&Y_0\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}+Y_0\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}\\
&-Y_0\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}-\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}\mathbf{Y}\\
=&2Y_0\left(Y_0\mathbf{I}_N+\mathbf{Y}\right)^{-1}-\mathbf{I}_N,\label{eq:T(B)}
\end{align}
yielding the relationship
\begin{equation}
\left(\frac{\mathbf{Y}}{Y_0}+\mathbf{I}_N\right)^{-1}=\frac{1}{2}\left(\boldsymbol{\Theta}+\mathbf{I}_N\right),\label{eq:alternative}
\end{equation}
which can be used to simplify the expressions of the matrices $\mathbf{F}$ and $\mathbf{G}$ in \eqref{eq:F(Y)2} and \eqref{eq:G(Y)}, respectively.

By introducing the scattering matrix of the \gls{milac} at the transmitter as $\boldsymbol{\Theta}_F\in\mathbb{C}^{(N_S+N_T)\times(N_S+N_T)}$, related to $\mathbf{Y}_F$ via
\begin{equation}
\boldsymbol{\Theta}_F=\left(Y_0\mathbf{I}_{N_S+N_T}+\mathbf{Y}_F\right)^{-1}\left(Y_0\mathbf{I}_{N_S+N_T}-\mathbf{Y}_F\right),\label{eq:TF(YF)}
\end{equation}
because of \eqref{eq:T(Y)}, the precoding matrix $\mathbf{F}$ in \eqref{eq:F(Y)2} can be rewritten as
\begin{equation}
\mathbf{F}=\left[\frac{1}{2}\left(\boldsymbol{\Theta}_F+\mathbf{I}_{N_S+N_T}\right)\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S},
\end{equation}
following the relationship in \eqref{eq:alternative}.
Furthermore, $\mathbf{F}$ can be rewritten as
\begin{equation}
\mathbf{F}=\frac{1}{2}\left[\boldsymbol{\Theta}_F\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S}+\frac{1}{2}\left[\mathbf{I}_{N_S+N_T}\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S},
\end{equation}
and, since $[\mathbf{I}_{N_S+N_T}]_{N_S+\mathcal{N}_T,\mathcal{N}_S}=\mathbf{0}_{N_T\times N_S}$, it simplifies as
\begin{equation}
\mathbf{F}=\frac{1}{2}\left[\boldsymbol{\Theta}_F\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S},
\end{equation}
providing an expression for the precoding matrix simpler than \eqref{eq:F(Y)2}.
A similar discussion can be carried out for the \gls{milac} at the receiver and, by introducing its scattering matrix as $\boldsymbol{\Theta}_G\in\mathbb{C}^{(N_R+N_S)\times(N_R+N_S)}$, which is related to $\mathbf{Y}_G$ via
\begin{equation}
\boldsymbol{\Theta}_G=\left(Y_0\mathbf{I}_{N_R+N_S}+\mathbf{Y}_G\right)^{-1}\left(Y_0\mathbf{I}_{N_R+N_S}-\mathbf{Y}_G\right),\label{eq:TG(YG)}
\end{equation}
the combining matrix $\mathbf{G}$ in \eqref{eq:G(Y)} can be expressed in a simpler way as
\begin{equation}
\mathbf{G}=\frac{1}{2}\left[\boldsymbol{\Theta}_G\right]_{N_R+\mathcal{N}_S,\mathcal{N}_R}.
\end{equation}
In terms of constraints, a lossless microwave network is characterized by a unitary scattering matrix, while a reciprocal microwave network has a symmetric scattering matrix \cite[Chapter~4]{poz11}.
When both these two properties apply, the scattering matrix of a lossless and reciprocal microwave network is unitary and symmetric, as considered to implement \gls{bd-ris} \cite{she22,ner24-1}.
Thus, $\boldsymbol{\Theta}_F$ is mathematically subject to
\begin{equation}
\boldsymbol{\Theta}_F^H\boldsymbol{\Theta}_F=\mathbf{I}_{N_S+N_T},\;\boldsymbol{\Theta}_F=\boldsymbol{\Theta}_F^{T},
\end{equation}
for the \gls{milac} at the transmitter and $\boldsymbol{\Theta}_G$ is subject to
\begin{equation}
\boldsymbol{\Theta}_G^H\boldsymbol{\Theta}_G=\mathbf{I}_{N_R+N_S},\;\boldsymbol{\Theta}_G=\boldsymbol{\Theta}_G^{T},
\end{equation}
for the \gls{milac} at the receiver.

By using the scattering parameters representation, the problem in \eqref{eq:prob1-ini}-\eqref{eq:prob1-fin} can be equivalently rewritten as
\begin{align}
\underset{\boldsymbol{\Theta}_F,\boldsymbol{\Theta}_G,p_{s}}{\mathsf{\mathrm{max}}}\;\;
&R\label{eq:prob2-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\mathbf{F}=\frac{1}{2}\left[\boldsymbol{\Theta}_F\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S},\\
&\boldsymbol{\Theta}_F^H\boldsymbol{\Theta}_F=\mathbf{I}_{N_S+N_T},\;\boldsymbol{\Theta}_F=\boldsymbol{\Theta}_F^T,\\
&\mathbf{G}=\frac{1}{2}\left[\boldsymbol{\Theta}_G\right]_{N_R+\mathcal{N}_S,\mathcal{N}_R},\\
&\boldsymbol{\Theta}_G^H\boldsymbol{\Theta}_G=\mathbf{I}_{N_R+N_S},\;\boldsymbol{\Theta}_G=\boldsymbol{\Theta}_G^T,\\
&\mathbf{P}=\text{diag}(p_1,\ldots,p_{N_S}),\;\sum_{s=1}^{N_S}p_{s}=1,\label{eq:prob2-fin}
\end{align}
which is solved by determining the scattering matrices $\boldsymbol{\Theta}_F$ and $\boldsymbol{\Theta}_G$ and the power allocation $p_1,\ldots,p_{N_S}$ that maximize the rate $R$.
After finding the optimal $\boldsymbol{\Theta}_F$ and $\boldsymbol{\Theta}_G$, the admittance matrices $\mathbf{Y}_F=j\mathbf{B}_F$ and $\mathbf{Y}_G=j\mathbf{B}_G$ can be readily obtained by inverting the relationships in \eqref{eq:TF(YF)} and \eqref{eq:TG(YG)}, respectively.

\subsection{Maximizing an Upper Bound on the Rate}

To solve problem \eqref{eq:prob2-ini}-\eqref{eq:prob2-fin}, we maximize an upper bound on the rate $R$ by obtaining a global optimal solution.
We will then show in Section~\ref{sec:optimal} that this upper bound coincides with the rate $R$ in the obtained solution, confirming that the rate $R$ is also globally maximized.

The rate $R$ in \eqref{eq:C3} is obtained via a suboptimal detection technique, which treats the residual interference from other streams as noise.
Thus, the rate $R$ is upper bounded by the mutual information between $\mathbf{s}$ and $\mathbf{z}$, denoted as $\mathcal{I}(\mathbf{s},\mathbf{z})$, which can be achieved via a joint detection strategy, i.e., $R\leq\mathcal{I}(\mathbf{s},\mathbf{z})$.
In addition to the inequality $R\leq\mathcal{I}(\mathbf{s},\mathbf{z})$, we have $\mathcal{I}(\mathbf{s},\mathbf{z})\leq\mathcal{I}(\mathbf{s},\mathbf{y})$ because of the data processing inequality, which can be applied since $\mathbf{z}$ defined in \eqref{eq:z} is a function of $\mathbf{y}$ \cite[Chapter~2]{cov99}.
Consequently, we can introduce the mutual information between $\mathbf{s}$ and $\mathbf{y}$ $\mathcal{I}(\mathbf{s},\mathbf{y})$ as an upper bound on the rate $R$, given by
\begin{equation}
\mathcal{I}(\mathbf{s},\mathbf{y})=\log_2\det\left(\mathbf{I}_{N_R}+\frac{P_T}{\sigma^2}\mathbf{H}\mathbf{F}\mathbf{P}\mathbf{F}^H\mathbf{H}^H\right),
\end{equation}
and the problem of maximizing $\mathcal{I}(\mathbf{s},\mathbf{y})$ writes as
\begin{align}
\underset{\boldsymbol{\Theta}_F,p_{s}}{\mathsf{\mathrm{max}}}\;\;
&\log_2\det\left(\mathbf{I}_{N_R}+\frac{P_T}{\sigma^2}\mathbf{H}\mathbf{F}\mathbf{P}\mathbf{F}^H\mathbf{H}^H\right)\label{eq:prob3-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\mathbf{F}=\frac{1}{2}\left[\boldsymbol{\Theta}_F\right]_{N_S+\mathcal{N}_T,\mathcal{N}_S},\label{eq:prob3-c1}\\
&\boldsymbol{\Theta}_F^H\boldsymbol{\Theta}_F=\mathbf{I}_{N_S+N_T},\;\boldsymbol{\Theta}_F=\boldsymbol{\Theta}_F^T,\label{eq:prob3-c2}\\
&\mathbf{P}=\text{diag}(p_1,\ldots,p_{N_S}),\;\sum_{s=1}^{N_S}p_{s}=1,\label{eq:prob3-fin}
\end{align}
involving only the optimization variables $\boldsymbol{\Theta}_F$ and $p_1,\ldots,p_{N_S}$.

\subsection{Solving a Relaxed Problem}

To solve problem \eqref{eq:prob3-ini}-\eqref{eq:prob3-fin}, we reformulate it by relaxing constraints \eqref{eq:prob3-c1}-\eqref{eq:prob3-c2} and solve the obtained problem through a global optimal solution.
We will then show in Section~\ref{sec:optimal} that the derived global optimal solution of the relaxed problem also fulfills constraints \eqref{eq:prob3-c1}-\eqref{eq:prob3-c2}, confirming that it also globally solves problem \eqref{eq:prob3-ini}-\eqref{eq:prob3-fin}.

Consider the auxiliary variable $\bar{\mathbf{F}}\in\mathbb{C}^{N_T\times N_S}$ defined as $\bar{\mathbf{F}}=[\boldsymbol{\Theta}_F]_{N_S+\mathcal{N}_T,\mathcal{N}_S}$, such that $\mathbf{F}=\bar{\mathbf{F}}/2$.
Since $\bar{\mathbf{F}}$ is a block of a unitary matrix, each of its $N_S$ columns has an $\ell_2$-norm smaller than 1, giving $\Vert\bar{\mathbf{F}}\Vert_F^2\leq N_S$.
Considering this relaxed contraint on $\bar{\mathbf{F}}$, problem \eqref{eq:prob3-ini}-\eqref{eq:prob3-fin} can be reformulated as
\begin{align}
\underset{\bar{\mathbf{F}},p_{s}}{\mathsf{\mathrm{max}}}\;\;
&\log_2\det\left(\mathbf{I}_{N_R}+\frac{P_T}{4\sigma^2}\mathbf{H}\bar{\mathbf{F}}\mathbf{P}\bar{\mathbf{F}}^H\mathbf{H}^H\right)\label{eq:prob4-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\left\Vert\bar{\mathbf{F}}\right\Vert_F^2\leq N_S,\\
&\mathbf{P}=\text{diag}(p_1,\ldots,p_{N_S}),\;\sum_{s=1}^{N_S}p_{s}=1.\label{eq:prob4-fin}
\end{align}
To solve problem \eqref{eq:prob4-ini}-\eqref{eq:prob4-fin}, there exists a well-known global optimal solution based on multi-eigenmode transmission along the strongest $N_S$ channel eigenmodes with water-filling power allocation \cite[Chapter~5]{cle13}.
Specifically, consider the \gls{svd} of the channel matrix $\mathbf{H}$ as
\begin{equation}
\mathbf{H}=\mathbf{U}\mathbf{\Sigma}\mathbf{V}^H,
\end{equation}
where $\mathbf{U}\in\mathbb{C}^{N_R\times N_R}$ is a unitary matrix containing the left singular vectors of $\mathbf{H}$ in its columns, $\mathbf{\Sigma}\in\mathbb{R}^{N_R\times N_T}$ is a diagonal matrix containing the singular values of $\mathbf{H}$ in its diagonal, denoted as $\sigma_1,\ldots,\sigma_K$, with $K=\min\{N_T,N_R\}$, which are assumed to be nonnegative and in decreasing order, and $\mathbf{V}\in\mathbb{C}^{N_T\times N_T}$ is a unitary matrix containing the right singular vectors of $\mathbf{H}$ in its columns.
Thus, the optimal $\bar{\mathbf{F}}$ is given by the first $N_S$ columns of $\mathbf{V}$, containing the right singular vectors of $\mathbf{H}$ associated with the strongest $N_S$ singular values.
Denoting as $\bar{\mathbf{V}}\in\mathbb{C}^{N_T\times N_S}$ and $\tilde{\mathbf{V}}\in\mathbb{C}^{N_T\times (N_T-N_S)}$ the matrices containing the first $N_S$ columns of $\mathbf{V}$ and the last $N_T-N_S$ columns of $\mathbf{V}$, respectively, such that $\mathbf{V}=[\bar{\mathbf{V}},\tilde{\mathbf{V}}]$, the optimal $\bar{\mathbf{F}}$ writes as $\bar{\mathbf{F}}^\star=\bar{\mathbf{V}}$.
In addition, the optimal power allocations $p_1^\star,\ldots,p_{N_S}^\star$ are given by the water-filling solution
\begin{equation}
p_s^\star=\max\left\{0,\mu-\frac{4\sigma^2}{P_T\lambda_s}\right\}\label{eq:water-filling}
\end{equation}
for $s=1,\ldots,N_S$, where $\mu$ is chosen so as to satisfy the total power constraint $\sum_{s=1}^{N_S}p_{s}=1$ and $\lambda_s=\sigma_s^2$ is the $s$th eigenvalue of $\mathbf{H}\mathbf{H}^H$, for $s=1,\ldots,N_S$.
By substituting the optimal values $\bar{\mathbf{F}}^\star$ and $p_1^\star,\ldots,p_{N_S}^\star$ into the objective function \eqref{eq:prob4-ini}, we obtain that its maximum value is given by
\begin{equation}
C=\sum_{s=1}^{N_S}\log_2\left(1+\frac{P_Tp_{s}^\star\lambda_{s}}{4\sigma^2}\right).\label{eq:Cstar}
\end{equation}

We recall that the optimal value of the objective function in \eqref{eq:Cstar} is not guaranteed to be a tight upper bound on the rate $R$ for two reasons.
First, \eqref{eq:Cstar} is the maximum value of the mutual information $\mathcal{I}(\mathbf{s},\mathbf{y})$ between $\mathbf{s}$ and $\mathbf{y}$, which is an upper bound on the rate $R$.
Second, \eqref{eq:Cstar} has been obtained by considering relaxed constraints on $\mathbf{F}$, given the complexity of its original constraints.
Thus, it is for the moment unclear whether the rate $R$ can achieve the capacity $C$ in \eqref{eq:Cstar} considering the original constraints of $\mathbf{F}$.
In the following, we first show that the derived optimal solution of $\mathbf{F}$ falls within its original constraints.
We then show that with this solution the value of the rate $R$ coincides with the capacity $C$ in \eqref{eq:Cstar}, confirming the feasibility and the global optimality of our solution.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Showing that the Derived Solution\\is Feasible and Global Optimal}
\label{sec:optimal}

We have solved the rate maximization problem and derived a closed-form expression for the maximum rate that can be achieved.
However, the proposed solution has been derived by solving a problem with relaxed constraints, and is not guaranteed to satisfy the constraints of the original optimization problem.
In addition, the proposed solution has been derived by maximizing an upper bound on the rate, and is not guaranteed to globally maximize the rate.
In this section, we address these open questions by proving that the derived solution is feasible, i.e., satisfies the constraints of the original rate maximization problem, and globally maximizes the rate.

\subsection{Checking Solution Feasibility}
%https://www.jstor.org/stable/2028117

We now verify that the solution for the auxiliary variable $\bar{\mathbf{F}}$ given by $\bar{\mathbf{F}}^\star=\bar{\mathbf{V}}$ is compatible with the original constraints \eqref{eq:prob3-c1}-\eqref{eq:prob3-c2}, which require $\bar{\mathbf{F}}$ to be such that $\bar{\mathbf{F}}=[\boldsymbol{\Theta}_F]_{N_R+\mathcal{N}_S,\mathcal{N}_R}$, with $\boldsymbol{\Theta}_F^H\boldsymbol{\Theta}_F=\mathbf{I}_{N_S+N_T}$ and $\boldsymbol{\Theta}_F=\boldsymbol{\Theta}_F^T$.
To this end, we need to find a symmetric unitary matrix $\boldsymbol{\Theta}_F$ having the block $[\boldsymbol{\Theta}_F]_{N_R+\mathcal{N}_S,\mathcal{N}_R}=\bar{\mathbf{V}}$, i.e., a symmetric unitary matrix $\boldsymbol{\Theta}_F$ which can be partitioned as
\begin{equation}
\boldsymbol{\Theta}_F=
\begin{bmatrix}
\mathbf{X}_1 & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix},\label{eq:TF-X1X2}
\end{equation}
where $\mathbf{X}_1\in\mathbb{C}^{N_S\times N_S}$ and $\mathbf{X}_2\in\mathbb{C}^{N_T\times N_T}$.
This problem can be formalized in the following feasibility-check problem
\begin{align}
\mathrm{find}\;\;
&\mathbf{X}_1\in\mathbb{C}^{N_S\times N_S},\mathbf{X}_2\in\mathbb{C}^{N_T\times N_T}\label{eq:prob5-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\begin{bmatrix}
\mathbf{X}_1 & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}^H
\begin{bmatrix}
\mathbf{X}_1 & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}=\mathbf{I}_{N_S+N_T},\\
&\begin{bmatrix}
\mathbf{X}_1 & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}=
\begin{bmatrix}
\mathbf{X}_1 & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}^T.\label{eq:prob5-fin}
\end{align}
Note that problems involving the completion of symmetric unitary matrices are not trivial due to the joint presence of the two constraints, symmetric and unitary.
For example, a problem similar to \eqref{eq:prob5-ini}-\eqref{eq:prob5-fin} was considered in \cite{mat69} and solved through an iterative solution.
In the following, we show how problem \eqref{eq:prob5-ini}-\eqref{eq:prob5-fin} can be solved in closed form.

We first notice that all the columns of a unitary matrix have unit $\ell_2$-norm and that all the columns of $\bar{\mathbf{V}}$ have also unit norm.
Thus, we must have $\mathbf{X}_1=\mathbf{0}_{N_S}$ to ensure that the first $N_S$ columns of $\boldsymbol{\Theta}_F$ have unit $\ell_2$-norm, and $\mathbf{X}_2$ can be found by solving
\begin{align}
\mathrm{find}\;\;
&\mathbf{X}_2\in\mathbb{C}^{N_S\times N_S}\label{eq:prob6-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\begin{bmatrix}
\mathbf{0}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}^H
\begin{bmatrix}
\mathbf{0}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}=\mathbf{I}_{N_S+N_T},\label{eq:prob6-c1}\\
&\begin{bmatrix}
\mathbf{0}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}=
\begin{bmatrix}
\mathbf{0}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{X}_2
\end{bmatrix}^T.\label{eq:prob6-fin}
\end{align}
To solve problem \eqref{eq:prob6-ini}-\eqref{eq:prob6-fin}, we notice that constraint \eqref{eq:prob6-c1} can be equivalently rewritten as
\begin{gather}
\bar{\mathbf{V}}^H\bar{\mathbf{V}}=\mathbf{I}_{N_S},\label{eq:prob6-c1-1}\\
\bar{\mathbf{V}}^H\mathbf{X}_2=\mathbf{0}_{N_S\times N_T},\label{eq:prob6-c1-2}\\
\mathbf{X}_2^H\bar{\mathbf{V}}=\mathbf{0}_{N_T\times N_S},\label{eq:prob6-c1-3}\\
\bar{\mathbf{V}}^*\bar{\mathbf{V}}^T+\mathbf{X}_2^H\mathbf{X}_2=\mathbf{I}_{N_T},\label{eq:prob6-c1-4}
\end{gather}
where \eqref{eq:prob6-c1-1} is always satisfied and \eqref{eq:prob6-c1-3} coincides with \eqref{eq:prob6-c1-2} since they are the Hermitian of each other.
Besides, constraint \eqref{eq:prob6-fin} is satisfied if and only if
\begin{equation}
\mathbf{X}_2=\mathbf{X}_2^T.\label{eq:prob6-c2-1}
\end{equation}
Thus, problem \eqref{eq:prob6-ini}-\eqref{eq:prob6-fin} can be equivalently reformulated as
\begin{align}
\mathrm{find}\;\;
&\mathbf{X}_2\in\mathbb{C}^{N_S\times N_S}\label{eq:prob7-ini}\\
\mathsf{\mathrm{s.t.}}\;\;\;
&\eqref{eq:prob6-c1-2},\;\eqref{eq:prob6-c1-4},\;\eqref{eq:prob6-c2-1},\label{eq:prob7-fin}
%&\bar{\mathbf{V}}^H\mathbf{X}_2=\mathbf{0}_{N_S\times N_T},\\
%&\bar{\mathbf{V}}^*\bar{\mathbf{V}}^T+\mathbf{X}_2^H\mathbf{X}_2=\mathbf{I}_{N_T},\\
%&\mathbf{X}_2=\mathbf{X}_2^T,
\end{align}
with a solution given by $\mathbf{X}_2=-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$, as it can be verified by showing that all three constraints are fulfilled by this solution.
First, $\bar{\mathbf{V}}^H\mathbf{X}_2=-\bar{\mathbf{V}}^H\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T=\mathbf{0}_{N_S\times N_T}$ since all the columns of $\tilde{\mathbf{V}}$ are orthogonal to all the columns of $\bar{\mathbf{V}}$, which gives $\bar{\mathbf{V}}^H\tilde{\mathbf{V}}=\mathbf{0}_{N_S\times N_T}$.
Second, $\bar{\mathbf{V}}^*\bar{\mathbf{V}}^T+\mathbf{X}_2^H\mathbf{X}_2=\bar{\mathbf{V}}^*\bar{\mathbf{V}}^T+\tilde{\mathbf{V}}^*\tilde{\mathbf{V}}^T=\mathbf{V}^*\mathbf{V}^T=(\mathbf{V}^H\mathbf{V})^*$, yielding $\bar{\mathbf{V}}^*\bar{\mathbf{V}}^T+\mathbf{X}_2^H\mathbf{X}_2=\mathbf{I}_{N_T}$ since $\mathbf{V}$ is unitary and $(\mathbf{V}^H\mathbf{V})^*=\mathbf{I}_{N_T}$.
Third, it is obvious that $-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$ is symmetric.
Note that $\mathbf{X}_2=-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$ is just a valid solution among infinitely many others\footnote{While also $\mathbf{X}_2=\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$ solves problem \eqref{eq:prob7-ini}-\eqref{eq:prob7-fin}, we adopt $\mathbf{X}_2=-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$ since it allows to express the admittance matrix of the \gls{milac} at the transmitter in closed form, as it will be clarified in Section~\ref{sec:StoY}.}.
For example, any matrix $\mathbf{X}_2=\mathbf{A}\mathbf{A}^T$, with $\mathbf{A}\in\mathbb{C}^{N_T\times (N_T-N_S)}$, is a valid solution if all the columns of $\mathbf{A}$ have unit $\ell_2$-norm, are orthogonal between themselves and are orthogonal with the $N_S$ columns of $\bar{\mathbf{V}}$.

Considering the derived solution to problem \eqref{eq:prob5-ini}-\eqref{eq:prob5-fin}, a symmetric unitary scattering matrix $\boldsymbol{\Theta}_F$ having $[\boldsymbol{\Theta}_F]_{N_R+\mathcal{N}_S,\mathcal{N}_R}=\bar{\mathbf{V}}$ can be obtained by substituting $\mathbf{X}_1=\mathbf{0}_{N_S}$ and $\mathbf{X}_2=-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T$ in \eqref{eq:TF-X1X2} as
\begin{equation}
\boldsymbol{\Theta}_F^\star=
\begin{bmatrix}
\mathbf{0}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & -\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T
\end{bmatrix}.\label{eq:TF}
\end{equation}
This proves that the global optimal solution to the relaxed problem \eqref{eq:prob4-ini}-\eqref{eq:prob4-fin} is also a valid global optimal solution to the problem \eqref{eq:prob3-ini}-\eqref{eq:prob3-fin}.

\subsection{Checking Global Maximization of the Rate}

We have derived a global optimal solution to the problem \eqref{eq:prob3-ini}-\eqref{eq:prob3-fin}.
However, the objective function in \eqref{eq:prob3-ini} is an upper bound on the rate $R$, and there is no guarantee that the obtained solution also globally maximizes the rate $R$.
In addition, we only have a solution for the scattering matrix of the \gls{milac} at the transmitter $\boldsymbol{\Theta}_F$ and the power allocations $p_s$, for $s=1,\ldots,N_S$, while it is still unclear how to reconfigure the scattering matrix of the \gls{milac} at the receiver $\boldsymbol{\Theta}_G$.
We now propose a solution for $\boldsymbol{\Theta}_G$ and verify that, jointly with the previously derived solutions for $\boldsymbol{\Theta}_F$ and $p_s$, they indeed globally maximize the rate $R$.

Adopting a dual approach to that employed at the transmitter side, we reconfigure the \gls{milac} at the receiver such that the combining matrix $\mathbf{G}$ contains in its $N_S$ rows the left singular vectors of $\mathbf{H}$ associated with the strongest $N_S$ singular values.
More formally, denoting as $\bar{\mathbf{U}}\in\mathbb{C}^{N_R\times N_S}$ and $\tilde{\mathbf{U}}\in\mathbb{C}^{N_R\times (N_R-N_S)}$ the matrices containing the first $N_S$ columns of $\mathbf{U}$ and the last $N_R-N_S$ columns of $\mathbf{U}$, respectively, such that $\mathbf{U}=[\bar{\mathbf{U}},\tilde{\mathbf{U}}]$, we speculate that the optimal $\mathbf{G}$ maximizing the rate $R$ is given by $\mathbf{G}^\star=\bar{\mathbf{U}}^H/2$.
Thus, a possible scattering matrix of the \gls{milac} at the receiver $\boldsymbol{\Theta}_G$ satisfying $[\boldsymbol{\Theta}_G]_{N_R+\mathcal{N}_S,\mathcal{N}_R}=\bar{\mathbf{U}}^H$ and fulfilling the symmetric unitary constraints is
\begin{equation}
\boldsymbol{\Theta}_G^\star=
\begin{bmatrix}
-\tilde{\mathbf{U}}^*\tilde{\mathbf{U}}^H & \bar{\mathbf{U}}^*\\
\bar{\mathbf{U}}^H & \mathbf{0}_{N_S} 
\end{bmatrix},\label{eq:TG}
\end{equation}
as it can be easily verified by checking that $\boldsymbol{\Theta}_G^{\star H}\boldsymbol{\Theta}_G^\star=\mathbf{I}_{N_R+N_S}$ and $\boldsymbol{\Theta}_G^\star=\boldsymbol{\Theta}_G^{\star T}$.

With the solutions of the scattering matrices $\boldsymbol{\Theta}_F^\star$ in \eqref{eq:TF} and $\boldsymbol{\Theta}_G^\star$ in \eqref{eq:TG}, the optimal precoding and combining matrices are given by $\mathbf{F}^\star=\bar{\mathbf{V}}/2$ and $\mathbf{G}^\star=\bar{\mathbf{U}}^H/2$, respectively.
This gives $\mathbf{G}^\star\mathbf{H}\mathbf{F}^\star=[\mathbf{\Sigma}]_{\mathcal{N}_S,\mathcal{N}_S}/4$, which simplifies the rate in \eqref{eq:C1} to
\begin{equation}
R=\sum_{s=1}^{N_S}\log_2\left(1+\frac{P_Tp_{s}\lambda_s}
{4\sigma^2}\right),\label{eq:Copt}
\end{equation}
since $\vert[\mathbf{G}^\star\mathbf{H}\mathbf{F}^\star]_{s,s}\vert^2=\lambda_s/16$, $\vert[\mathbf{G}^\star\mathbf{H}\mathbf{F}^\star]_{s,t}\vert^2=0$ if $t\neq s$, and $\Vert[\mathbf{G}^\star]_{s,:}\Vert^2=1/4$, for $s,t=1,\ldots,N_S$.
By also considering the optimal power allocation $p_1^\star,\ldots,p_{N_S}^\star$ given by the water-filling solution in \eqref{eq:water-filling}, the achieved rate in \eqref{eq:Copt} coincides with the capacity in \eqref{eq:Cstar}, proving that the obtained solution is globally optimal.

\subsection{From Scattering to Admittance Parameters Representation}
\label{sec:StoY}

We have determined the expressions for the optimal scattering matrices of the \glspl{milac} at the transmitter and receiver, in \eqref{eq:TF} and \eqref{eq:TG}, respectively, which are proved to globally solve problem \eqref{eq:prob2-ini}-\eqref{eq:prob2-fin}.
However, the original problem \eqref{eq:prob1-ini}-\eqref{eq:prob1-fin} involves the optimization of the admittance matrices of the \glspl{milac}, which are directly related to their tunable admittance components.
In the following, we derive the expressions of the optimal admittance matrices of the \glspl{milac}, concluding the solution of problem \eqref{eq:prob1-ini}-\eqref{eq:prob1-fin}.

For the \gls{milac} at the transmitter, its optimal susceptance matrix $\mathbf{B}_F^\star$ is related to its optimal scattering matrix $\boldsymbol{\Theta}_F^\star$ through
\begin{equation}
\mathbf{B}_F^\star=-jY_0\left(2\left(\boldsymbol{\Theta}_F^\star+\mathbf{I}_{N_S+N_T}\right)^{-1}-\mathbf{I}_{N_S+N_T}\right),\label{eq:BF}
\end{equation}
which is a direct consequence of \eqref{eq:TF(YF)} and that $\mathbf{Y}_F=j\mathbf{B}_F$ in a lossless \gls{milac}.
By substituting $\boldsymbol{\Theta}_F^\star$ given by \eqref{eq:TF} into \eqref{eq:BF}, we obtain
\begin{equation}
\mathbf{B}_F^\star=-jY_0\left(2
\begin{bmatrix}
\mathbf{I}_{N_S} & \bar{\mathbf{V}}^T\\
\bar{\mathbf{V}} & \mathbf{I}_{N_T}-\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T
\end{bmatrix}^{-1}-\mathbf{I}_{N_S+N_T}\right),\label{eq:BF-inv}
\end{equation}
which can also be written as
\begin{equation}
\mathbf{B}_F^\star=-jY_0\left(2
\begin{bmatrix}
\mathbf{K}_{F,11} & \mathbf{K}_{F,12}\\
\mathbf{K}_{F,21} & \mathbf{K}_{F,22}
\end{bmatrix}-\mathbf{I}_{N_S+N_T}\right),\label{eq:BF-K}
\end{equation}
with
\begin{gather}
\mathbf{K}_{F,11}=\mathbf{I}_{N_S}+\bar{\mathbf{V}}^T\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}},\label{eq:KF11}\\
\mathbf{K}_{F,12}=-\bar{\mathbf{V}}^T\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1},\\
\mathbf{K}_{F,21}=-\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}},\\
\mathbf{K}_{F,22}=\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1},\label{eq:KF22}
\end{gather}
where we exploited the expression of the inverse of a $2\times2$ block matrix \cite{lu02} and the relationship $\bar{\mathbf{V}}\bar{\mathbf{V}}^T+\tilde{\mathbf{V}}\tilde{\mathbf{V}}^T=\mathbf{V}\mathbf{V}^T$, valid for any matrix $\mathbf{V}=[\bar{\mathbf{V}},\tilde{\mathbf{V}}]$.
After the necessary computations, the expressions in \eqref{eq:KF11}-\eqref{eq:KF22} can be rewritten as functions of only $\Re\{\mathbf{V}\}$ and $\Im\{\mathbf{V}\}$ as
\begin{comment}
\begin{align}
&\mathbf{I}_{N_S}+\bar{\mathbf{V}}^T\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}}\\
&=\mathbf{I}_{N_S}+\bar{\mathbf{V}}^T\left(\mathbf{V}\left(\mathbf{V}^H\mathbf{V}^*-\mathbf{I}_{N_T}\right)\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}}\\
&=\mathbf{I}_{N_S}+\bar{\mathbf{V}}^T\mathbf{V}^*\left(\mathbf{V}^H\mathbf{V}^*-\mathbf{I}_{N_T}\right)^{-1}\mathbf{V}^H\bar{\mathbf{V}}\\
&=\mathbf{I}_{N_S}+\left[\left(\mathbf{V}^H\mathbf{V}^*-\mathbf{I}_{N_T}\right)^{-1}\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\left(\mathbf{V}^H\left(\mathbf{V}^*-\mathbf{V}\right)\right)^{-1}\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\left(-2j\Im\{\mathbf{V}\}\right)^{-1}\mathbf{V}\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\frac{1}{2}j\Im\{\mathbf{V}\}^{-1}\left(\Re\{\mathbf{V}\}+j\Im\{\mathbf{V}\}\right)\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\frac{1}{2}\left(-\mathbf{I}_{N_T}+j\Im\{\mathbf{V}\}^{-1}\Re\{\mathbf{V}\}\right)\right]_{1:N_S,1:N_S}\\
&=\frac{1}{2}\left(\mathbf{I}_{N_S}+j\left[\Im\{\mathbf{V}\}^{-1}\Re\{\mathbf{V}\}\right]_{1:N_S,1:N_S}\right)
\end{align}
\begin{align}
-\bar{\mathbf{V}}^T\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}
&=-\bar{\mathbf{V}}^T\left(\left(\mathbf{V}^*-\mathbf{V}\right)\mathbf{V}^T\right)^{-1}\\
&=\bar{\mathbf{V}}^T\mathbf{V}^*\left(2j\Im\{\mathbf{V}\}\right)^{-1}\\
&=-\frac{1}{2}j\left[\Im\{\mathbf{V}\}^{-1}\right]_{1:N_S,:}
\end{align}
\begin{align}
-\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}}
&=-\left(\mathbf{V}\left(\mathbf{V}^H-\mathbf{V}^T\right)\right)^{-1}\bar{\mathbf{V}}\\
&=\left(2j\Im\{\mathbf{V}^T\}\right)^{-1}\mathbf{V}^H\bar{\mathbf{V}}\\
&=-\frac{1}{2}j\left[\Im\{\mathbf{V}^T\}^{-1}\right]_{:,1:N_S}\\
&=-\frac{1}{2}j\left[\Im\{\mathbf{V}\}^{-1}\right]_{1:N_S,:}^T
\end{align}
\begin{align}
\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}
&=\left(\left(\mathbf{V}^*-\mathbf{V}\right)\mathbf{V}^T\right)^{-1}\\
&=\mathbf{V}^*\left(-2j\Im\{\mathbf{V}\}\right)^{-1}\\
&=\frac{1}{2}j\left(\Re\{\mathbf{V}\}-j\Im\{\mathbf{V}\}\right)\Im\{\mathbf{V}\}^{-1}\\
&=\frac{1}{2}\left(\Im\{\mathbf{V}\}+j\Re\{\mathbf{V}\}\right)\Im\{\mathbf{V}\}^{-1}\\
&=\frac{1}{2}\left(\mathbf{I}_{N_T}+j\Re\{\mathbf{V}\}\Im\{\mathbf{V}\}^{-1}\right)
\end{align}
\end{comment}
\begin{gather}
\begin{split}
\mathbf{I}_{N_S}+\bar{\mathbf{V}}^T&\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}}\\
&=\frac{1}{2}\left(\mathbf{I}_{N_S}+j\left[\Im\{\mathbf{V}\}^{-1}\Re\{\mathbf{V}\}\right]_{\mathcal{N}_S,\mathcal{N}_S}\right),
\end{split}\label{eq:KF11-sim}\\
-\bar{\mathbf{V}}^T\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}
=-\frac{1}{2}j\left[\Im\{\mathbf{V}\}^{-1}\right]_{\mathcal{N}_S,:},\\
-\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}\bar{\mathbf{V}}
=-\frac{1}{2}j\left[\Im\{\mathbf{V}\}^{-1}\right]_{\mathcal{N}_S,:}^T,\\
\left(\mathbf{I}_{N_T}-\mathbf{V}\mathbf{V}^T\right)^{-1}
=\frac{1}{2}\left(\mathbf{I}_{N_T}+j\Re\{\mathbf{V}\}\Im\{\mathbf{V}\}^{-1}\right),\label{eq:KF22-sim}
\end{gather}
respectively.
Thus, by substituting \eqref{eq:KF11-sim}-\eqref{eq:KF22-sim} into \eqref{eq:KF11}-\eqref{eq:KF22}, and then into \eqref{eq:BF-K}, we obtain $\mathbf{B}_F^\star$ in closed-form as
\begin{equation}
\mathbf{B}_F^\star=Y_0
\begin{bmatrix}
\left[\Im\{\mathbf{V}\}^{-1}\Re\{\mathbf{V}\}\right]_{\mathcal{N}_S,\mathcal{N}_S} &
-\left[\Im\{\mathbf{V}\}^{-1}\right]_{\mathcal{N}_S,:} \\
-\left[\Im\{\mathbf{V}\}^{-1}\right]_{\mathcal{N}_S,:}^T &
\Re\{\mathbf{V}\}\Im\{\mathbf{V}\}^{-1}
\end{bmatrix},\label{eq:BFstar}
\end{equation}
purely as a function of $\Re\{\mathbf{U}\}$ and $\Im\{\mathbf{V}\}$.
\begin{comment}
\begin{gather}
(\mathbf{R}+j\mathbf{M})^H(\mathbf{R}+j\mathbf{M})=\mathbf{I}\\
(\mathbf{R}^T-j\mathbf{M}^T)(\mathbf{R}+j\mathbf{M})=\mathbf{I}\\
(\mathbf{R}^T\mathbf{R}+\mathbf{M}^T\mathbf{M})+j(\mathbf{R}^T\mathbf{M}-\mathbf{M}^T\mathbf{R})=\mathbf{I}\\
\mathbf{M}^T\mathbf{R}=\mathbf{R}^T\mathbf{M}\\
\mathbf{M}^T\mathbf{R}\mathbf{M}^{-1}=\mathbf{R}^T\\
\mathbf{R}\mathbf{M}^{-1}=(\mathbf{M}^T)^{-1}\mathbf{R}^T=(\mathbf{M}^{-1})^T\mathbf{R}^T=(\mathbf{R}\mathbf{M}^{-1})^T\\
\end{gather}
\begin{gather}
(\mathbf{R}+j\mathbf{M})(\mathbf{R}+j\mathbf{M})^H=\mathbf{I}\\
(\mathbf{R}+j\mathbf{M})(\mathbf{R}^T-j\mathbf{M}^T)=\mathbf{I}\\
(\mathbf{R}\mathbf{R}^T+\mathbf{M}\mathbf{M}^T)+j(\mathbf{M}\mathbf{R}^T-\mathbf{R}\mathbf{M}^T)=\mathbf{I}\\
\mathbf{R}\mathbf{M}^T=\mathbf{M}\mathbf{R}^T\\
\mathbf{M}^{-1}\mathbf{R}\mathbf{M}^T=\mathbf{R}^T\\
\mathbf{M}^{-1}\mathbf{R}=\mathbf{R}^T(\mathbf{M}^T)^{-1}=\mathbf{R}^T(\mathbf{M}^{-1})^T=(\mathbf{M}^{-1}\mathbf{R})^T\\
\end{gather}
\end{comment}
As expected for the susceptance matrix of a reciprocal microwave network, note that $\mathbf{B}_F^\star$ is symmetric since the matrices $\Im\{\mathbf{V}\}^{-1}\Re\{\mathbf{V}\}$ and $\Re\{\mathbf{V}\}\Im\{\mathbf{V}\}^{-1}$ are symmetric for any unitary matrix $\mathbf{V}$ with invertible imaginary part.

A similar discussion can be repeated for the \gls{milac} at the receiver by departing from the relationship  between its optimal admittance matrix $\mathbf{B}_G^\star$ and its optimal scattering matrix $\boldsymbol{\Theta}_G^\star$, given by
\begin{equation}
\mathbf{B}_G^\star=-jY_0\left(2\left(\boldsymbol{\Theta}_G^\star+\mathbf{I}_{N_R+N_S}\right)^{-1}-\mathbf{I}_{N_R+N_S}\right),\label{eq:BG}
\end{equation}
following from \eqref{eq:TG(YG)}, which becomes
\begin{equation}
\mathbf{B}_G^\star=-jY_0\left(2
\begin{bmatrix}
\mathbf{I}_{N_R}-\tilde{\mathbf{U}}^*\tilde{\mathbf{U}}^H & \bar{\mathbf{U}}^*\\
\bar{\mathbf{U}}^H & \mathbf{I}_{N_S}
\end{bmatrix}^{-1}-\mathbf{I}_{N_R+N_S}\right),\label{eq:BG-inv}
\end{equation}
by considering the expression of $\boldsymbol{\Theta}_G^\star$ given by \eqref{eq:TG}.
In addition, by recalling the expression of the inverse of a $2\times2$ block matrix \cite{lu02}, \eqref{eq:BG-inv} can be written as
\begin{equation}
\mathbf{B}_G^\star=-jY_0\left(2
\begin{bmatrix}
\mathbf{K}_{G,11} & \mathbf{K}_{G,12}\\
\mathbf{K}_{G,21} & \mathbf{K}_{G,22}
\end{bmatrix}-\mathbf{I}_{N_R+N_S}\right),\label{eq:BG-K}
\end{equation}
with
\begin{gather}
\mathbf{K}_{G,11}=\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1},\label{eq:KG11}\\
\mathbf{K}_{G,12}=-\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*,\\
\mathbf{K}_{G,21}=-\bar{\mathbf{U}}^H\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1},\\
\mathbf{K}_{G,22}=\mathbf{I}_{N_S}+\bar{\mathbf{U}}^H\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*,\label{eq:KG22}
\end{gather}
where we also used the relationship $\bar{\mathbf{U}}^*\bar{\mathbf{U}}^H+\tilde{\mathbf{U}}^*\tilde{\mathbf{U}}^H=\mathbf{U}^*\mathbf{U}^H$, valid for any matrix $\mathbf{U}=[\bar{\mathbf{U}},\tilde{\mathbf{U}}]$.
Following appropriate calculations, \eqref{eq:KG11}-\eqref{eq:KG22} can be expressed as
\begin{comment}
\begin{align}
\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}
&=\left(\left(\mathbf{U}-\mathbf{U}^*\right)\mathbf{U}^H\right)^{-1}\\
&=\mathbf{U}\left(2j\Im\{\mathbf{U}\}\right)^{-1}\\
&=-\frac{1}{2}j\left(\Re\{\mathbf{U}\}+j\Im\{\mathbf{U}\}\right)\Im\{\mathbf{U}\}^{-1}\\
&=\frac{1}{2}\left(\Im\{\mathbf{U}\}-j\Re\{\mathbf{U}\}\right)\Im\{\mathbf{U}\}^{-1}\\
&=\frac{1}{2}\left(\mathbf{I}_{N_R}-j\Re\{\mathbf{U}\}\Im\{\mathbf{U}\}^{-1}\right)
\end{align}
\begin{align}
-\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*
&=-\left(\mathbf{U}^*\left(\mathbf{U}^T-\mathbf{U}^H\right)\right)^{-1}\bar{\mathbf{U}}^*\\
&=-\left(2j\Im\{\mathbf{U}^T\}\right)^{-1}\mathbf{U}^T\bar{\mathbf{U}}^*\\
&=\frac{1}{2}j\left[\Im\{\mathbf{U}^T\}^{-1}\right]_{:,1:N_S}\\
&=\frac{1}{2}j\left[\Im\{\mathbf{U}\}^{-1}\right]_{1:N_S,:}^T
\end{align}
\begin{align}
-\bar{\mathbf{U}}^H\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}
&=-\bar{\mathbf{U}}^H\left(\left(\mathbf{U}-\mathbf{U}^*\right)\mathbf{U}^H\right)^{-1}\\
&=-\bar{\mathbf{U}}^H\mathbf{U}\left(2j\Im\{\mathbf{U}\}\right)^{-1}\\
&=\frac{1}{2}j\left[\Im\{\mathbf{U}\}^{-1}\right]_{1:N_S,:}
\end{align}
\begin{align}
&\mathbf{I}_{N_S}+\bar{\mathbf{U}}^H\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*\\
&=\mathbf{I}_{N_S}+\bar{\mathbf{U}}^H\left(\mathbf{U}^*\left(\mathbf{U}^T\mathbf{U}-\mathbf{I}_{N_R}\right)\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*\\
&=\mathbf{I}_{N_S}+\bar{\mathbf{U}}^H\mathbf{U}\left(\mathbf{U}^T\mathbf{U}-\mathbf{I}_{N_R}\right)^{-1}\mathbf{U}^T\bar{\mathbf{U}}^*\\
&=\mathbf{I}_{N_S}+\left[\left(\mathbf{U}^T\mathbf{U}-\mathbf{I}_{N_R}\right)^{-1}\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\left(\mathbf{U}^T\left(\mathbf{U}-\mathbf{U}^*\right)\right)^{-1}\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\left(2j\Im\{\mathbf{U}\}\right)^{-1}\mathbf{U}^*\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[-\frac{1}{2}j\Im\{\mathbf{U}\}^{-1}\left(\Re\{\mathbf{U}\}-j\Im\{\mathbf{U}\}\right)\right]_{1:N_S,1:N_S}\\
&=\mathbf{I}_{N_S}+\left[\frac{1}{2}\left(-\mathbf{I}_{N_R}-j\Im\{\mathbf{U}\}^{-1}\Re\{\mathbf{U}\}\right)\right]_{1:N_S,1:N_S}\\
&=\frac{1}{2}\left(\mathbf{I}_{N_S}-j\left[\Im\{\mathbf{U}\}^{-1}\Re\{\mathbf{U}\}\right]_{1:N_S,1:N_S}\right)
\end{align}
\end{comment}
\begin{gather}
\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}
=\frac{1}{2}\left(\mathbf{I}_{N_R}-j\Re\{\mathbf{U}\}\Im\{\mathbf{U}\}^{-1}\right),\label{eq:KG11-sim}\\
-\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*
=\frac{1}{2}j\left[\Im\{\mathbf{U}\}^{-1}\right]_{\mathcal{N}_S,:}^T,\\
-\bar{\mathbf{U}}^H\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}
=\frac{1}{2}j\left[\Im\{\mathbf{U}\}^{-1}\right]_{\mathcal{N}_S,:},\label{eq:KG22-sim}\\
\begin{split}
\mathbf{I}_{N_S}+\bar{\mathbf{U}}^H&\left(\mathbf{I}_{N_R}-\mathbf{U}^*\mathbf{U}^H\right)^{-1}\bar{\mathbf{U}}^*\\
&=\frac{1}{2}\left(\mathbf{I}_{N_S}-j\left[\Im\{\mathbf{U}\}^{-1}\Re\{\mathbf{U}\}\right]_{\mathcal{N}_S,\mathcal{N}_S}\right),
\end{split}
\end{gather}
allowing us to rewrite \eqref{eq:BG-K} in closed-form as
\begin{equation}
\mathbf{B}_G^\star=Y_0
\begin{bmatrix}
-\Re\{\mathbf{U}\}\Im\{\mathbf{U}\}^{-1} &
\left[\Im\{\mathbf{U}\}^{-1}\right]_{\mathcal{N}_S,:}^T \\
\left[\Im\{\mathbf{U}\}^{-1}\right]_{\mathcal{N}_S,:} &
-\left[\Im\{\mathbf{U}\}^{-1}\Re\{\mathbf{U}\}\right]_{\mathcal{N}_S,\mathcal{N}_S}
\end{bmatrix},\label{eq:BGstar}
\end{equation}
as a function of only $\Re\{\mathbf{U}\}$ and $\Im\{\mathbf{U}\}$.

In summary, the expressions of the optimal susceptance matrices $\mathbf{B}_F^\star$ in \eqref{eq:BFstar} and $\mathbf{B}_G^\star$ in \eqref{eq:BGstar}, together with the optimal power allocation given by the water-filling solution in \eqref{eq:water-filling}, globally solve in closed form the rate maximization problem formulated in \eqref{eq:prob1-ini}-\eqref{eq:prob1-fin}.
This solution allows us to achieve the capacity given in \eqref{eq:Cstar}.

