\section{Equations for \texorpdfstring{$\OCM$}{the oriented Cayley-Menger variety}}
\label{equations}

\begin{lemma}
\label{lemma:equation_oriented_volume}
 The following equations hold for $\OCM$. Form the matrix
  %
  \[
  M_{i, i+1, \Top, \Bottom} =
  \left(
  \begin{array}{rrrrr}
    0 & 1 & 1 & 1 & 1 \\
    1 & 0 & d_{i \, i+1} & d_{i \, \Top} & d_{i \, \Bottom} \\
    1 & d_{i \, i+1} & 0 & d_{i+1 \, \Top} & d_{i+1 \, \Bottom} \\
    1 & d_{i \, \Top} & d_{i+1 \, \Top} & 0 & d_{\Top \, \Bottom} \\
    1 & d_{i \, \Bottom} & d_{i+1 \, \Bottom} & d_{\Top \, \Bottom} & 0 \\
  \end{array}
  \right)\,.
  \]
  %
 Then
 \[
   288 \, s_{i,i+1}^2 - \det(M_{i, i+1, \Top, \Bottom}) = 0 \,.
 \]
 %
\end{lemma}
\begin{proof}
 This is a well known fact in distance geometry (see for example \cite[Section~4.1.2]{Liberti2017}).
\end{proof}

The following lemma has content very similar to \cite{Sabitov};
we state and prove it because for our purposes we need a precise description of the equation satisfied by the distances and the oriented volumes.

\begin{lemma}
\label{lemma:equation_distance_volume}
 The following equations hold for $\OCM$:
 %
 \[
  a_k d_{ij} + b_{ijk} - 288 \varsigma_{ik} \varsigma_{kj} = 0 \,,
 \]
 %
 where
 %
 \[
  a_k = 2(d_{k\Top} d_{k\Bottom} + d_{k\Top} d_{\Top\Bottom} + d_{k\Bottom} d_{\Top\Bottom}) - (d_{k\Top}^2 + d_{k\Bottom}^2 + d_{\Top\Bottom}^2)
 \]
 %
 \begin{align*}
  b_{ijk} =
   &\bigl(d_{ik} (d_{j\Bottom}-d_{j\Top})+d_{kj}
   (d_{i\Bottom}-d_{i\Top})+d_{k\Bottom}
   (d_{i\Top}+d_{j\Top})-d_{k\Top} (d_{i\Bottom}+d_{j\Bottom})\bigr)
   (d_{k\Bottom}-d_{k\Top})\\
   &-d_{\Top\Bottom} \bigl(d_{i\Top}
   (d_{k\Bottom}+d_{kj})+d_{i\Bottom}
   (d_{k\Top}+d_{kj})+d_{j\Top}
   (d_{ik}+d_{k\Bottom})+d_{j\Bottom} (d_{ik}+d_{k\Top})\bigr)\\
   &-(d_{k\Bottom}+d_{k\Top}-d_{\Top\Bottom})
   \bigl(d_{\Top\Bottom} (d_{ik}+d_{kj})+(d_{i\Top}
   d_{j\Bottom}+d_{j\Top} d_{i\Bottom})\bigr)\\
   &+2 (d_{i\Top} d_{k\Bottom}
   d_{j\Top}+d_{i\Bottom} d_{k\Top} d_{j\Bottom}+d_{k\Bottom}
   d_{k\Top} d_{\Top\Bottom} + d_{ik} d_{kj} d_{\Top\Bottom})\,.
 \end{align*}
 Notice that both $a_{k}$ and $b_{ijk}$ only depend on the $d$-coordinates; in particular, $a_k$ depends on the variables $d_{k\Top}$,$d_{k\Bottom}$, and $d_{\Top\Bottom}$, while $b_{ijk}$ depends on the variables $d_{m\Top}$, $d_{m\Bottom}$ for $m \in \{i,j,k\}$ and $d_{ik}$, $d_{kj}$, and $d_{\Top\Bottom}$.
\end{lemma}
\begin{proof}
 It is well-known (see for example \cite[Theorem 4.2]{Liberti2016}) that the following determinant is identically zero:
 %
 \[
  \det
  \left(
  \begin{array}{cccccc}
   0 & 1 & 1 & 1 & 1 & 1 \\
   1 & 0 & d_{ik} & d_{ij} & d_{i\Top} & d_{i\Bottom} \\
   1 & d_{ik} & 0 & d_{kj} & d_{k\Top} & d_{k\Bottom} \\
   1 & d_{ij} & d_{kj} & 0 & d_{j\Top} & d_{j\Bottom} \\
   1 & d_{i\Top} & d_{k\Top} & d_{j\Top} & 0 & d_{\Top\Bottom} \\
   1 & d_{i\Bottom} & d_{k\Bottom} & d_{j\Bottom} & d_{\Top\Bottom} & 0 \\
  \end{array}
  \right) \,.
 \]
 %
 This determinant is a polynomial in $d_{ij}$ of degree $k$.
 Solving the equation with respect to $d_{ij}$ yields the desired equation,
 with an ambiguity regarding the sign of
 the monomial~$288 \varsigma_{i,k} \varsigma_{k,j}$.
 To solve the ambiguity, one can plug in the parametrization of $\OCM$
 with symbolic coordinates for the points in $(\R^3)^{V_{\Bipyramid}}$.
 See notebook \cite[Section~3.1]{supportingCode}.
\end{proof}

\begin{definition}
 We denote by $W_{i, j, k, \ell}$ the squared volume of the tetrahedron $(i, j, k, \ell)$.
 It follows that $W_{i, j, k, \ell}$ is a polynomial in $\{ d_{uv} \}_{u,v \in \{i, j, k, \ell\}}$.
\end{definition}

\begin{lemma}
\label{lemma:oriented_volume_diagonal}
 For every $i, j, k \in \{1, \dotsc, n\}$, we have
 %
 \[
   a_{i,j,k} \, \varsigma_{i, j} + b_{i,j,k} = 0 \,,
 \]
 %
 where
 %
 \begin{align*}
  a_{i,j,k} &= -4 (\varsigma_{i, k} + \varsigma_{k, j}) \bigl((\varsigma_{i, k} + \varsigma_{k, j})^2 - W_{i, k, j, \Bottom} - W_{i, k, j, \Top} + W_{i, j, \Top, \Bottom} \bigr) \, ,  \\
  b_{i,j,k} &= (\varsigma_{i, k} + \varsigma_{k, j})^2 \bigl( (\varsigma_{i, k} + \varsigma_{k, j})^2 - 2W_{i, k, j, \Bottom} - 2W_{i, k, j, \Top} + 6W_{i, j, \Top, \Bottom} \bigr) \\
  &\phantom{=} +
  (W_{i, k, j, \Bottom} + W_{i, k, j, \Top} - W_{i, j, \Top, \Bottom})^2 - 4W_{i, k, j, \Bottom} W_{i, k, j, \Top} \, .
 \end{align*}
 %
\end{lemma}
\begin{proof}
 See notebook~\cite[Section~3.2]{supportingCode}.
\end{proof}

\begin{corollary}
\label{corollary:rational_functions}
 For every $i, j \in \{1, \dotsc, n\}$, we have that both $d_{ij}$ and $\varsigma_{i,j}$
 are rational functions in $\{s_e\}_{e \in \Eq} \cup \{d_{e}\}_{e \in E_{\Bipyramid}} \cup \{d_{\Top\Bottom}\}$ in the function field of $\OCM$.
\end{corollary}
\begin{proof}
 We prove the statement by induction on $|j - i|$.
 Since $d_{ji} = d_{ij}$ and $\varsigma_{i,j} = -\varsigma_{j,i}$, we can suppose that $j > i$.
 For the base case $j = i+1$, then $\varsigma_{i,i+1} = s_{i,i+1}$, so the statement is proven.
 By choosing $k = j-1$, \Cref{lemma:equation_distance_volume} shows that $d_{ij}$ is a rational function in
 $\{\varsigma_{i, j-1}, \varsigma_{j-1, j}\} \cup \{ d_{i, j-1}, d_{j-1, j}\} \cup \{d_{u\Top}, d_{u\Bottom} \}_{u \in \{i, j-1, j\}} \cup \{d_{\Top\Bottom}\}$.
 Moreover, again by choosing $k = j-1$, \Cref{lemma:oriented_volume_diagonal} shows that $\varsigma_{i,j}$ is a rational function in $\{\varsigma_{i, j-1}, \varsigma_{j-1, j}\} \cup \{ d_{i, j-1}, d_{j-1, j}, d_{i, j} \} \cup \{d_{u\Top}, d_{u\Bottom} \}_{u \in \{i, j-1, j\}} \cup \{d_{\Top\Bottom}\}$: indeed, the squared volumes appearing in $a_{i,j,k}$ and $b_{i,j,k}$ can be expressed as polynomials in $\{ d_{i, j-1}, d_{j-1, j}, d_{i, j} \} \cup \{d_{u\Top}, d_{u\Bottom} \}_{u \in \{i, j-1, j\}} \cup \{d_{\Top\Bottom}\}$.
 Hence, by the inductive step, both $d_{ij}$ and $\varsigma_{i,j}$ are rational functions in the desired variables.
\end{proof}

