\section{Proof of Theorem~\ref{thm:optim} and auxiliary results}\label{sec:proof}
In this Section, we will prove Theorem~\ref{thm:optim}. We will first show that the error estimator is an upper bound for the error, i.e., it is reliable. Then, we will show that the adaptive algorithm is optimal in the sense of \eqref{eq:rate_optim} and that the error converges with the same rate as the error estimator.
\subsection{Linear convergence and total time optimality}\label{sec:time}
We will use the framework of~\cite{Carstensen_2014} to show optimality. This method first shows linear convergence of the error estimator, i.e., the output of Algorithm~\ref{alg:adaptive} satisfies
\begin{align}\label{eq:linconv}
    \eta_{\TT_{\ell+k}}\leq C_{\rm lin} q^k \eta_{\TT_\ell}\quad\text{for all }\ell,k\in\N.
\end{align}
This is a crucial intermediate step on the way to optimal convergence rates. Clearly,~\eqref{eq:linconv} ensures that only logarithmically many iterations are needed to reach a desired accuracy. Moreover, it serves as the theoretical justification of the fact that the cumulative compute time for the adaptive algorithm is dominated by the last iteration as shown in the proof of Theorem~\ref{thm:optim}.


\subsection{The error estimator is an upper bound for the error}
The following lemma shows the most fundamental property of the error estimator: It is an upper bound for the error. In a posteriori error estimation, this property is called \emph{reliability}.
\begin{lemma}
\label{lem:gen_reliability}
    If $F$ in \eqref{eq:ode} satisfies \eqref{eq:Lip}, the error estimator~\eqref{eq:estimator} is reliable in the sense
\begin{align*}
    \norm{y-y_{\TT}}{H^1([t_0,\tend])}\leq C_{\rm rel}\eta_{\TT}\quad\text{for all admissible meshes }\TT\in\T,
\end{align*}
where $C_{\rm rel}>0$ is independent of $\TT$.
\end{lemma}
\begin{proof}
We will use variants of Gronwall's lemma. Let us define the residual $R(t):=\partial_t y_{\TT}(t)-F(t,y_{\TT}(t))$. It holds for almost every $t \in (t_0, \tend)$ that
\begin{align*}
    \partial_t y(t)-\partial_t y_{\TT}(t)=F(t,y(t))-F(t,y_{\TT}(t))-R(t).
\end{align*}
Integrating from $t_0$ to $t$ and using condition \eqref{eq:Lip} yields
\begin{align*}
    |y(t)-y_\TT(t)| &\leq \int_{t_0}^t |F(s,y(s))-F(s,y_{\TT}(s))|ds+\int_{t_0}^t |R(s)|ds,\\
    & \leq L_1\int_{t_0}^t |y(s)-y_\TT(s)|ds+\int_{t_0}^t |R(s)|ds.
\end{align*}
Gronwall's lemma~\cite[Prop. 2.1]{emmrich1999discrete} gives
\begin{align}\label{eq:firstest}
    |y(t)-y_\TT(t)| \leq e^{L_1 (t-t_0)}\int_{t_0}^t |R(s)|ds \leq e^{L_1 (\tend-t_0)}\int_{t_0}^{\tend} |R(s)|ds.
\end{align}
Moreover, we get
\begin{align*}
    \norm{y-y_{\TT}}{H^1([t_0,\tend])}^2& \leq C^2_{\rm pc} \norm{ \partial_t y-\partial_t y_{\TT}}{L^2([t_0,\tend])}^2=C^2_{\rm pc}\int_{t_0}^{\tend} \Big(F(t,y(t))-F(t,y_{\TT}(t))-R(t)\Big)^2 dt \\
    & \leq C^2_{\rm pc} 2 L_1^2 \int_{t_0}^{\tend} \Big(y(t)-y_\TT(t) \Big)^2 dt + 2\int_{t_0}^{\tend} R(t)^2 dt,
\end{align*}
where we denote the Poincaré constant used in the first step by $C_{\rm pc}=\sqrt{\tend-t_0}$. With~\eqref{eq:firstest}, we get
\begin{align}\label{eq:resrel}
\begin{split}
 \norm{y-y_{\TT}}{H^1([t_0,\tend])}^2
    & \leq C^2_{\rm pc}2L_1^2 e^{2L_1 (\tend-t_0)}\int_{t_0}^{\tend} \Big(\int_{t_0}^{\tend}|R(s)|ds\Big)^2dt+2\int_{t_0}^{\tend} R(t)^2 dt\\
    & \leq C^2_{\rm pc}\Big(2L_1^2 e^{2L_1 (\tend-t_0)} (\tend-t_0)^2+2\Big) \int_{t_0}^{\tend} R(t)^2 dt.
    \end{split}
\end{align}
In~\eqref{eq:gen_disc}, we may choose $v \in P^0(\TT)$ to show $\int_TR(t)dt=0$ for all $T\in\TT$. Thus, we can use a Poincaré type inequality as in~\cite{ANASTASSIOU20081102} to see
\begin{align*}
    \norm{y-y_{\TT}}{H^1([t_0,\tend])}^2 \leq C_{\rm rel}^2 \sum_{T \in \TT} |T|^2 \norm{\partial_t F(\cdot,y_{{\TT}})+\nabla_yF(\cdot, y_{{\TT}}) \partial_t y_{{\TT}}-\partial^2_t y_\TT}{L^2(T)}^2.
\end{align*}
This concludes the proof with $C^2_{\rm rel}=C_{\rm pc}^2\Big(2L_1^2 e^{2L_1 (\tend-t_0)} (\tend-t_0)^2+2\Big).$
\end{proof}
With a small refinement of the proof, we can also obtain a computable upper bound for the pointwise error.
\begin{lemma}\label{lem:infty_reliability}
    If $F$ in \eqref{eq:ode} satisfies \eqref{eq:Lip}, the error estimator~\eqref{eq:estimator} satisfies
\begin{align*}
 \norm{y-y_{\TT}}{L^\infty([t_0,\tend])}\leq e^{L_1(\tend-t_0)}\max_{T\in\TT}|T|^{1/2}\eta_\TT(T).
\end{align*}
\end{lemma}
\begin{proof}
As in the proof of Lemma~\ref{lem:gen_reliability}, we obtain
\begin{align*}
    |y(t)-y_\TT(t)| 
    & \leq L_1\int_{t_0}^t |y(s)-y_\TT(s)|ds+\Big|\int_{t_0}^t R(s)\,ds\Big|.
\end{align*}
Since $\int_TR(t)dt=0$ for all $T\in\TT$, we have $\int_{t_0}^t R(s)\,ds = \int_{t_-}^t R(s)\,ds$, where $t_-$ is the left endpoint of the time interval containing $t$. A Poincar\'e inequality shows
\begin{align*}
\Big|\int_{t_0}^t R(s)\,ds\Big|\leq \max_{T\in\TT} |T|^{3/2}\norm{\partial_t R}{L^2(T)}
\end{align*}
and Gronwall's lemma implies
\begin{align}\label{eq:firstest}
    |y(t)-y_\TT(t)| \leq e^{L_1 (t-t_0)}\max_{T\in\TT} |T|^{3/2}\norm{\partial_t R}{L^2(T)}.
\end{align}
\end{proof}



\subsection{Convergence of uniform time stepping}
Since the proof technique is very similar to the previous result, we make a short excursion to show that if the step size is sufficiently small, also the approximation error can be arbitrarily small. 
\begin{lemma}\label{lem:unifconv}
All approximate solutions $y_\TT$ are uniformly bounded in the sense $\norm{y_\TT}{H^1([t_0,\tend])}\leq C$ for a constant $C<\infty$ that depends only on the exact solution $y$, $\tend$ and $L_1$. Moreover, let $\tau_\TT:= \max_{T\in\TT}|T|$ denote the maximal step size of $\TT$. There holds 
    \begin{align*}
        \lim_{\tau_\TT\to 0 }\norm{y-y_\TT}{H^1([t_0,\tend])} = 0.
    \end{align*}
\end{lemma}
\begin{proof}
We introduce the $L^2$-orthogonal projection onto piecewise polynomials of degree $p-1$, denoted by $\Pi_{p-1}: L^2([t_0,\tend],\R^d) \to \PP^{p-1}(\TT)$. From the definition, we obtain the identity
\begin{align*}
   \partial_t y - \partial_t y_\TT(t) &= F(t,y(t)) - \partial_t y_\TT(t) =  (1-\Pi_{p-1})F(t,y(t)) +\Pi_{p-1}F(t,y(t))- \partial_t y_\TT(t) \\
   &= 
    (1-\Pi_{p-1})F(t,y(t)) +\Pi_{p-1}(F(\cdot,y)- F(\cdot,y_\TT)).
\end{align*}
Lipschitz's continuity of $F$ and integration from $t_0$ to $t$ show
\begin{align*}
    |y(t) - y_\TT(t)|\leq \int_{t_0}^t(1-\Pi_{p-1})F(\cdot,y)\,ds  + L_1 \int_{t_0}^t |y(s)-y_\TT(s)|\,ds.
\end{align*}
Hence, Gronwall's lemma~\cite[Prop. 2.1]{emmrich1999discrete} shows
\begin{align*}
    |y(t) - y_\TT(t)|\leq e^{L_1(t-t_0)}\int_{t_0}^t|(1-\Pi_{p-1})F(\cdot,y)|\,ds
    \leq  e^{L_1(t-t_0)}\sqrt{|t-t_0|}\norm{(1-\Pi_{p-1})F(\cdot,y)}{L^2([t_0,\tend])}.
\end{align*}
Just as in the proof of Lemma~\ref{lem:gen_reliability}, we can use this estimate to also get
\begin{align*}
    \norm{y-y_\TT}{H^1([t_0,\tend])} &\leq C_{\rm pc} \norm{\partial_t y - \partial_t y_\TT}{L^2([t_0,\tend])}\\
    &\leq 
    C_{\rm pc} \norm{(1-\Pi_{p-1})F(t,y(t))}{L^2([t_0,\tend])}+C_{\rm pc}\norm{\Pi_{p-1}(F(\cdot,y)- F(\cdot,y_\TT))}{L^2([t_0,\tend])}\\
    &\leq 
    C_{\rm pc} \norm{(1-\Pi_{p-1})F(t,y(t))}{L^2([t_0,\tend])}+C_{\rm pc}L_1\norm{y- y_\TT}{L^2([t_0,\tend])}\\ 
    &\lesssim \norm{(1-\Pi_{p-1})F(\cdot,y)}{L^2([t_0,\tend])},
\end{align*}
where the hidden constant in the last estimate depends on $C_{\rm pc}$, $\tend$, and $L_1$.
From this, we immediately get boundedness of $\norm{y_\TT}{H^1([t_0,\tend])}$. Moreover, since $y\in H^1([t_0,\tend],\R^d)$ and $F$ is Lipschitz continuous, there  holds $\norm{(1-\Pi_{p-1})F(\cdot,y)}{L^2([t_0,\tend])}\to 0$ as $\tau_\TT \to 0$.
This concludes the proof.
\end{proof}
\subsection{Optimality properties of the error estimator}
We aim to use the framework established in~\cite{Carstensen_2014} and therefore require certain properties of the error estimator called (A1)--(A4) in~\cite{Carstensen_2014}.
The next result is called \emph{Stability on non-refined elements}~(A1) and shows that the error estimator is Lipschitz continuous. The term \emph{element} comes from the fact that the framework in~\cite{Carstensen_2014} was built for stationary mesh refinement where one typically refers to the elements of a mesh. In our context, it would be more accurate to speak of \emph{interval}, however, for consistency we adopt the terminology.
\begin{lemma}
\label{lem:gen_stability}
    If the right-hand side $F$ from~\eqref{eq:ode} satisfies \eqref{eq:Lip}--\eqref{eq:JacLip}, the error estimator~\eqref{eq:estimator} satisfies stability on non-refined elements in the sense that
    \begin{align*}
        \Bigg| \Big(\sum_{T \in \TT \cap \widehat\TT}\eta_{\TT}(T)^2 \Big)^{1/2}-\Big(\sum_{T \in \TT \cap \widehat\TT} \eta_{\widehat\TT}(T)^2\Big)^{1/2} \Bigg| \leq C_{\rm stab} \norm{y_{\TT}-y_{\widehat\TT}}{H^1([t_0,\tend])},
    \end{align*}
     for a refinement $\widehat\TT$ of $\TT \in \T.$
\end{lemma}
\begin{proof}
    Repeated use of the triangle inequality yields
    \begin{align*}
        &\Bigg(\Big(\sum_{T \in \TT \cap \widehat\TT}\eta_{\TT}(T)^2 \Big)^{1/2}-\Big(\sum_{T \in \TT \cap \widehat\TT} \eta_{\widehat\TT}(T)^2\Big)^{1/2}\Bigg)^2 \\
        &\leq \sum_{T \in \TT \cap \widehat\TT}|T|^2\norm{\partial_t F(\cdot,y_{{\TT}})+\nabla_yF(\cdot, y_{{\TT}}) \partial_t y_{{\TT}}-\partial^2_t y_\TT-\partial_t F(\cdot,y_{\widehat\TT})-\nabla_yF(\cdot, y_{\widehat\TT}) \partial_t y_{\widehat\TT}+\partial^2_t y_{\widehat\TT}}{L^2(T)}^2 \\
        &\lesssim \sum_{T \in \TT \cap \widehat\TT}|T|^2\Bigg( \int_T |\partial_t F(t,y_{{\TT}}(t))-\partial_t F(t,y_{\widehat\TT}(t))|^2dt+\int_T|\nabla_yF(t, y_{{\TT}}(t)) \partial_t y_{{\TT}}(t)-\nabla_yF(t, y_{\widehat\TT}(t)) \partial_t y_{\widehat\TT}(t)|^2dt\\
        &\qquad +\int_T |\partial^2_t y_\TT(t)-\partial^2_t y_{\widehat\TT}(t)|^2dt\Bigg).
    \end{align*}
    Because of the Lipschitz condition on the Jacobian of $F$, we get for the first term of the sum
    \begin{align*}
        \int_T |\partial_t F(t,y_{{\TT}}(t))-\partial_t F(t,y_{\widehat\TT}(t))|^2dt \leq L_2^2\int_T |y_{\TT}(t)-y_{\widehat\TT}(t)|^2dt.
    \end{align*}
    For the second term we get
    \begin{align*}
        \int_T|\nabla_y&F(t, y_{{\TT}}(t)) \partial_t y_{{\TT}}(t)-\nabla_yF(t, y_{\widehat\TT}(t)) \partial_t y_{\widehat\TT}(t)|^2dt \\
        &\lesssim \int_T|\nabla_yF(t, y_{{\TT}}(t))-\nabla_yF(t, y_{\widehat\TT}(t))|^2|\partial_t y_{{\TT}}(t)|^2+|\nabla_yF(t, y_{\widehat\TT}(t))|^2|\partial_t y_{{\TT}}(t)-\partial_t y_{\widehat\TT}(t)|^2 dt.
    \end{align*}
    Note that $|T|^2|\partial_t y_{{\TT}}(t)|^2$ and $|\nabla_yF(t, y_{\widehat\TT}(t))|^2$ are uniformly bounded because of Lemma \ref{lem:unifconv}, with a bound only depending on the true solution, the initial discretization $\TT_0$ and $L_2$. Therefore, we obtain
    \begin{align*}
         \int_T|\nabla_yF(t, y_{{\TT}}(t)) \partial_t y_{{\TT}}(t)-\nabla_yF(t, y_{\widehat\TT}(t)) \partial_t y_{\widehat\TT}(t)|^2dt \lesssim  \int_T | y_{\TT}(t)-y_{\widehat\TT}(t)|^2 dt +\int_T |\partial_t y_{\TT}(t)-\partial_t y_{\widehat\TT}(t)|^2dt
    \end{align*}
    For the last term of the sum, an inverse estimate on $T\in \TT\cap \widehat \TT$ gives
    \begin{align*}
        \int_T |\partial^2_t y_\TT(t)-\partial^2_t y_{\widehat\TT}(t)|^2dt \lesssim \frac{1}{|T|^2}\int_T|\partial_t y_\TT(t)-\partial_t y_{\widehat\TT}(t)|^2dt
    \end{align*}
    Combining the estimates and using a Poincaré inequality (since $y_\TT(t_0)=y_{\widehat\TT}(t_0)$) yields the result.
\end{proof}
The next result is called~\emph{Reduction on refined elements}~(A2) in \cite{Carstensen_2014} and shows that, up to a perturbation, the error estimator gets smaller when the step size is reduced.
\begin{lemma}
\label{lem:gen_reduction}
     If the right-hand side $F$ from~\eqref{eq:ode} satisfies \eqref{eq:Lip}--\eqref{eq:JacLip}, the error estimator~\eqref{eq:estimator} satisfies reduction on refined elements in the sense
    \begin{align*}
        \sum_{T \in \widehat\TT \setminus \TT} \eta_{\widehat\TT}(T)^2 \leq q \sum_{T \in  \TT\setminus \widehat\TT} \eta_{\TT}(T)^2 + C_{\rm red}\norm{y_{\TT}-y_{\widehat\TT}}{H^1([t_0,\tend])}^2
    \end{align*}
     for a refinement $\widehat\TT$ of $\TT \in \T,$ $0<q<1$ and $C_{\rm red}>1$.
\end{lemma}
\begin{proof}
    The proof is similar to the one in \cite{generalqo}. Let $T \in \TT\setminus \widehat\TT$ and $T_1,\ldots,T_n \in \widehat\TT \setminus \TT$ such that $T_1 \cup\ldots \cup T_n=T$. It holds that $|T_i|\leq |T|/2$ for all $i=1,\ldots,n$. Now we have
    \begin{align*}
        &\sum_{i=1}^n\eta_{\widehat\TT}(T_i)^2\\
        &\leq (1+ \delta) \sum_{i=1}^n\frac{|T|^2}{4}\norm{\partial_t F(\cdot,y_{\TT})+\nabla_yF(\cdot, y_{\TT}) \partial_t y_{\TT}-\partial^2_t y_\TT}{L^2(T_i)}^2\\
        &\qquad +(1+\delta^{-1}) \sum_{i=1}^n|T_i|^2\norm{\partial_t F(\cdot,y_{{\TT}})+\nabla_yF(\cdot, y_{{\TT}}) \partial_t y_{{\TT}}-\partial^2_t y_\TT-\partial_t F(\cdot,y_{\widehat\TT})-\nabla_yF(\cdot, y_{\widehat\TT}) \partial_t y_{\widehat\TT}+\partial^2_t y_{\widehat\TT}}{L^2(T)}^2
    \end{align*}
    for any $\delta>0$. By using the same estimates as in Lemma \ref{lem:gen_stability} and choosing $\delta>0$ sufficiently small, we get
    \begin{align*}
        \sum_{i=1}^n\eta_{\widehat\TT}(T_i)^2 \leq q_{\delta}\eta_{\TT}(T)^2+ C_{\delta} \norm{y_{\TT}-y_{\widehat\TT}}{H^1(T)}^2.
    \end{align*}
    Summing up over $T\in \TT\setminus \widehat\TT $ yields the result.
\end{proof}
The next result is a refinement of \emph{reliability} (Lemma~\ref{lem:gen_reliability}) and is called \emph{Discrete reliability}~(A4) in~\cite{Carstensen_2014}.
It shows that the difference between to discrete approximation can be bounded on a subset of the domain.
The main idea of the proof of the next statement is an inductive argument, where refined and non-refined elements are treated differently.
\begin{lemma}
\label{lem:gen_reldisc}
  If the right-hand side $F$ from~\eqref{eq:ode} satisfies \eqref{eq:Lip}--\eqref{eq:JacLip} and the initial discretization $\TT_0$ is fine enough, the error estimator~\eqref{eq:estimator} satisfies discrete reliability, in the sense
    \begin{align*}
        \norm{y_{\widehat\TT}-y_{\TT}}{H^1([t_0,\tend])}^2 \leq C_{\rm rel} \sum_{T \in \TT \setminus \widehat\TT}\eta_{\TT}(T)^2
    \end{align*}
    for a refinement $\widehat\TT$ of $\TT \in \T$.
\end{lemma}
\begin{proof}
    Recall the residual $R(t):=\partial_t y_{\TT}(t)-F(t,y_{\TT})$. We have for almost all $t \in (t_0, \tend)$
    \begin{align}
        \label{eq:starting_point}
        \partial_t y_\TT(t)-\partial_t y_{\widehat\TT}(t)=F(t,y_\TT(t))-\partial_t y_{\widehat\TT}(t)+R(t).
    \end{align}
    \emph{Step~1: }
    Let $[t_i,t_{i+1}]=T \in \widehat\TT \setminus \TT$ be a refined element. Since $y_{\TT}-y_{\widehat\TT}$ is a polynomial of order $p$ in $T$, we can uniquely determine it by the values of the first derivative at the $p$ Gauss-Legendre integration points in $T$ and its value at $t_i$, i.e, we write it as
    \begin{align}
    \label{eq:parametrize}
        y_{\TT}(t)-y_{\widehat\TT}(t)=y_{\TT}(t_i)-y_{\widehat\TT}(t_i)+ \int_{t_i}^t \sum_{k=1}^p \partial_t (y_\TT(\sigma_k)-y_{\widehat\TT}(\sigma_k)) l_k(s) ds,
    \end{align}
    where $\sigma_1, \ldots \sigma_p$ are the $p$ Gauss-Legendre integration nodes in $T$ and $l_k(s)=\prod_{j=1,j\neq k}^p \frac{(s-\sigma_j)}{\sigma_k-\sigma_j}$, the $k$th Lagrange interpolation polynomial. By multiplying \eqref{eq:starting_point} with $l_k$ as a test function and integrating over $T$ we get by the definition of the numerical scheme for $k=1,\ldots,p$ that
    \begin{align}
    \label{eq:test_fun}
        \int_T \Big(\partial_t y_\TT(t)-\partial_t y_{\widehat\TT}(t)\Big)l_k(t) dt=\int_T\Big(F(t,y_\TT(t))-F(t,y_{\widehat\TT}(t)) \Big)l_k(t) dt + \int_T R(t) l_k(t) dt.
    \end{align}
    Since the integrand on the left-hand side of \eqref{eq:test_fun} is a polynomial of order at most $2p-2$, the $p$ point Gauss-Legendre quadrature integrates it exactly, i.e., by denoting the corresponding integration weights by $w_1, \ldots, w_p$, we get
    \begin{align*}
        \int_T \Big(\partial_t y_\TT(t)-\partial_t y_{\widehat\TT}(t)\Big)l_k(t) dt=\sum_{i=1}^p w_i |T| \Big(\partial_t y_\TT(\sigma_i)-\partial_t y_{\widehat\TT}(\sigma_i)\Big)l_k(\sigma_i)=w_k |T| \Big(\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)\Big).
    \end{align*}
    Since $l_k$ is uniformly bounded in $T$ by a constant only depending on $p$, we get by taking norms in \eqref{eq:test_fun} that all $k=1, \ldots, p$ satisfy
    \begin{align*}
       |T| |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)| \lesssim \int_T \Big|F(t,y_\TT(t))-F(t,y_{\widehat\TT}(t)) \Big|dt+ \int_T |R(t)|dt.
    \end{align*}
    Using the Lipschitz condition on $F$ shows
    \begin{align*}
       |T| |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)| &\lesssim L_1 \int_T \Big|y_\TT(t)-y_{\widehat\TT}(t) \Big|dt+ \int_T |R(t)|dt\\
        &=L_1 \int_T \Big|y_{\TT}(t_i)-y_{\widehat\TT}(t_i)+ \int_{t_i}^t \sum_{k=1}^p \partial_t (y_\TT(\sigma_k)-y_{\widehat\TT}(\sigma_k)) l_k(s) ds \Big|dt + \int_T |R(t)|dt
    \end{align*}
    The boundedness of the Lagrange polynomials implies
    \begin{align*}
       |T| |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)| &\lesssim |T|\Big(|y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|+|T|\sum_{k=1}^p |\partial_t (y_\TT(\sigma_k)-y_{\widehat\TT}(\sigma_k))| \Big) + \int_T |R(t)|dt.
    \end{align*}
    Summing up over $k=1,\ldots,p$, we get
    \begin{align*}
      |T| \sum_{k=1}^p |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)| &\leq C |T|\Big(|y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|+|T|\sum_{k=1}^p |\partial_t (y_\TT(\sigma_k)-y_{\widehat\TT}(\sigma_k))| \Big) + \int_T |R(t)|dt
    \end{align*}
    for some constant $C>0$. This can be rearranged to 
    \begin{align}
    \label{eq:deriv_esti}
        |T| \sum_{k=1}^p |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)|\leq C\frac{|T||y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|+\int_T |R(t)|dt}{1-C|T|}
    \end{align}
    if $|T|$ is sufficiently small enough (this can be guaranteed by a sufficiently fine initial mesh $\TT_0$).
    Note that with~\eqref{eq:parametrize} this shows for any $t \in T$ that
    \begin{align}
    \label{eq:end_estimate}
        |y_\TT(t)-y_{\widehat\TT}(t)| \lesssim \frac{1+C|T|}{1-C|T|} \Big(|y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|+\int_T |R(t)|dt\Big).
    \end{align}
    \emph{Step~2: }
    Let $[t_i,t_{i+1}]=T \in \TT \cap \widehat\TT$ be a non-refined element. Then we have by the definition of the numerical scheme that
    \begin{align*}
        \int_T \Big(\partial_t y_\TT(t)-\partial_t y_{\widehat\TT}(t)\Big)l_k(t) dt=\int_T\Big(F(t,y_\TT(t))-F(t,y_{\widehat\TT}(t)) \Big)l_k(t) dt.
    \end{align*}
    Analogously to Step~1, we get the estimates
    \begin{align}
        \label{deriv_esti_non_ref}
         |T| \sum_{k=1}^p |\partial_t y_\TT(\sigma_k)-\partial_t y_{\widehat\TT}(\sigma_k)|\leq C\frac{|T||y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|}{1-C|T|}\quad\text{and}\\
         \label{eq:end_estimate_non_ref}
          |y_\TT(t)-y_{\widehat\TT}(t)| \lesssim \frac{1+C|T|}{1-C|T|} \Big(|y_{\TT}(t_i)-y_{\widehat\TT}(t_i)|\Big).
    \end{align}
    We prove by mathematical induction that for all $t \in [t_i,t_{i+1}]=T \in \widehat\TT$, there holds
    \begin{align}
    \label{eq:induction_hyp}
        |y_\TT(t)-y_{\widehat\TT}(t)| \lesssim \prod_{j=0}^i \frac{1+C|t_{j+1}-t_j|}{1-C|t_{j+1}-t_j|} \sum_{T'=[t'_j,t'_{j+1}] \in \widehat\TT \setminus \TT, t'_{j+1}\leq t_{i+1}} \int_{T'} |R(t)| dt.
    \end{align}
    The base case $i=0$ follows from $y_{\TT}(t_0)=y_{\widehat\TT}(t_0)$ and \eqref{eq:end_estimate} or \eqref{eq:end_estimate_non_ref} accordingly. For the inductive step we consider two cases: First suppose that $[t_{i+1},t_{i+2}] \in \widehat\TT \setminus \TT$. In this case \eqref{eq:end_estimate} implies that
    \begin{align*}
        |y_\TT(t)-y_{\widehat\TT}(t)| \lesssim \frac{1+C|t_{i+2}-t_{i+1}|}{1-C|t_{i+2}-t_{i+1}|} \Big(|y_{\TT}(t_{i+1})-y_{\widehat\TT}(t_{i+1})|+\int_{t_{i+1}}^{t_{i+2}} |R(t)|dt\Big).
    \end{align*}
    Together with the induction hypothesis \eqref{eq:induction_hyp} this shows
    \begin{align*}
         |y_\TT(t)&-y_{\widehat\TT}(t)| \\&\lesssim \frac{1+C|t_{i+2}-t_{i+1}|}{1-C|t_{i+2}-t_{i+1}|} \Bigg( \prod_{j=0}^i \frac{1+C|t_{j+1}-t_j|}{1-C|t_{j+1}-t_j|} \sum_{T'=[t'_j,t'_{j+1}] \in \widehat\TT \setminus \TT, t'_{j+1}\leq t_{i+1}} \int_{T'} |R(t)| dt + \int_{t_{i+1}}^{t_{i+2}} |R(t)|dt\Bigg)\\
         &\lesssim \prod_{j=0}^{i+1} \frac{1+C|t_{j+1}-t_j|}{1-C|t_{j+1}-t_j|} \sum_{T'=[t'_j,t'_{j+1}] \in \widehat\TT \setminus \TT, t'_{j+1}\leq t_{i+2}} \int_{T'} |R(t)| dt.
    \end{align*}
    The case $[t_{i+1},t_{i+2}] \in \TT \cap \widehat\TT$ follows analogously using \eqref{eq:end_estimate_non_ref} instead of \eqref{eq:end_estimate}. This concludes the induction and proves \eqref{eq:induction_hyp}. Note that the denominators in the products are positive for sufficiently fine initial discretizations. From this and Lemma \ref{lem:prod_bound} below, we deduce immediately that
    \begin{align*}
        \norm{y_{\TT}-y_{\widehat\TT}}{L^2(T)}^2 \lesssim  |T| \sum_{T' \in \widehat\TT \setminus \TT}\int_{T'} |R(t)|^2 dt.
    \end{align*}
  Summing over all $T$ yields
    \begin{align}
        \label{eq:l2_esti_gen}
        \norm{y_{\TT}-y_{\widehat\TT}}{L^2([t_0,\tend])}^2 \lesssim \sum_{T' \in \widehat\TT \setminus \TT}\int_{T'} |R(t)|^2 dt.
    \end{align}
    \emph{Step~3:} It remains to prove the same estimate in the $H^1$-norm. To that end we have for $T \in \TT \cap \widehat\TT$ that
    \begin{align*}
        \norm{\partial_t y_\TT- \partial_t y_{\widehat\TT}}{L^2(T)}^2 =\int_T\Big(F(t,y_\TT(t))-F(t,y_{\widehat\TT}(t))\Big) \cdot \Big(\partial_t y_\TT(t)- \partial_t y_{\widehat\TT}(t) \Big)dt
    \end{align*}
    by the definition of the numerical scheme. Cauchy-Schwarz and Lipschitz continuity of $F$ give
    \begin{align}
        \label{eq:h1_non_ref}
        \norm{\partial_t y_\TT- \partial_t y_{\widehat\TT}}{L^2(T)} \leq L_1 \norm{y_{\TT}-y_{\widehat\TT}}{L^2(T)}.
    \end{align}
    For a refined element $T \in \widehat\TT \setminus \TT$, we have that
    \begin{align*}
        \norm{&\partial_t y_\TT- \partial_t y_{\widehat\TT}}{L^2(T)}^2\\
        &=\int_T \Big(F(t,y_\TT(t))-F(t,y_{\widehat\TT}(t))\Big) \cdot \Big(\partial_t y_\TT(t)- \partial_t y_{\widehat\TT}(t) \Big)dt+ \int_T R(t) \cdot \Big(\partial_t y_\TT(t)- \partial_t y_{\widehat\TT}(t) \Big)dt.
    \end{align*}
    Lipschitz continuity and Cauchy-Schwartz again give
    \begin{align}
        \label{eq:h1_ref}
        \norm{\partial_t y_\TT- \partial_t y_{\widehat\TT}}{L^2(T)} \leq L_1 \Big(\norm{y_{\TT}-y_{\widehat\TT}}{L^2(T)}+\norm{R}{L^2(T)} \Big).
    \end{align}
    Summing over all $T$ using \eqref{eq:h1_non_ref} and \eqref{eq:h1_ref} yields that
    \begin{align*}
        \norm{\partial_t y_\TT- \partial_t y_{\widehat\TT}}{L^2([t_0,\tend])}^2 \lesssim \norm{y_{\TT}-y_{\widehat\TT}}{L^2([t_0,\tend])}^2+ \sum_{T' \in \widehat\TT \setminus \TT}\int_{T'} |R(t)|^2 dt.
    \end{align*}
    Using the $L^2$ estimate \eqref{eq:l2_esti_gen} thus concludes the proof.
    \end{proof}
On the way to linear convergence~\eqref{eq:linconv} of the estimator sequence we finally need~(A3) \emph{quasi-orthogonality}.
However, to deal with nonlinear problems, we need to introduce a linearization of \eqref{eq:ode}. With the solution $y$ of~\eqref{eq:ode}, we state the linearized problem.
\begin{align}
\label{eq:ode_lin_gen}
    \begin{split}
        \partial_t \widetilde{y}(t)&=F(t,y(t))+\nabla_yF(t,y(t))\Big( \widetilde{y}(t)-y(t)\Big) \quad \text{for} \quad t \in [t_0, \tend] \\
        \widetilde{y}(t_0)&=y_0.
    \end{split}
\end{align}
Note that since the right-hand side is Lipschitz continuous by definition, $\widetilde{y}=y$ is the unique solution of \eqref{eq:ode_lin_gen}. We discretize \eqref{eq:ode_lin_gen} on the same time mesh $\TT$ and with the same method we used for the non-linear problem, i.e., find an approximate solution $\widetilde{y}_\TT \in S^p(\TT)$ such that
\begin{align}
\label{eq:lin_disc_gen}
    \begin{split}
        \int_{t_0}^{\tend}\Big(\partial_t \widetilde{y}_\TT(t)-F(t,y(t))+\nabla_yF(t,y(t))\Big( \widetilde{y}_\TT(t)-y(t)\Big) \Big)\cdot v(t) dt &=0,\\
    \widetilde{y}_{\TT}(t_0)&=y_0,
    \end{split}
\end{align}
for all $v \in \PP^{p-1}(\TT)$. Note that this auxiliary approximation serves theoretical purposes only and need not be computed. We are ready to state a lemma which will bound the difference between $y_\TT$ and $\widetilde{y}_\TT$.
\begin{lemma}
    \label{lem:lin_min_nonlin_gen}
     Let the right-hand side $F$ from~\eqref{eq:ode} satisfy \eqref{eq:Lip}--\eqref{eq:JacLip} and the let initial discretization $\TT_0$ be sufficiently fine. Then, we have for solutions $y_\TT$ of $\eqref{eq:gen_disc}$ and $\widetilde{y}_\TT$ of \eqref{eq:lin_disc_gen}
    \begin{align*}
        \norm{\widetilde{y}_\TT-y_\TT}{H^1([t_0,\tend])} \leq C \norm{y-y_\TT}{H^1([t_0,\tend])}^2,
    \end{align*}
    where the constant $C>0$ is independent of $\TT$.
\end{lemma}
\begin{proof}
    Define $w=\widetilde{y}_\TT-y_\TT$ and $a(t)=F(t,y(t))-F(t,y_\TT(t))+\nabla_y F(t,y(t))\Big( y_\TT(t)-y(t)\Big)$. Note that due to the assumptions on $F$, Taylor expansion shows that $a(t)=\mathcal{O}(|y_\TT(t)-y(t)|^2)$, where the implied constants do not depend on $t$. Let $[t_i, t_{i+1}]=T \in \TT$.  For every $k= 1.\ldots, p$ it holds by the definition of the numerical scheme that
    \begin{align}
    \label{eq:diffeq}
        \int_T \partial_t w(t)l_k(t)dt=\int_T \Big(a(t)+\nabla_yF(t,y(t))w(t) \Big)l_k(t)dt,
    \end{align}
    which, as in the proof of Lemma \ref{lem:gen_reldisc}, shows together with the boundedness of $\nabla_yF(t,y(t))$ that for all $t \in T$, we have
    \begin{align*}
        |w(t)| \lesssim \frac{1+C|T|}{1-C|T|}\Big(|w(t_i)|+\int_T|a(t)|dt \Big).
    \end{align*}
    By a similar inductive argument as in the proof of Lemma~\ref{lem:gen_reldisc} and using that $w(t_0)=0$, we show for $t \in T=[t_i,t_{i+1}]$ that
    \begin{align*}
        |w(t)| \lesssim \prod_{j=0}^{i}\frac{1+C|t_{j+1}-t_j|}{1-C|t_{j+1}-t_j|} \int_{t_0}^{t_{i+1}}|a(t)|dt,
    \end{align*}
    which, together with the boundedness of the product by Lemma \ref{lem:prod_bound} below, implies the bound
    \begin{align*}
        \norm{w}{L^2([t_0,\tend])} \lesssim \int_{t_0}^{\tend}|a(t)|dt =\mathcal{O}\Big(\norm{y_\TT-y}{L^2([t_0,\tend])}^2\Big).
    \end{align*}
    By choosing $\partial_t w$ as a test function in \eqref{eq:diffeq} and with the boundedness of $\nabla_yF(t,y(t))$, we infer
    \begin{align*}
        \norm{\partial_t w}{L^2([t_0,\tend])} \lesssim \norm{a}{L^2([t_0,\tend])}+\norm{w}{L^2([t_0,\tend])}.
    \end{align*}
    Inserting the $L^2$ estimate, we conclude the proof.
\end{proof}
For the next result, we use an equivalent weak formulation of \eqref{eq:lin_disc_gen} as introduced in \cite{generalqo}. Find $\widetilde{y}_\TT \in S^p(\TT)$ such that $\widetilde{y}_\TT(t_0)=0$ and all $v \in \PP^{p-1}(\TT)$ satisfy
\begin{align}
\label{eq:weak_lin_gen}
    a(\widetilde{y}_\TT,v)= \int_{t_0}^{\tend}\Big(F(t,y(t))- \nabla_y F(t,y(t))(y(t)-y_0) \Big) \cdot v(t) dt,
\end{align}
where 
\begin{align*}
    a(\widetilde{y}_\TT,v)=\int_{t_0}^{\tend}\Bigg(\partial_t  \widetilde{y}_\TT(t)-\nabla_yF(t,y(t))\widetilde{y}_\TT(t) \Bigg) \cdot v(t) dt
\end{align*}
for $\widetilde{y}_\TT \in \mathcal{X}_\TT=\{u \in S^p(\TT): u(t_0)=0\}$ and $v \in  \mathcal{Y}_\TT = \PP^{p-1}(\TT)$.
Note that $\widetilde{y}_\TT(t)+y_0$ will solve \eqref{eq:lin_disc_gen}. The weak formulation $\eqref{eq:weak_lin_gen}$ fits into the abstract framework of \cite{generalqo}.

 We will equip $\mathcal{X}_\TT$ and $\mathcal{Y}_\TT$ with the norms $\norm{\cdot}{H^1([t_0,\tend])}$ and $\norm{\cdot}{L^2([t_0,\tend])}$,  respectively. Continuity of $a(\cdot,\cdot)$ follows trivially. Moreover, we have inf-sup stability as shown in the following lemma.
\begin{lemma}
    \label{lem:infsup_gen}
     If the right-hand side $F$ from~\eqref{eq:ode} satisfies \eqref{eq:Lip}--\eqref{eq:JacLip} and the initial discretization $\TT_0$ is sufficiently fine, $a(\cdot,\cdot)$ is uniformly inf-sup stable in the sense that for all $\TT$ which can be obtained by some refinement of $\TT_0$,
    \begin{align}
         \inf_{u \in \mathcal{X}_{\TT}} \sup_{v \in \mathcal{Y}_{\TT}} \frac{a(u,v)}{\norm{u}{\mathcal{X}_{\TT}} \norm{v}{\mathcal{Y}_{\TT}}} \geq \gamma >0.
    \end{align}
    The constant $\gamma$ does not depend on $\TT$.
\end{lemma}
\begin{proof}
    Let $\TT\in\T$ be an arbitrary refinement of $\TT_0$ and let $\widetilde{y}_{\TT} \in \mathcal{X}_{\TT}$. Choose $v(t)=\Pi_{p-1} \Big( \partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)  \Big)$,  where $\Pi_{p-1}: L^2([t_0,\tend],\R^d) \to \PP^{p-1}(\TT)$ denotes the $L^2$-orthogonal projection onto piecewise polynomials of degree $p-1$.
    Substituting into the bilinear form yields
     \begin{align}
     \label{eq:bilin_gen}
     \begin{split}
         a(\widetilde{y}_{\TT},v)&=\int_{t_0}^{\tend}\Big(\partial_t  \widetilde{y}_{\TT}(t)-\nabla_yF(t,y(t))\widetilde{y}_{\TT}(t) \Big) \cdot v(t) dt\\
    &=\int_{t_0}^{\tend}\Big(\partial_t  \widetilde{y}_{\TT}(t)-\nabla_yF(t,y(t))\widetilde{y}_{\TT}(t) \Big) \cdot \Big( \partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big) dt \\
    &\qquad +\int_{t_0}^{\tend}\Big(\partial_t  \widetilde{y}_{\TT}(t)-\nabla_yF(t,y(t))\widetilde{y}_{\TT}(t) \Big) \cdot \Big(v(t)- \Big(\partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big)\Big) dt\\
    &:= {\rm I} + {\rm II}.
     \end{split}
     \end{align}
     To analyze the first term, we notice
     \begin{align}
     \label{eq:ode_self_gen}
          \partial_t \widetilde{y}_{\TT}(t)=\nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)+ \partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t).
     \end{align}
      Integrating from $t_0$ to $t$ yields, with a constant only depending on an upper bound for $\nabla_yF(t,y(t))$, that
      \begin{align*}
          |\widetilde{y}_{\TT}(t)| \leq C_F \int_{t_0}^{t}|\widetilde{y}_{\TT}(s)|ds + \int_{t_0}^{t} |\partial_t \widetilde{y}_{\TT}(s)- \nabla_yF(s,y(s))\widetilde{y}_{\TT}(s)| ds.
      \end{align*}
      Gronwall's lemma gives
      \begin{align}
        \label{eq:esti_l2_gen}
          |\widetilde{y}_{\TT}(t)| \lesssim \int_{t_0}^{t} |\partial_t \widetilde{y}_{\TT}(s)- \nabla_yF(s,y(s))\widetilde{y}_{\TT}(s)| ds.
      \end{align}
      Integrating the square of \eqref{eq:ode_self_gen} shows
       \begin{align}
     \label{eq:bound1_gen}
         \norm{\partial_t \widetilde{y}_{\TT}}{L^2([t_0,\tend])}^2 \lesssim \Big( \int_{t_0}^{\tend} \Big|\nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big|^2 dt+\int_{t_0}^{\tend} \Big| \partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big|^2 dt \Big).
     \end{align}
     Since $\nabla_yF(t,y(t))$ is bounded,~\eqref{eq:esti_l2_gen} implies
     \begin{align*}
         \norm{\partial_t \widetilde{y}_{\TT}}{L^2([t_0,\tend])}^2 \lesssim \norm{\partial_t \widetilde{y}_{\TT}- \nabla_yF(\cdot,y(\cdot))\widetilde{y}_{\TT}}{L^2([t_0,\tend])}^2 = {\rm I}.
         \end{align*}
         This concludes the estimate for the first term on the right-hand side of \eqref{eq:bilin_gen}.
     For the second term, we need to bound $\Big|v(t)- \Big(\partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big)\Big|$. Since $\partial_t \widetilde{y}_{\TT} \in \PP^{p-1}(\TT)$, we have $\Pi_{p-1}\partial_t \widetilde{y}_{\TT}=\partial_t \widetilde{y}_{\TT}$. Moreover, with the Lagrange polynomials already used in the proof of Lemma~\ref{lem:gen_reldisc}, we have for $t \in \TT$ that
     \begin{align}
     \begin{split}
         \int_T\Big|v(t)- \Big(&\partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big)\Big|^2dt \\
         &\leq \int_T\Big|\sum_{k=1}^pl_k(t)\nabla_yF(\sigma_k,y(\sigma_k))y_{\TT}(\sigma_k)-\nabla_yF(t,y(t))y_{\TT}(t)\Big|^2 dt\\
         &\lesssim \sum_{k=1}^p \int_T  |l_k(t) y_{\TT}(\sigma_k)|^2\Big|\nabla_yF(\sigma_k,y(\sigma_k))- \nabla_yF(t,y(t))\Big|^2 dt\\
         &\qquad+ \int_T  |\nabla_yF(t,y(t))|^2\Big|\sum_{k=1}^pl_k(t) y_{\TT}(\sigma_k)-y_{\TT}(t) \Big|^2 dt. 
         \end{split}
     \end{align}
     By using interpolation estimates for polynomials and the Lipschitz continuity of $\nabla F$ and differentiability of $y$ this yields
     \begin{align*}
         \int_T\Big|v(t)-& \Big(\partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big)\Big|^2dt \\
         &\lesssim \sum_{k=1}^p \int_T  |l_k(t) y_{\TT}(\sigma_k)|^2\|T|^2 \Big(||\partial_ty||_{L^\infty((t_0,\tend))}+1\Big)^2 dt+ |T|^2\norm{\partial_t y_{\TT}}{L^2(T)}^2.
     \end{align*}
     Norm equivalence on the finite dimensional space $\PP^p(T)$ together with a scaling argument conclude
     \begin{align*}
         \norm{v(t)- \Big(\partial_t \widetilde{y}_{\TT}(t)- \nabla_yF(t,y(t))\widetilde{y}_{\TT}(t)\Big)}{L^2(T)} \lesssim |T| \Big(\norm{y_{\TT}}{L^2(T)}+\norm{\partial_t y_{\TT}}{L^2(T)} \Big).
     \end{align*}
     Summing all $T$ and Poincaré inequality combined with Cauchy-Schwartz yields an upper bound for the second term in \eqref{eq:bilin_gen} of the form
    \begin{align}
     \label{eq:bound2_gen}
         {\rm II}\leq C_F \max_{T \in \TT} |T| \norm{\partial_t \widetilde{y}_{\TT}}{L^2([t_0,t_{\rm end}])},
     \end{align}
     where $C_F$ is independent of the mesh.
     Therefore, we obtain with \eqref{eq:bound1_gen} and \eqref{eq:bound2_gen} the bound
     \begin{align*}
          a(\widetilde{y}_{\TT},v) \gtrsim  (1-C_F\max_{T \in \TT_0} |T|) \norm{\partial_t \widetilde{y}_{\TT}}{L^2([t_0,\tend])}^2,
     \end{align*}
     where the term in the brackets is positive if the initial discretization is sufficiently fine. With $\norm{v}{L^2([t_0,\tend])} \lesssim \norm{\partial_t \widetilde{y}_{\TT}}{L^2([t_0,\tend])}$, we conclude the proof.
\end{proof}
Let us investigate the boundedness of the product used in the preceding lemmas.
\begin{lemma}
\label{lem:prod_bound}
    Let $\theta=1/2, \lambda>0$ and $\{\tau_n\} \subset \R^+$ such that $\sum_n \tau_n=S< \infty$ and $1-\theta \lambda \tau_n>1-\theta \lambda c>0, c >0$, for all $n \in \N$. Then
    \begin{align*}
        \prod_n \frac{1+ \theta \lambda \tau_n}{1-\theta \lambda \tau_n} \leq \exp \Big(S \theta \lambda-\frac{S}{c}\log(1-\theta \lambda c) \Big).
    \end{align*}
\end{lemma}
\begin{proof}
    For the numerator it holds that
    \begin{align*}
        1+\theta \lambda \tau_n \leq \exp(\theta \lambda \tau_n),
    \end{align*}
    which yields
    \begin{align*}
        \prod_n (1+\theta \lambda \tau_n) \leq \exp (S \theta \lambda).
    \end{align*}
    For the denominator we have
    \begin{align*}
        \log(1-\theta \lambda \tau_n) \geq \frac{\tau_n}{c}\log(1-\theta \lambda c)
    \end{align*}
    because of the concavity of $\log(1-\cdot)$. This yields
    \begin{align*}
        \log\Bigg(\prod_n (1-\theta \lambda \tau_n) \Bigg) \geq \frac{S}{c}\log(1-\theta \lambda c).
    \end{align*}
    Combining both estimates concludes the proof.
\end{proof}
We are now ready to prove quasi-orthogonality (A3). To that end, we consider a sequence of sequentially refined meshes $\TT_{\ell}$ for $\ell \geq 0$ and  the corresponding solutions $y_{\ell}\in \SS^p(\TT_\ell)$ of \eqref{eq:gen_disc} as well as $\widetilde{y}_{\ell}\in \SS^p(\TT_\ell)$ of \eqref{eq:lin_disc_gen}. 
    \begin{lemma}
        \label{lem:quasi_ortho}
        Let the right-hand side $F$ from~\eqref{eq:ode} satisfy \eqref{eq:Lip}--\eqref{eq:JacLip} and let the initial discretization $\TT_0$ be sufficiently fine. Then, $y_{\ell}$ satisfies general quasi-orthogonality in the sense that there exist a function $C:\N \to \R$ and $\eps>0$ small such that for every $\ell,N \in \N$ we have
        \begin{align*}
            \sum_{k=\ell}^{\ell+N} \norm{y_{k+1}-y_k}{H^1([t_0,\tend])}^2-\eps \eta_{\TT_k}^2 \leq C(N) \norm{y-y_{\ell}}{H^1([t_0,\tend])}^2,
        \end{align*}
        where $C(N)=\mathcal{O}(N^{1-\delta})$ for some $\delta>0$.
    \end{lemma}
\begin{proof}
    Let $\ell,N \in \N$, we have
    \begin{align*}
        \sum_{k=\ell}^{\ell+N}& \norm{y_{k+1}-y_k}{H^1([t_0,\tend])}^2\\
        & \leq  3\sum_{k=\ell}^{\ell+N} \Big(\norm{y_{k+1}-\widetilde{y}_{k+1}}{H^1([t_0,\tend])}^2+\norm{y_k-\widetilde{y}_k}{H^1([t_0,\tend])}^2+\norm{\widetilde{y}_{k+1}-\widetilde{y}_k}{H^1([t_0,\tend])}^2\Big).
    \end{align*}
    The result~\cite[Lemma 9]{generalqo} shows that Lemma \ref{lem:infsup_gen} implies general quasi-orthogonality with $C(N)=\mathcal{O}(N^{1-\delta})$, i.e.,
    \begin{align*}
         \sum_{k=\ell}^{\ell+N} \norm{y_{k+1}-y_k}{H^1([t_0,\tend])}^2\leq C(N) \norm{y-y_{\ell}}{H^1([t_0,\tend])}^2
    \end{align*}
    for all $\ell,N\in\N$, if the initial mesh is fine enough. Lemma \ref{lem:lin_min_nonlin_gen} implies that with a constant $C_{ \rm orth}$ independent of the mesh, there holds
    \begin{align*}
        \sum_{k=\ell}^{\ell+N} &\norm{y_{k+1}-y_k}{H^1([t_0,\tend])}^2 \\
        &\leq C_{\rm orth} \sum_{k=\ell}^{\ell+N} \Big(\norm{y-y_k}{H^1([t_0,\tend])}^4+ \norm{y-y_{k+1}}{H^1([t_0,\tend])}^4 \Big) +C(N)\norm{y-\widetilde{y}_{\ell}}{H^1([t_0,\tend])}^2.
    \end{align*}
    Using reliability from Lemma \ref{lem:gen_reliability} together with stability and reduction (Lemmas \ref{lem:gen_stability}--\ref{lem:gen_reduction}) and choosing the initial mesh sufficiently fine such that $\norm{y-y_{\ell}}{H^1([t_0,\tend])} \leq \eps$ (this is possible because of the convergence of our method on uniform meshes, see Lemma \ref{lem:unifconv}), we get
    \begin{align*}
         \sum_{k=\ell}^{\ell+N} \norm{y_{k+1}-y_k}{H^1([t_0,\tend])}^2-\eps \eta_{\TT_k}^2 &\leq C(N)\norm{y-\widetilde{y}_{\ell}}{H^1([t_0,\tend])}^2.
    \end{align*}
    Another application of Lemma \ref{lem:lin_min_nonlin_gen} to the right-hand side yields the result.
\end{proof}
Now we are ready to proof the main result of this section.
\begin{proof}[Proof of Theorem \ref{thm:optim}]
    Suppose $\TT_0$ is sufficiently fine such that all the Lemmas of this section are applicable. The results \cite[Lemma 3.5 \& 4.7]{Carstensen_2014} show that we can deduce \textit{estimator reduction} and \textit{quasi-monotonicity} from Lemmas \ref{lem:gen_reliability}, \ref{lem:gen_stability}--\ref{lem:gen_reduction}. Therefore, the requirements for \cite[Lemmas 5\& 6]{generalqo} are met. Together with \cite[Remark 7]{generalqo} and Lemma \ref{lem:quasi_ortho}, this shows for the estimator sequence from Algorithm \ref{alg:adaptive} that~\eqref{eq:linconv} holds for uniform constants $0 < q <1$ and $C_{\rm lin}>0$. With this we can use the results \cite[Prop. 4.12, 4.14, 4.15]{Carstensen_2014} together with Lemma \ref{lem:gen_reldisc} and obtain $0<\theta_\star<1$ such that Algorithm \ref{alg:adaptive} is rate-optimal~\eqref{eq:optimal}.

To show~\eqref{eq:runtime}, we introduce the notation ${\rm time}_\ell$ for the total runtime time in~\eqref{eq:runtime}. With~\eqref{eq:optimal} and~\eqref{eq:linconv}, ${\rm time}_\ell$  can be estimated by
\begin{align*}
    \text{time}_\ell \leq C_{\rm time}  \sum_{j=0}^\ell \#\TT_\ell
    &\leq C_{\rm time}C_{\rm best}^{1/s}C_{\rm opt}^{1/s} \sum_{j=0}^\ell \eta_{\TT_j}^{-1/s} \leq C_{\rm time}C_{\rm best}^{1/s}C_{\rm opt}^{1/s}C_{\rm lin}^{1/s}\eta_{\TT_\ell}^{-1/s} \sum_{j=0}^\ell q^{(\ell-j)/s}\\
    &\leq C_{\rm time}\frac{C_{\rm best}^{1/s}C_{\rm opt}^{1/s}C_{\rm lin}^{1/s}}{1-q^{1/s}}\eta_{\TT_\ell}^{-1/s}.
\end{align*}
This concludes the proof.


\end{proof}



