The system matrices on the coarse levels are reassembled according to the BE-FE discretisation method, rather than using Galerkin projection which is commonly used in spatial multigrid methods for topology optimisation \cite{amir2014_topOptMG, aage2015_openSourceTopOpt}. When applying $x$-coarsening or full space-time coarsening, the coefficients $k$ and $c$ on the coarse levels are computed as being averages of $k$ and $c$ on the finer levels like so:
\begin{subequations}
    \begin{align}
        k_e^{(l+1)} &= \frac{ k_{2e}^{(l)} + k_{2e+1}^{(l)} }{2} 
        \\
        c_e^{(l+1)} &= \frac{ c_{2e}^{(l)} + c_{2e+1}^{(l)} }{2} 
    \end{align}
\end{subequations}
where $k_e^{(l)}$ and $c_e^{(l)}$ are the material parameters of the $e$\tss{th} element on the $l$\tss{th} level.  


This work exclusively considers multigrid V-cycles, the pseudocode of which is presented in Algorithm \ref{alg: stmg v cycle}. In this context, level $l=1$ is the finest level, $N_l$ denotes the number of levels, $\mbf{z}^{(l+1)}$ is the coarse grid correction vector, and $\nu$ denotes the number of pre- and post-smoothing steps. In this paper, $\nu=5$ unless stated otherwise. %Here the V-cycle function is formulated such that it accepts the level, $l$, a guess solution, $\mbf{u}^{(l)}$, and a source term, $\mbf{b}^{(l)}$, as input arguments, and returns a better estimate of $\mbf{u}^{(l)}$

\begin{algorithm}%[htbp]
\caption{$\mathrm{VCycle}(l, \mbf{u}^{(l)}, \mbf{b}^{(l)})$}
\label{alg: stmg v cycle}
\begin{algorithmic}[1]
    \IF{$l = N_l$}
        \STATE Solve for $\mbf{u}^{(l)}$ in the equation $\mbf{J}^{(l)} \mbf{u}^{(l)} = \mbf{b}^{(l)}$
        \RETURN $\mbf{u}^{(l)}$
    \ELSE
        \STATE Perform $\nu$ smoothing steps on $\mbf{J}^{(l)} \mbf{u}^{(l)} = \mbf{b}^{(l)}$
        \STATE $\mbf{b}^{(l+1)} \gets \mbf{R}^{(l)} \left( \mbf{b}^{(l)} - \mbf{J}^{(l)} \mbf{u}^{(l)} \right)$
        \STATE $\mbf{z}^{(l+1)} \gets \mathrm{VCycle}(l+1, \mbf{0}, \mbf{b}^{(l+1)})$
        \STATE $\mbf{u}^{(l)} \gets \mbf{u}^{(l)} + \mbf{P}^{(l)} \mbf{z}^{(l+1)}$
        \STATE Perform $\nu$ smoothing steps on $\mbf{J}^{(l)} \mbf{u}^{(l)} = \mbf{b}^{(l)}$
        \RETURN $\mbf{u}^{(l)}$
    \ENDIF
\end{algorithmic}
\end{algorithm}


The initial guess for the vector of unknowns is $\mbf{u} = \mbf{0}$. The relative residual after $n$ cycles is defined as:
\begin{align}
    r_n &= \frac{\lVert \mbf{J} \mbf{u}_n - \mbf{b} \rVert}{\lVert \mbf{b} \rVert} 
\end{align}
where $\mbf{u}_n$ is $\mbf{u}$ after the $n$\tss{th} cycle and $\lVert \cdot \rVert$ is the Euclidian norm. The multigrid method is terminated after the $n$\tss{th} cycle if the following condition is true:
\begin{align}
    \label{eq: stmg termination criterion}
    r_n < 10^{-9} \text{ or } r_n > 10^{9} \text{ or } n = 100
\end{align}
An estimate of the convergence factor is then computed as:
\begin{align}
    \text{Estimated convergence factor} &= \left( 
    r_N  /  r_0 
    \right)^{1/N}
\end{align}
where $N$ is the number of completed cycles. During testing, it was found that this estimate often depends noticeably on the imposed heat load function, $q(x,t)$. For the sake of consistency, the imposed heat load is set to the following in every test presented in this paper:
\begin{align}
    q_{e,j} &= \left( 1 + \cos \left\{ 200 \cdot \left[ \left( x_e/L - 1/2 \right)^2 + \left( t_j/t_T - 1/2 \right)^2 \right] \right\} \right) \cdot 10^6 \, \mathrm{W/m^3} 
    \label{eq: heat load def}
\end{align}
where $q_{e,j}$ is the heat imposed on the $e$\tss{th} element at $t=t_j$. This function is plotted is Figure \ref{fig: heat load plot}. This is not a realistic heat load in the context of practical heat conduction problems. Instead, the motivation behind the above expression is to expose the multigrid method to an input which contains many different frequencies. This seemed to produce more pessimistic estimates of the convergence factor than, for example, setting $q(x,t)$ to be constant over both $x$ and $t$. 

