\section{Discrete potential SIEs: method of moments}\label{sec4}
In this section, we briefly present the method of moments (MoM)~\cite{harrington68} to discretize the SIE~\eqref{eq:SIE_Phi_A}. As mentioned in Section~3, the interior domain $\Omega_2$ is approximated by a simplicial complex, and the boundary of this simplicial complex---a surface triangulation---approximates $\GA$. The boundary mesh consists of $N_2^\Par$ boundary triangles, $N_1^\Par$ boundary edges, and $N_0^\Par$ boundary nodes. The position vectors of the boundary nodes are denoted by $\rs_n$, $n = 1,\ldots, N_0^\Par$. The scalar fields $\alpha$ and $\beta$ in Eq.~\eqref{eq:SIE_Phi_A} are approximated by a finite expansion in nodal basis functions $h_n(\rs)$ as
\begin{equation}\label{SolApprox}
   \alpha(\rs)  \approx \sum\limits_{n = 1}^{N_0^\Par} \alpha_n h_n(\rs), \quad
   \beta(\rs)   \approx \sum\limits_{n = 1}^{N_0^\Par} \beta_n h_n(\rs),
\end{equation}
where $\alpha_n := \alpha(\rs_n)$ and $\beta_n := \beta(\rs_n)$. The basis functions $\set{h_n(\rs)}_{n = 1}^{N_0^\Par}$ are linear functions defined over each boundary triangle using barycentric coordinates, and satisfy $h_m(\rs_n) = \delta_{mn}$.

For each boundary triangle $T_m, m = 1,\ldots,N_2^\Par$, with vertex position vectors $\rs_1^{(m)}, \rs_2^{(m)}$, and $\rs_3^{(m)}$, a point $\rs\in T_m$ is associated with barycentric coordinates  $\lambda_1^{(m)}(\rs)$, $\lambda_2^{(m)}(\rs)$, and $\lambda_3^{(m)}(\rs)$. Defining
\[
\vv := \rs - \rs_3^{(m)}, \quad \vv_1 := \rs_1^{(m)}-\rs_3^{(m)}, \quad \vv_2 := \rs_2^{(m)}-\rs_3^{(m)},
\]
the barycentric functions $\lambda_1^{(m)}$, $\lambda_2^{(m)}$, and $\lambda_3^{(m)}$ are given by
\begin{equation}
    \lambda_1^{(m)}(\rs) = \frac{ \cbrc{ \vv \cdot \vv_1 } \norm{ \vv_2 }^2 - \cbrc{ \vv \cdot \vv_2 } \cbrc{ \vv_1 \cdot \vv_2 } }{ 4 S_m^2 }, \quad \rs \in T_m,
\end{equation}
\begin{equation}
    \lambda_2^{(m)}(\rs) = \frac{ \cbrc{ \vv \cdot \vv_2 } \norm{ \vv_1 }^2 - \cbrc{ \vv \cdot \vv_1 } \cbrc{ \vv_1 \cdot \vv_2 } }{ 4 S_m^2 }, \quad \rs \in T_m,
\end{equation}
and
\begin{equation}
    \lambda_3^{(m)}(\rs) = 1 - \lambda_1^{(m)}(\rs) - \lambda_2^{(m)}(\rs).
\end{equation}
Here, $S_m$ is the area of $T_m$, and we have used the identity
\begin{equation}
    \norm{ \vv_1 \times \vv_2 }^2 = \norm{ \vv_1 }^2 \norm{ \vv_2 }^2 - \cbrc{ \vv_1 \cdot \vv_2 }^2 = 4 S_m^2,
\end{equation}
which relates the triangle area to the edge vectors $\vv_1$ and $\vv_2$. 

With $h_m(\rs)$ defined, we first substitute Eqs.~\eqref{SolApprox} into Eq.~\eqref{eq:SIE_Phi_A} to obtain 
\begin{equation}\label{Eq::Phi_OUT}
\frac{1}{2}\sum\limits_{n = 1}^{N_0^\Par} \alpha_n h_n(\rs) - \sum\limits_{n = 1}^{N_0^\Par} \alpha_n \brc{\int_{\GA} \frac{\partial \G (\rs,\rt)}{\partial\nn(\rt) } h_n(\rt) d\GA(\rt)} + \sum\limits_{n = 1}^{N_0^\Par} \beta_n \brc{\int_{\GA} \G (\rs,\rt) h_n(\rt) d\GA(\rt)} =  \inc{\alpha}(\rs).
\end{equation}
Second, Eq.~\eqref{Eq::Phi_OUT} is tested against $ h_m(\rs),\,m = 1,\ldots,{N_0^\Par}$, to obtain the linear system
\begin{equation}\label{eq:main_SIE}
\bmsf{D}\,{\boldsymbol{\alpha}} + \bmsf{S}\,{\boldsymbol{\beta}} = \boldsymbol{f}_{\alpha}.
\end{equation}
Here, ${\boldsymbol{\alpha}} $ and ${\boldsymbol{\beta}} $ are $N_0^\Par$-dimensional column vectors, with their respective $n$th components given by $\alpha_n$ and $\beta_n$. The entries of the $N_0^\Par\times N_0^\Par$ matrices $\bmsf{D}$ and $\bmsf{S}$, denoted by $[\bmsf{D}]_{m,n}$ and $[\bmsf{S}]_{m,n}$, respectively, are given by
\begin{equation}\label{EqZ0}
    [\bmsf{D}]_{m,n} =  \frac{1}{2} \int\limits_{\GA} h_m(\rs)h_n(\rs) d\GA(\rs) -  \frac{1}{4\pi} \int\limits_{\GA} \,\int\limits_{\GA}{ h_m(\rs)h_n(\rt)   }\nn'\cdot \nabla'\frac{e^{ik_0 \abs{\rs-\rt}}}{\abs{\rs-\rt}} d\GA(\rt) d\GA(\rs),
\end{equation}
and
\begin{equation}\label{EqZ1}
   [\bmsf{S}]_{m,n} = \frac{1}{4\pi}   \int\limits_{\GA} \,\int\limits_{\GA}{ h_m(\rs)h_n(\rt)   }\frac{e^{ik_0 \abs{\rs-\rt}}}{  \abs{\rs-\rt}} d\GA(\rt) d\GA(\rs).
\end{equation}
The $m$th entry of $\boldsymbol{f}_{\alpha}$, denoted by $\brc{\boldsymbol{f}_{\alpha}}_m$ is given by
\begin{equation}\label{Eqb}
\brc{\boldsymbol{f}_{\alpha}}_m =    \int\limits_{\GA} { h_m(\rs)  \inc{\alpha}(\rs)} d\GA(\rs).
%%=========================================================================
\end{equation}
For more details on the evaluation of the matrices $\bmsf{D}$ and $\bmsf{S}$, the reader may refer to~\cite{graglia1993} and the references therein.
