%%%%%Algo
\begin{algorithm}[!hb]
% \vspace{-4mm}
    \caption{Runtime Schedule Selection Algorithm}
    \label{algo:Schedule_select_algo}
    \scriptsize
    \begin{algorithmic}[1]
        \Require{Schedule Array $\mathcal{A}$, Schedule vulnerability threshold $SVT$, Lookup table $LUT$, Detector flag $Atkflag$, current schedule $s_k$}
        \Ensure{next attack-aware schedule $s_{k^{\prime}}$}
        \Function{SchedSel}{$\mathcal{A}$, $SVT$, $LUT$, $Atkflag$, $s_k$} \Comment{Function}
            \State $K \gets \Call{IndexOfSVI}{\mathcal{A}, SVT}$ \Comment{Storing schedule index with SVI=SVT}\label{algflaginit}
            \State $k \gets \Call{IndexOf}{ s_k }, k^{\prime}\gets -1$\Comment{current and next schedule indices init}  \label{algdtcupdate}
            \If{$AtkFlag==0$}  \label{algifAtkFalse}
                \While{$k^{\prime} \neq k$} \label{algnosame}
                \State $k^{\prime} \gets rand( )\%K$ \Comment{ random index between [0,K)}\label{algnormalmoderand}
                \EndWhile
                \State $s^{\prime} \gets \mathcal{A}[k^{\prime}]$\Comment{Normal Mode}\label{algnormalmode}
            \ElsIf{$AtkFlag >0$} $i\gets AtkFlag$   \label{algifAtkTrue}\Comment{If attack detected on $\tau_i$}
                \While{$k \neq k^{\prime}$}  \label{algnosame1}
                % \State $s_{k^{\prime}} \gets GetRandSchedAP (\mathcal{A}, LUT[i])$;   \Comment{Alert Mode}\label{algalertmode}
                \State $M \gets \Call{LengthOf}{ LUT[i] }$\Comment{schedule count with AP below $TAP_i$ }\label{algalertmoderand0}
                %
                \State $ki \gets rand( )\% M$, $k'\gets LUT[i][ki]$ \Comment{random index $\in$[0,M-1]}\label{algalertmoderand}
                \EndWhile
                \State $s_{k^{\prime}} \gets \mathcal{A}[LUT[i][k^{\prime}]]$   \Comment{Alert Mode}\label{algalertmode}
            \EndIf
            \State\Return $s_{k^{\prime}}$; \label{algReturn}
        \EndFunction
    \end{algorithmic}
\end{algorithm}
\par 
% Explain Algo
\noindent The runtime algorithm in the MAARS framework 
% (blue transparent box in Fig.~\ref{fig: Overview_figure}\su{change}) 
is responsible for randomly deploying schedules in an attack-aware fashion. The runtime schedule selection function $\Call{SchedSel}{ }$ in Algo.~\ref{algo:Schedule_select_algo} takes the following inputs, \textbf{(i) } The lookup table $LUT$ and the stored schedule array $\mathcal{A}$, \textbf{(ii) }the $\chi^2$-detector flag $Atkflag$, \textbf{(iii) }the schedule vulnerability threshold $SVT$ and \textbf{(iv) }the schedule deployed in the current hyper-period $s_k$. 
The algorithm starts by storing the schedule index in $\mathcal{A}$, which has the same SVI as the input SVT. We use the $\Call{IndexOfSVI}{ }$ method, which takes the sorted schedule array $\mathcal{A}$ and the $SVT$ as inputs to find out this index and store in $K$ (see line~\ref{algflaginit}). In line~\ref{algdtcupdate}, by using $\Call{IndexOf}{ }$ method we find out the index $k$ of the input schedule $s_k$ that is currently deployed. Another variable, $k'$, is also initialised (with $-1$) to store the index of the next schedule. 
% Algo.~\ref{algo:Schedule_select_algo} Depending on the detector flag, the next schedule is selected. 
%
The algorithm has two distinct modes of schedule selection and deployment operations depending on the detector flag $Atkflag$. 
\par \noindent \emph{\textbf{(1) Normal mode: }} When there are no attack flags raised, i.e., $Atkflag=0$ denoting no attack on any control task, the algorithm operates in {\em Normal Mode} (lines~\ref{algnosame} to~\ref{algnormalmode}). In this mode, schedules with $SVI$ less than $SVT$ are randomly selected from the array $\mathcal{A}$. Line~\ref{algifAtkFalse} of the algorithm checks if the $AtkFlag$ value is zero. If it is zero, then the algorithm selects a random number in the range $[0,K-1]$ and stores it in $k'$ (see line~\ref{algnormalmoderand}). Since MAARS randomly deploys new non-vulnerable schedules at every hyper-period, the random schedule index $k'$ must not match with the currently deployed schedule index $k$. The algorithm keeps picking another random number until $k\neq k'$ for this purpose.
% , denoting a new schedule to be deployed in the next hyper-period 
(see the while loop in line~\ref{algnosame}). The next schedule $s_{k^\prime}$ is selected from the $k'$-th row of the schedule array $\mathcal{A}$ (see line~\ref{algnormalmode}).  
%
\par\noindent{\textbf{\em (2) Alert Mode: }} If the \emph{$\chi^2$-detector} running inside the control task raises an alarm by detecting an attack ($g[k]>Th\Rightarrow AtkFlag>0$, see Sec.~\ref{sec:detector_model}) on a control task $\tau_i$, the algorithm runs in {\em Alert mode}. In this mode, schedules are selected from the schedule array $\mathcal{A}$ such that the attack probability for the victim control task $\tau_i$ is lower than its tolerable attack probability $TAP_i$. In line~\ref{algifAtkTrue}, if $AtkFlag$ is non-zero, we first store its value in $i$. The value of the $Atkflg$ denotes a potential attack on task $\tau_i$. In line~\ref{algalertmoderand0}, we find out the length of the $i$-th row in $LUT$ and store it in $M$. This is used to find a random number $ki$ in the range $[0,M-1]$ (see line~\ref{algalertmoderand}). This number is then used to get the index of the next schedule $k'$ from the $ki$-th column and $i$-th row of $LUT$. Note that each such schedule index picked from LUT satisfies $AP_{<\tau_i,\mathcal{A}_k'>} < TAP_i$. As stated earlier, this random number selection is repeated if the index of the current schedule $k$ matches with the randomly picked next schedule index $k'$ (see the while loop in line~\ref{algnosame1}). We select the schedule $s_{k^\prime}$ from the $k'(\neq k)$-th row of $\mathcal{A}$ (see  line~\ref{algalertmode}). 
% The function \textsc{GetRandSchedAP}() selects the schedules that have $AP_{<\tau_i,s_k>} < TAP_i \ \forall \ \tau_i \in \Gamma_t$. The algorithm returns the randomly selected schedule as output in line~\ref{algReturn}.
\par Finally, $\Call{SchedSel}{ }$ returns the new schedule $s_k'$ for deployment. Algo~\ref{algo:Schedule_select_algo} is run once every hyper-period in order to select and deploy new schedules randomly. This online schedule selection is done in an attack-informed way. As a result, the vulnerability level of the task execution schedule is minimized while maintaining the system's performance. 
% We will now discuss the timing complexity of the runtime algorithm~\ref{algo:Schedule_select_algo} and the overall memory consumption after design-time analysis.
%%
\par \textbf{Overhead Analysis:}
The time complexity of Algo.~\ref{algo:Schedule_select_algo} depends on the complexity of selecting a random number so that it does not match the current value. Since we store the schedules in the sorted orders of SVI and AP in arrays, the algorithm can access them in $O(1)$.  
% In the normal mode of operation, a schedule is randomly selected between the $(0-K)$-th index of $\mathcal{A}$. In alert mode, the indices of $\mathcal{A}$ are already specified in LUT containing $I_s[M]$. We have used the C function $rand()$ for this purpose, which has a $O(1)$ complexity. Therefore, both \textsc{GetRandSchedSVI}() and \textsc{GetRandAP}() functions for randomly selecting schedules have $O(1)$ complexity. Therefore, the overall complexity of \textsc{SchedSel} in Algorithm~\ref{algo:Schedule_select_algo} is $\approx O(1)$.
% \su{cannot state, must give reason}.
% Therefore, the time required for search in Normal Mode is $O(1)$. In \emph{Alert Mode}, since the array $I_s[N]$ stores only the indices of schedules whose upper limit is $N$ elements in each row, the complexity for random selection is $O(1)$. Therefore in both situations, time complexity is $\approx O(1)$. The scheduler performs a table lookup at runtime to select the next job after each slot. 
The total memory cost for storing $\mathcal{A}$ and $LUT$ can also be calculated, assuming that each element(of the arrays) takes $b$ data bytes. Each schedule, therefore, comprises rows equal to the length of its hyper-period, say $l_k$ for the $k$-th schedule. Considering a total of $M$ schedules, the total cost is $(\sum_{k=1}^{M} l_k) \cdot b $ bytes.
% $l_k$ being the hyper-period length of the $k$-th schedule. 
$LUT$, is stored as a 2-D array of $q$ rows (number of trusted control tasks) and $M$ columns, the cost is $qM$. Hence, the total memory cost is  $\left[ qM + \left( \sum_{k=1}^{M} l_k \right) \cdot M \right] \cdot b\ \text{\textit {bytes}}$.
In the next section, we demonstrate the efficacy of this runtime schedule selection algorithm guided by the design-time analysis in real-time system setup.
