&
}}}
\end{equation}
%with $\varphi(x) = \tru$, $\varphi(y_1) = \tru \wedge x$, $\varphi(y_2) = \tru \wedge \neg x$, $\varphi(z_1) = \tru \wedge \neg x \wedge y_2$ and $\varphi(z_2) = \tru \wedge \neg x \wedge \neg y_2$. 
%In this case, we shall let $\lambda(x) = b_1$, $\lambda(y_1) = a_1$, $\lambda(y_2) = b_2$, $\lambda(z_1) = a_2$ and $\lambda(z_2) = a_3$.
Hence, every node $x$ labelled with a Boolean test yields a (binary) branch and its (two) successors have the same formula as $x$, with an extra conjunct that is either $x$ or $\neg x$, according to the outcome of the test.
With this in mind, \Cref{def:lpof}(4) is quite intuitive:
\begin{itemize}[leftmargin=*]
\item Requiring $\sat(\varphi(x))$ amounts to expressing the fact that every node $x$ is reachable, \ie there exists a truth assignment $v$ such that $v \models \varphi(x)$. The truth assignment tells, for every node labeled with a Boolean test, whether that test passes or not. In our example, $x_{a_3}$ is reachable when both the tests $b_1$ and $b_2$ fail; this is exactly what satisfiability of $\varphi(x_{a_3})$ entails (viz., that both $b_1$ and $b_2$ must be false to satisfy $\neg x_{b_1} \wedge \neg x_{b_2}$).
\item This intuition justifies the other two requirements of \Cref{def:lpof}(4): reachability of a node can only depend on the values of the tests that precede it (and so $\varphi(x)$ can only use nodes that precede $x$) and, since along a path we shall only add conjuncts, the formula of a higher-level node is stronger than the formulae of all of its predecessors.
\end{itemize}

Next, we define an order on \lpof s, which we will use for the construction of fixed points to give semantics to unbounded loops. The intuition is that $\alpha \lelpo \beta$ iff
$\beta$ has \emph{more behaviors} than $\alpha$, meaning that $\beta$ can be obtained by expanding $\bot$ nodes in $\alpha$ into larger structures (each  unfolding of a while-loop is obtained in this way, as shown in Section \ref{sec:pomset-semantics}).
%Appendix \ref{app:loops}). 
Since \lpof s can only be expanded from $\bot$ nodes, the label set $L$ must be pointed (\ie $\bot\in L$); however, the order on $L$ need not be flat: labels themselves can also become larger when passing from $\alpha$ to $\beta$ (\eg if actions are nondeterministic assignments from a given set, this corresponds to enlarging the set of possible choices). This can also be useful to model \emph{invariant sensitive execution}, introduced in Probabilistic Concurrent Outcome Logic \cite{zilberstein2024probabilistic}.
Notationally,
$\Bot_\alpha$ denotes the set of nodes labelled with $\bot$, \ie $\Bot_\alpha \triangleq  \{x \in N_\alpha \mid \lambda_\alpha(x) = \bot\}$.

\begin{definition}[Ordering on \lpof s]
\label{def:lelpo}
We let $\alpha \lelpo \beta$ iff:
\begin{enumerate}
\item\label{def:lelpo:N} $N_\alpha$ is a downward-closed subset of $N_\beta$, written $N_\alpha \dwclosed N_\beta$;
\medskip
\item \label{def:lelpo:<} $\mathord{<_\alpha} = \mathord{<_\beta} \cap (N_\alpha \times N_\alpha)$;
\medskip
\item $\forall x\in N_\alpha$:
\begin{enumerate*}
\item\label{def:lelpo:lambda} $\lambda_\alpha(x) \le \lambda_\beta(x)$;
\item $\varphi_\alpha(x) = \varphi_\beta(x)$;
\item\label{def:lelpo:succ} $\succ_\alpha(x) = \succ_\beta(x) \setminus \succplus{\Bot_\alpha}_\beta$.
\end{enumerate*}
\end{enumerate}
\end{definition}

\begin{example}\rm
Consider the following three \lpof s:
\[
\alpha =
\vcenter{\vbox{\xymatrix@R=5pt@C=6pt{
&
\\
y_1(\bot) && y_2
\\
& x \ar[ul]\ar[ur]
}}}
\qquad\qquad
\beta = 
\vcenter{\vbox{\xymatrix@R=5pt@C=6pt{
&& z
\\
y_1(\bot) && y_2 \ar[u]
\\
& x \ar[ul]\ar[ur]
}}}
\qquad\qquad
\gamma =
\vcenter{\vbox{\xymatrix@R=5pt@C=6pt{
& z
\\
y_1\ar[ur] && y_2 \ar[ul]
\\
& x \ar[ul]\ar[ur]
}}}
\]
where node $y_1$ is labelled with $\bot$ in $\alpha$ and $\beta$, whereas all other nodes have non-$\bot$ labels.
Following the intuition given above, both $\alpha$ and $\beta$ are attempts to specify that the computation in $\gamma$ is truncated at $y_1$.
However, only $\alpha \lelpo \gamma$; this is because, if $\bot$ represents a diverging computation, then $z$ will never have all the causes it needs to be executed and so it must disappear. Indeed, $\beta \nlelpo \gamma$ because, even though $N_\beta \dwclosed N_\gamma$, condition (3c) of \Cref{def:lelpo} is violated: $z \in \succ_\beta(y_2)$ but $z \not\in \succ_\gamma(y_2) \setminus \succplus{\Bot_\beta}_\gamma$, since $y_1 \in \Bot_\beta$ and $y_1 <_\gamma z$.
\end{example}

Finally, in order to find fixed points, we will need to have a directed complete partial order (\dcpo) structure and a notion of continuity for functions, which we now define. %at different points, and to obtain it we will incorporate ideas from \cite{meyer1988applications,meyer1989pomset,bakker1990metric}. 

\begin{definition}[\dcpo]
Given a poset $\tuple{X,\leq}$, a subset $D \subseteq X$ is called {\em directed} iff it is not empty and, for every two elements $x_1,x_2 \in D$, there exists $x \in D$ such that $x_1, x_2 \leq x$.

$\tuple{X,\leq}$ is a {\em directed complete partial order} (\dcpo) iff, for every directed set  $D$, $\sup D$ exists; furthermore, $\tuple{X,\leq}$ is called {\em pointed} if there exists an element $\bot \in X$ such that $\bot \le x$ for all $x\in X$.
\end{definition}

\begin{definition}[Scott Continuity]
Given two \dcpo s $\tuple{X, \le_X}$ and $\tuple{Y, \le_Y}$, a function $f \colon X \to Y$ is \emph{Scott Continuous} if it is monotone: $f(x) \le_Y f(x')$ for all $x \le_X x'$; and preserves suprema of directed sets: $\sup_{x\in D} f(x) = f(\sup D)$ for all $D \subseteq X$ directed.
\end{definition}

\begin{restatable}{lemma}{lposup}
\label{lem:lpo-sup}
For any directed set $D \subseteq \lpo(L)$, $\sup D = \tuple{N, <, \lambda, \varphi}$, where: 
  \begin{align*}
    N &\triangleq \bigcup_{\beta\in D} N_{\beta}
    &
    \mathord{<} &\triangleq \bigcup_{\beta\in D} \mathord{<_{\beta}}
    &
    \lambda(x) &\triangleq \sup_{\beta\in D\,:\,x \in N_{\beta}} \lambda_{\beta}(x)
    &
    \varphi(x) & \triangleq \psi_x
  \end{align*}
  and $\psi_x = \varphi_\beta(x)$, for all $\beta \in D$ such that $x\in N_\beta$.
\end{restatable}
In \Cref{lem:lpo-sup},  $\varphi$ is well defined since, for every $x \in \Nodes$ and $\beta,\beta' \in D$ that contain $x$, it must be that $\varphi_\beta(x) = \varphi_{\beta'}(x)$. Indeed, since $D$ is directed, there must exist a $\gamma \in D$ such that $\beta,\beta' \lelpo \gamma$ and, by \Cref{def:lelpo}(3b), we have that $\varphi_\beta(x) = \varphi_\gamma(x) = \varphi_{\beta'}(x)$.

Notice that $\lpo(L)$ is {\em not} pointed, since the node at the root can vary; hence, there is no single \lpof\ that is smaller (w.r.t. $\lelpo$) than all other \lpof s. This situation will change when moving to pomsets \Arefp{lem:pomdcpo}, which abstract away from the specific nodes.

\subsection{Pomsets with Formulae}

Although \lpof s express causality and branching behavior, they are not ideal semantic structures because information about node identifiers is extraneous. We instead work with \emph{partially ordered multisets} (pomsets), which abstract away from the specific names used.

\begin{definition}[\lpof\ Isomorphism]
\label{def:equivLPO}
Let $\alpha$ and $\beta$ be \lpof s and $f \colon N_\alpha \to N_\beta$ be a bijection between their nodes. Define $f(\alpha) = \tuple{ N, <, \lambda, \varphi }$ as
\begin{align*}
  N &\triangleq \{ f(x) \mid x\in N_\alpha \}
  &
  \mathord{<} &\triangleq \{ (f(x), f(y)) \mid x <_\alpha y \}
  &
  \lambda &\triangleq \lambda_\alpha \circ f^{-1}
  &
  \varphi &\triangleq f \circ \varphi \circ f^{-1}
\end{align*}
where $f(\psi)$ syntactically renames the variables of $\psi$ in the obvious way;
$\alpha$ and $\beta$ are isomorphic, written $\alpha \equiv \beta$, iff there is a bijection $f \colon N_\alpha \to N_\beta$ such that $f(\alpha) = \beta$.
\end{definition}


\begin{definition}[Pomsets with Formulae]
Let $[\alpha] \triangleq \{ \beta \in \lpo(L) \mid \alpha\equiv\beta \}$ be the isomorphism class of $\alpha$.
A pomset with formulae (or, simply, pomset) $\Alpha \in \pom(L)$ is an isomorphism class of \lpof s:
$
  \pom(L) \triangleq \{ [\alpha] \mid \alpha \in \lpo(L) \}
$.
%We say that a pomset
 %$[\alpha]$ is single-rooted if $\alpha$ is a single-rooted \lpof\ and that it
Let $\pom_\fin(L)$ be the set of pomsets with finitely many nodes. Finally, let $\Alpha \lepom \Beta$ iff $\forall \alpha \in \Alpha.\, \exists\beta\in \Beta.\ \alpha \sqsubseteq_\lpo \beta$.
\end{definition}




