  N &\triangleq N_\alpha \cup \bigcup_{\psi \in \br_\alpha} N_{\beta_\psi}
  &
  \mathord{<} &\triangleq \mathord{<_\alpha} \cup \smashoperator{\bigcup_{\psi \in \br_\alpha}} \left( \mathord{<_{\beta_{\psi}}} \cup
      (\{ x\in N_\alpha \mid \psi \Rightarrow \varphi_\alpha(x) \} \times N_{\beta_\psi})
   \right)
  \\
  \lambda(x) &\triangleq \left\{
  \arraycolsep=2pt
    \begin{array}{ll}
      \lambda_\alpha(x) & \text{if} ~ x \in N_\alpha
      \\
      \lambda_{\beta_\psi}(x) & \text{if} ~ x \in N_{\beta_\psi}
    \end{array}
  \right.
  &
  \varphi(x) &\triangleq \left\{
  \arraycolsep=2pt
    \begin{array}{ll}
      \varphi_\alpha(x) & \text{if} ~ x \in N_\alpha
      \\
      \varphi_{\beta_\psi}(x)\land \psi & \text{if} ~ x \in N_{\beta_\psi}
    \end{array}
  \right.
\end{align*}
(where, again, $\psi\land\tru=\tru\land\psi=\psi$).
