\section{Preliminaries and Omitted Definitions}
\label{app:prelim}

\subsection{Order Theory and Domain Theory}
\label{app:ord}

\begin{definition}[Poset]
A partially ordered set, or {\em poset}, is a set equipped with a partial order: that is, a pair $\tuple{X,\le}$ consisting of a set $X$ and an order relation $\mathord{\le} \subseteq X\times X$ which is reflexive, transitive and antisymmetric. When the order is instead irreflexive (\ie $x \not< x$ for all $x\in X$), the poset is called {\em strict} and the order relation is denoted by $<$.
\end{definition}

Given a strict poset $\tuple{X, <}$ and $x \in X$, we define the upward and downward closures:
\begin{align*}
  \succplus x &\triangleq \{ y \in X  \mid  x < y \}
  &
   \predplus x &\triangleq \{ y \in X  \mid  y < x \};
  \end{align*}
and  its set of immediate successors and predecessors as
  \[
   \succ(x) \triangleq \{ y \in \succplus x\ \mid\ \not\exists z. (x < z < y) \} \qquad\qquad
    \pred(x) \triangleq \{ y \in \predplus x\ \mid\ \not\exists z. (y < z < x) \}
      \]
      All the above operations can easily be extended to sets of elements, \eg $\succplus X \triangleq \bigcup_{x\in X} \succplus x$, for any set $X$.
  The set of minimal and maximal nodes of a poset is given by:
        \begin{align*}
  \max \triangleq \{ x \in X \mid \succ(x) = \emptyset \} 
   \qquad
 \min  \triangleq \{ x \in X \mid \pred(x) = \emptyset \}
\end{align*}
To define our new structures we need a few more definitions on posets that will play a role in proving the existence of fixed points, essential for giving a semantics to unbounded loops. First, we recall the notion of downward closed sets.

\begin{definition}[Downward Closure]
Given a poset $\tuple{X, <}$, a set $Y \subseteq X$ is downward closed, written $Y \dwclosed X$, iff for all $y\in Y$ it holds that $\predplus y\, \subseteq Y$.
\end{definition}

Second, we need a notion of a poset being finitely preceded. 

\begin{definition}[Finitely Preceded]
A poset $\tuple{X, <}$ is \emph{finitely preceded} if there are finitely many elements smaller than each element; that is: $|\predplus{x}| < \infty$, for all $x\in X$.
\end{definition}

Third, we define the level of elements in the poset.

\begin{definition}[Level \cite{meyer1989pomset}]
  Given a finitely preceded poset $\tuple{X, <}$, define $\lev \colon X \to \mathbb N$:
  \[
  \lev(x) \triangleq
\sup \left\{ n \ \middle| \!\!
    \begin{array}{l}
    \exists x_0, \ldots, x_n \in X.\ x_0\in\min\ \wedge\  x_n = x \ \wedge\ \forall i < n.\ x_{i+1} \in \succ(x_i) \!\!\!
    \end{array}
    \right\}
  \]
%  Note that $\lev \colon X\to \mathbb{N}$ for finitely preceded posets.
  We also define its inverse $\lev^{-1} \colon \mathbb N \to \mathcal{P}(X)$:
  \[
    \lev^{-1}(n) \triangleq \{ x \in X \mid \lev(x) = n \}
  \]
\end{definition}

\begin{definition}\label{def:formulae}
The satisfaction relation $\mathord{\vDash} \subseteq (\Nodes \to \mathbb B) \times \Form$ for Boolean formulae is given below:
\begin{align*}
  v &\vDash \tru && \text{always}
  \\
  v &\vDash \fls && \text{never}
  \\
  v &\vDash \psi_1 \land\psi_2 && \text{iff} \quad v\vDash \psi_1 ~\text{and}~ v\vDash \psi_2
  \\
  v &\vDash \psi_1 \lor\psi_2 && \text{iff} \quad v\vDash \psi_1 ~\text{or}~ v\vDash \psi_2
  \\
  v &\vDash \lnot \psi && \text{iff} \quad v\not\vDash \psi
  \\
  v &\vDash x && \text{iff} \quad v(x) = 1
\end{align*}
\end{definition}

\subsection{The Convex Powerdomain}
\label{app:convex}

We begin by providing the omitted definitions from \Cref{sec:convex-powerset}, regarding the \dcpo\ structure of the convex powerset. We start by defining the order on probability distributions. For any set $X$, let $X_\bot = X \cup \{\bot\}$ and the order over distributions $\mathord{\sqsubseteq_\D} \subseteq \D(X_\bot) \times \D(X_\bot)$ be defined as follows:
\[
  \mu \sqsubseteq_\D \nu
  \quad\text{iff}\quad
  \forall x\in X.\ \mu(x) \le \nu(x)
\]
Note that this means that $\mu(\bot) \ge \nu(\bot)$ if $\mu \sqsubseteq_\D \nu$, and that the bottom of the order is $\bot_\D = [ \bot \mapsto 1]$. A set of distributions $S \subseteq \D(X_\bot)$ is \emph{upward closed} if, for all $\mu \in S$, it holds that $\mu \sqsubseteq_\D \nu$ implies $\nu \in S$. In addition, $S$ is \emph{Cauchy closed} if it is closed in the product of Euclidean topologies \cite[Definition 5.4.3]{mciver2005abstraction}. Now, the convex powerset is defined as follows:
\[
  \C(X) \triangleq \set{ S \subseteq \D(X_\bot) \;\;\middle|\;\; \text{$S$ is nonempty, convex, upward closed, and Cauchy closed}  }
\]
Convex powersets are ordered via the Smyth order \cite{smyth1978power} $\mathord{\sqsubseteq_\C} \subseteq \C(X) \times \C(X)$, defined below:
\[
  S \sqsubseteq_\C T
  \quad\text{iff}\quad
  \forall \nu \in T.\ \
  \exists \mu \in S.\ \
  \mu \sqsubseteq_\D \nu
\]
Since the sets above are upward closed, the Smyth order collapses to reverse subset inclusion $S \sqsubseteq_\C T$ iff $S \supseteq T$. This makes the \emph{convex powerdomain} $\tuple{\C(X), \sqsubseteq_\C}$ a pointed \dcpo\ with suprema given by set intersection and bottom $\bot_\C = \D(X_\bot)$ being the set of all distributions, for the full proof refer to \cite{zilberstein2025demonic}.

