\begin{align*}
  \de{\skp}_\C\!(s) &\triangleq \eta(s)
  \\
  \de{C_1; C_2}_\C\!(s) &\triangleq \de{C_2}_\C^\dagger\left(\de{C_1}_\C(s)\right)
  \\
  \de{\iftf b{C_1}{C_2}}_\C\!(s) &\triangleq \left\{
%    \arraycolsep = 1pt
    \begin{array}{ll}
      \de{C_1}_\C\!(s) & \text{if}~ \de{b}_\test(s) = 1
      \\
      \de{C_2}_\C\!(s) & \text{if}~ \de{b}_\test(s) = 0
    \end{array}
  \right.
  \\
  \de{\whl bC}_\C\!(s) &\triangleq \mathsf{lfp}(\Psi_{\tuple{\de{C}_\C, b}})(s)
  \\
  \de{a}_\C\!(s) &\triangleq \de{a}_\act(s)
\end{align*}
\caption{Convex powerset semantics $\de{-}_\C \colon \cmd \to \mathcal{S} \to \C(\mathcal S)$ due to \cite{jifeng1997probabilistic,zilberstein2025demonic,mciver2005abstraction}, 
where $\Psi$ is defined in \Cref{lem:lin-props}.}
