\section{Preliminaries and Problem Definitions}\label{section:prelims}

\iflong\subparagraph*{Permutations.}\fi We define $[n]=\{1,\dots,n\}$. A permutation $\pi$ of a multiset $S=\{s_1,\dots,s_n\}$ is a bijection $\pi:[n]\mapsto S$. We sometimes treat $\pi$ as the list $(\pi(1),\pi(2),\dots,\pi(n))$. Further, we define $\text{pos}_\pi(s)=i$ if and only $\pi^{-1}(s)=i$.

\iflong\subparagraph*{Time series.}\fi An \emph{$\ell$-time series} $f$ is a function $f:[\ell]\to \mathbb{R}^+_0$. We refer to the elements of its image as \emph{data points}.
A set $F$ of $\ell$-time series, is \emph{balanced} if $\sum_{f\in F}f(i)=\sum_{f\in F}f(j)$ for all $i,j\in [\ell]$.

\iflong\subparagraph*{Strong NP-hardness.}\fi A computational problem is \emph{strongly \NP-hard} if it remains \NP-hard even if its numerical parameters are integers that are polynomial in the input size. 


\paragraph*{Problem Definitions}
In most problems discussed in this paper, we are given a set $F=\{f_1,\dots,f_n\}$ of $\ell$-time series. Given a permutation $\pi$ of $F$, $i\in \{0\}\cup [n]$, and $j\in [\ell-1]$, we define the \emph{wiggle} value $W^\pi_{i,j}=\sum_{k=1}^i(\pi(k)(j+1)-\pi(k)(j))$. 
This results in the following two problem variants of \emph{wiggle minimization for stacked area charts}, the first unweighted, and the second weighted by the time series data points - as is more common in the stacked area charts literature \cite{dibartolomeoThereMoreStreamgraphs2016,strungemathiesenAestheticsOrderingStacked2021,greffardVisualizingSetMultiple2015} (see also \cref{fig:stackedareachart}b). For both problems, $p$ is a positive integer corresponding to the exponent of the wiggle values. The second problem is equivalent to the minimization of \emph{flatness} in~\cite{strungemathiesenAestheticsOrderingStacked2021}. 
\begin{problem}[\pwigglemin] 
    Given a set $F=\{f_1,\dots,f_n\}$ of $\ell$-time series, find a permutation $\pi$ of $F$ such that $\sum_{i=1}^{n}\sum_{j=1}^{\ell-1}|W^\pi_{i,j}|^p$ is minimized.
\end{problem}
%
%
%
%


\begin{problem}[\wpwigglemin]
    Given a set $F=\{f_1,\dots,f_n\}$ of $\ell$-time series, find a permutation $\pi$ of $F$ such that 
    \begin{equation*}
        \sum_{i=1}^{n}\sum_{j=1}^{\ell-1}\frac{\pi(i)(j)+\pi(i)(j+1)+\pi(i+1)(j)+\pi(i+1)(j+1))}{4}|W^\pi_{i,j}|^p
    \end{equation*} is minimized. Above, $\pi(n+1)$ is the time series containing only zeroes.
\end{problem}
%
%
%
%
If $\ell=2$, then \onewigglemin\ is equivalent (see \cref{lemma:prefsumsumtowigglemin}) to the following fundamentally interesting problem, which we also study in this paper.

\begin{problem}[\prefsumsumprob]
    Given a multiset $S=\{s_1,\dots,s_n\}$ of real numbers, find a permutation $\pi$ of $S$ such that $\sum_{i=1}^n \left|\sum_{j=1}^{i}\pi(j)\right|$ is minimized.
\end{problem}
%
%
%
%
%
Given a solution $\pi$ of \prefsumsumprob, we define for $i=0,1,\dots,n$, $P^\pi_i=\sum_{j=1}^i\pi(j)$.

Next, we want to show relationships between the previously defined problems.
\begin{restatable}[\appsymb]{lemma}{lemmaprefsumsumtowigglemin}\label{lemma:prefsumsumtowigglemin}
    Given an instance $S=\{s_1,\dots,s_n\}$ of \prefsumsumprob, there exists an instance $F=\{f_1,\dots,f_n\}$ of \onewigglemin\ on two time points such that $S$ has a solution with value $x$ if and only if $F$ has a solution with value $x$. If $\sum_{s\in S}s=0$, then $F$ is balanced. Further, data point values in $F$ are bounded by a polynomial of the values in $S$.

    Conversely, for an instance $F$ of \onewigglemin\ on two time points, there exists an instance $S$ of \prefsumsumprob\ such that $S$ has a solution with value $x$ if and only if $F$ has a solution with value $x$.
\end{restatable}
\appendixproof{lemma:prefsumsumtowigglemin}{
\ifshort\lemmaprefsumsumtowigglemin*\fi
\begin{proof}
    Let $S=\{s_1,\dots,s_n\}$ be an instance of \prefsumsumprob. The instance $F=\{f_1,\dots,f_n\}$ of \onewigglemin\ is defined on two time points as follows. For $i\in [n]$, let
    \begin{itemize}
        \item $f_i(1)=0$ and $f_i(2)=s_i$ if $s_i\ge 0$, and
        \item $f_i(1)=-s_i$ and $f_i(2)=0$ otherwise.
    \end{itemize}
    The equivalence between the two instances is immediate since $f_i(2)-f_i(1)=s_i$.

    For the other direction, define $s_i=f_i(2)-f_i(1)$.
\end{proof}
}

\begin{restatable}[\appsymb]{lemma}{lemmawigglemintoweightedwigglemin}\label{lemma:wigglemintoweightedwigglemin}
    Let $p\ge 1$ be an integer.
    Given a balanced instance $F=\{f_1,\dots,f_n\}$ of \pwigglemin\ on $\ell$ time points, there is an instance $F'=\{f'_1,\dots,f'_n\}$ of \wpwigglemin\ on $4\ell+1$ time points and a constant $C$ such that $F$ has a solution with value $x$ if and only if $F'$ has a solution with value $Cx$. Further, the values of the data points in $F'$ are polynomially bounded w.r.t.\ the values of the data points in $F$.
\end{restatable}
\appendixproof{lemma:wigglemintoweightedwigglemin}{
    \ifshort\lemmawigglemintoweightedwigglemin*\fi
    \begin{proof}
    Let $F=\{f_1,\dots,f_n\}$ be a balanced instance of \pwigglemin\ on $\ell$ time points. We construct $F'=\{f'_1,\dots,f'_n\}$ as an instance of \wpwigglemin\ on $4\ell+1$ time points.
    Let $M=\max\{f_i(j)\mid i\in[n],j\in[\ell]\}$.
    We start by defining $f'_i(1)=M$ for all $i\in [n]$. Next, we define inductively for $j=1,\dots,\ell$:
    \begin{itemize}
        \item $f'_i(4j-2)=f'_{i}(4j-3)+(f_i(j+1)-f_i(j))$ for all $i\in [n]$,
        \item $f'_i(4j-1)=f'_{i}(4j-2)-(f_i(j+1)-f_i(j))$ for all $i\in [n]$,
        \item $f'_i(4j)=f'_{i}(4j-1)-(f_i(j+1)-f_i(j))$ for all $i\in [n]$, and
        \item $f'_i(4j+1)=f'_{i}(4j)+(f_i(j+1)-f_i(j))$ for all $i\in [n]$.
    \end{itemize}
    Notice that $f'_i(4j+1)=M$ for all $i\in [n]$ and that the average value of $f'_i(4j-2), f'_i(4j-1), f'_i(4j), f'_i(4j+1)$ is $M$.
    Now consider a permutation $\pi$ of $F$. Consider the permutation $\pi'$ of $F'$ defined such that $\text{pos}_{\pi}(f_i)=\text{pos}_{\pi'}(f'_i)$ for all $i\in [n]$.
    Notice that $|W^{\pi}_{i,j}|=|W^{\pi'}_{i,4j-3}|=|W^{\pi'}_{i,4j-2}|=|W^{\pi'}_{i,4j-1}|=|W^{\pi'}_{i,4j}|$. 
    Define the weighted wiggle $WW_{i,j}$ as
    \[WW_{i,j}=\frac{\pi'(i)(j)+\pi'(i)(j+1)+\pi'(i+1)(j)+\pi'(i+1)(j+1))}{4}|W^{\pi'}_{i,j}|^p.\]
    We have for $i\in [n]$ and $j\in [\ell-1]$ that
    \[WW_{i,4j-3}+WW_{i,4j-2}+WW_{i,4j-1}+WW_{i,4j}=4M|W^\pi_{i,j}|.\]
    It follows that $\pi$ is a solution of \pwigglemin\ with value $x$ if and only if $\pi'$ is a solution of \wpwigglemin\ with value $4Mx$. Note that $F$ has to be balanced for this, as otherwise the wiggle values $|W^{\pi'}_{n,j}|$ for $j\in [4\ell]$ would only be weighted by $M/2$ and not~$M$.
\end{proof}
}

A trivial algorithm for the mentioned problems would need to go over all permutations, and thus need $\mathcal{O}(n!|I|)$ time when $|I|$ is the instance size. A simple improvement is to use dynamic programming by computing the optimal solution for each subset of time series (or elements in $S$), leading to an algorithm needing time $\mathcal{O}(2^{n}|I|^c)$ for some constant $c$. In the following sections, we want to find out whether polynomial time exact, or approximation algorithms for the problems are likely.

\section{Complexity of \texorpdfstring{\prefsumsumprob\ and \probname{(Weighted)-}\onewigglemin}{}}\label{section:prefsumsum}
In this section, we consider the problem \prefsumsumprob. We will show several complexity results, some of which will imply results for \onewigglemin\ and \wonewigglemin. \iflong We start with a proof of strong \NP-hardness.\fi
\subsection{Strong NP-hardness}
Most of this section is devoted to showing strong \NP-hardness of \prefsumsumprob. The proof idea is to reduce instances of a known \NP-hard problem to instances $S$ of \prefsumsumprob, such that $S$ has a solution value which is equal to a lower bound if and only if the instance which we reduced from is a yes instance. This lower bound is stated next.
\begin{lemma}\label{lemma:lowerbound}
    A lower bound for the objective function of \prefsumsumprob\ is $\sum_{s\in S}|s|/2$.
\end{lemma}
\begin{proof}
    Let $\pi$ be some solution of \prefsumsumprob.
    It is easy to see that for $i=1,\dots,n$,
    \begin{align*}
        |P^\pi_i|+|P^\pi_{i-1}|\ge |\pi(i)|.
    \end{align*}
    Thus,
    \begin{align*}
        2\sum_{i=0}^n |P^\pi_i|&\ge |P^\pi_0|+|P^\pi_n|+2\sum_{i=1}^{n-1} |P^\pi_i|\ge \sum_{i=1}^n |s_i|\qedhere
    \end{align*}
\end{proof} 
We call a solution $\pi$ achieving this bound \emph{bound-achieving}.
The next lemma states a sufficient condition that implies that the solution value exceeds the previously stated lower bound.
\begin{lemma}\label{lemma:abovelowerbound}
    Let $\pi$ be a solution of \prefsumsumprob\ and $\sum_{i=1}^ns_i=0$. 
    There exists $j\in [n]$ such that $|P^\pi_j|+|P^\pi_{j-1}|>|\pi(j)|$ if and only if $\sum_{i=1}^n|P^\pi_i|> \sum_{i=0}^n|s_i|/2$.
\end{lemma}
\begin{proof} The backwards direction is clear. For the forward direction, we have
    \begin{equation*}
        2\sum_{i=0}^n |P^\pi_i|=2\sum_{i=1}^{n-1}|P^\pi_i|>\sum_{i=1}^n |s_i|. \qedhere
    \end{equation*}
\end{proof}
Additionally, in our reduction, we will consider instances $S$ of \prefsumsumprob\ that have specific properties. These properties are described below.
\begin{enumerate}
\renewcommand{\labelenumi}{\textbf{\theenumi}}
        \renewcommand{\theenumi}{\mylipgray{(IP\arabic{enumi})}}
    \item $\sum_{i=1}^ns_i=0$.\label{enum:prop1}
    \item $n\equiv 0 \pmod{3}$, i.e., $n$ is a multiple of $3$.\label{enum:prop2}
    \item $S$ has exactly $\frac{2n}{3}$ positive elements and $\frac{n}{3}$ negative elements.\label{enum:prop3}
\end{enumerate}
Hence, $S$ also has no elements equal to zero.
We call an instance that satisfies \ref{enum:prop1}-\ref{enum:prop3} \emph{nice}, and observe the following properties that will be useful for the reduction.
\begin{lemma}\label{lemma:nobothpositive}
    Let $\pi$ be a bound-achieving solution of a nice instance $S$.
    At least one of $\pi(1), \pi(2)$ is negative and at least one of $\pi(n-1),\pi(n)$ is negative.
\end{lemma}
\begin{proof}
    If both $\pi(1), \pi(2)$ are positive, then $\pi(2)<|P^\pi_1|+|P^\pi_2|$. \cref{lemma:abovelowerbound} gives us a contradiction, as we assumed that $\pi$ is bound-achieving.

    If both $\pi(n-1),\pi(n)$ are positive, then we have, as $P^\pi_n=0$, that $P^\pi_{n-1}=-\pi(n)$ and $P^\pi_{n-2}=-(\pi(n)+\pi(n-1))$. It follows that $|P^\pi_{n-2}|+|P^\pi_{n-1}|>|\pi(n-1)|$, a contradiction.
\end{proof}

\begin{lemma}\label{lemma:2conspi0}
    Let $\pi$ be a bound-achieving solution of a nice instance $S$. If for $i\in [n-1]$, $\pi(i)$ and $\pi(i+1)$ are both positive or both negative, then $P^\pi_i=0$.
\end{lemma}
\begin{proof}
    If $\pi(i)$ and $\pi(i+1)$ are both positive, and $P^\pi_i\ne 0$ then we have two cases.
    \begin{itemize}
        \item If $P^\pi_i>0$ then $|P^\pi_i|+|P^\pi_{i+1}|>\pi(i+1)$, a contradiction.
        \item If $P^\pi_i<0$ then $|P^\pi_{i-1}|+|P^\pi_i|>\pi(i)$, a contraction.
    \end{itemize}
    When both $\pi(i)$ and $\pi(i+1)$, are negative, the proof works the same.
\end{proof}

The following is a direct consequence of the last lemma.
\begin{corollary}\label{lemma:threeconsecutive}
    Let $\pi$ be a bound-achieving solution of a nice instance $S$. There exists no $i\in [n-2]$ such that $\pi(i),\pi(i+1),\pi(i+2)$ are all negative or all positive. 
\end{corollary}
With these lemmas out of the way, we can show that $\pi$ has a unique structure with regard to the signs of its elements.
\begin{lemma}\label{lemma:signproperties}
    Let $\pi$ be a bound-achieving solution of a nice instance $S$. Then, for $i\in [n]$,
    \begin{itemize}
        \item $\pi(i)$ is positive if and only if $i\equiv 0\pmod{3}$ or $i\equiv 1\pmod{3}$,
        \item $\pi(i)$ is negative if and only if $i\equiv 2\pmod{3}$, and
        \item if $i\equiv 0\pmod{3}$, then $P^\pi_i=0$.
    \end{itemize}
\end{lemma}
\begin{proof}
    We show the claim by induction on $i$. For the base case, $i=1$, assume for a contradiction that $\pi(1)$ is negative. Together with  \cref{lemma:nobothpositive} and the pigeonhole principle, it follows that there must be three consecutive positive elements, a contradiction to \cref{lemma:threeconsecutive}.

    For the induction step $i>1$, we have the following cases.
    \begin{itemize}
        \item If $i\equiv 0\pmod{3}$ then $\pi(i)$ must be positive; otherwise, for the remaining $n-i$ following elements, we have $(n-i)/3-1$ negative elements and $2(n-i)/3+1$ positive elements. By the pigeonhole principle, there are three consecutive positive elements, a contradiction. Further $P^\pi_i=0$ must hold: For $i=n$ it holds trivially. Otherwise, if $P^\pi_i$ was not zero, then $\pi(i+1)$ must be negative by \cref{lemma:2conspi0}. For there to be no three consecutive positive elements in the remaining array, $\pi(n-1)$ and $\pi(n)$ must be positive, a contradiction.
        \item If $i\equiv 1\pmod{3}$ then $\pi(i)$ is positive by the same argumentation as in the base case.
        \item If $i\equiv 2\pmod{3}$ then $\pi(i)$ is clearly negative; otherwise, as $P^\pi_{i-1}$ is positive, $|P^\pi_i|+|P^\pi_{i+1}|>|\pi(i)|$ would hold; a contradiction (see \cref{lemma:abovelowerbound}). \qedhere
    \end{itemize}
\end{proof}

With this groundwork, we are able to show the following result. 
\begin{theorem}
    The decision variant of \prefsumsumprob\ is strongly \NP-complete.
\end{theorem}
\begin{proof}
    \NP-membership is obvious, thus we continue with \NP-hardness.
    We reduce from the strongly \NP-hard problem \textsc{Numerical 3-Dimensional Matching} \cite{DBLP:journals/scheduling/YuHL04}. The problem input consists of three multisets $X,Y$, and $Z$, each containing $k$ integers.
    Let $b=(\sum_{e\in X\cup Y\cup Z}e)/k$. The problem is to decide whether there exists a subset $M$ of $X\times Y\times Z$ such that
    \begin{enumerate}
        \item each element from $X$, $Y$, and $Z$ appears in exactly one triple, and
        \item $x+y+z=b$ holds for each triple $(x,y,z)\in M$.
    \end{enumerate}
    We can assume that each element from $X\cup Y\cup Z$ is positive (otherwise add to all elements $-\alpha+1$, where $\alpha=\min X\cup Y\cup Z$ and obtain an equivalent instance with regard to the solution). We also assume that each element from $X,Y$, and $Z$ is smaller than $b$.
    Now define the multisets $X'=\{x\mid x\in X\}$, $Y'=\{y+2b\mid y\in Y\}$, and $Z'=\{z-3b\mid z\in Z\}$. Let $n=|X'\cup Y'\cup Z'|$. Notice that $\sum_{e\in X'\cup Y'\cup Z'}e=0$, and $X',Y'$ and $Z'$ are pairwise disjoint.
    We now define the instance $S$ of \prefsumsumprob\ as $S=X'\cup Y'\cup Z'$. Notice that $S$ is a nice instance satisfying \ref{enum:prop1}-\ref{enum:prop3}.
    %

    We claim that $(X,Y,Z)$ is a yes-instance of \textsc{Numerical 3-Dimensional Matching} if and only if there exists a solution $\pi$ of $S$ that is bound-achieving. We prove both directions.

    ``$\Rightarrow$'': Let $M$ be a subset of $X\times Y\times Z$ constituting a solution to the instance of \textsc{Numerical 3-Dimensional Matching}. We constructively define $\pi$ by going through the triples $(x,y,z)$ in $M$ in any order.
    Let $(x,y,z)$ be the $i$th triple.
    We define $\pi(3i-2)=x, \pi(3i-1)=z-3b$, and $\pi(3i)=y+2b$.
    By the definition of $X',Y'$, and $Z'$ such a permutation always exists.
    Now notice for $j=0,1,\dots, n$ that $P^\pi_j$ is
    \begin{itemize}
        \item $0$, if and only if $j\equiv 0\pmod{3}$,
        \item positive if and only if $j\equiv 1\pmod{3}$, and
        \item negative if and only if $j\equiv 2\pmod{3}$.
    \end{itemize}
    Thus, we have $|P^\pi_j|+|P^\pi_{j-1}|=|\pi(j)|$ for all $j\in [n]$. It follows that $\sum_{j=1}^n |P^\pi_j|=\sum_{s\in S} |s|/2$.

    ``$\Leftarrow$'': Assume that $\pi$ is bound-achieving. We construct $M$, starting with $M=\emptyset$.
    Because $S$ is nice, we have that \cref{lemma:signproperties} holds for $\pi$. For each $i\in [k]$ we have the following. Let $u:=\pi(i-2),v:=\pi(i-1)$, and $w:=\pi(i)$. Because of \cref{lemma:signproperties} we have that $u+v+w=0$, $v$ is negative, and $u$ and $w$ are positive. Hence, $v\in Z'$ holds. Now we claim that exactly one of $u$ and $w$ is from $X'$ and exactly one is from $Y'$. Indeed, if both $u$ and $w$ were from $X'$, then $u+w<2b<|v|$ and $u+v+w=0$ is impossible. Similarly, if both $u$ and $w$ were from $Y'$, then $u+w>4b>|v|$ and $u+v+w=0$ is impossible.
    Thus, w.l.o.g.\ assume that $u\in X'$ and $w\in Y'$. Add to $M$ the triple $(u,w-2b,v+3b)$.
    It is easy to verify that after adding this triple for each $i\in [k]$, $M$ verifies that $(X,Y,Z)$ is a yes-instance of \textsc{Numerical 3-Dimensional Matching}.
\end{proof}

\cref{lemma:prefsumsumtowigglemin} and \cref{lemma:wigglemintoweightedwigglemin} imply the following corollary. 
\begin{corollary}
    The decision variants of \onewigglemin\ and \wonewigglemin\ are strongly \NP-complete, even for a constant number of time points.
\end{corollary}

\subsection{Restricted instances of \texorpdfstring{\prefsumsumprob}{}}
We further ask for which types of instances \prefsumsumprob\ becomes tractable. In particular, we want to know whether restricting the number of negative (or positive) elements of $S$ has an effect on the computational complexity of \prefsumsumprob. Indeed, if $S$ only contains positive or only negative elements, then an optimal ordering $\pi$ will simply order the elements of $S$ by their absolute value.  But what if $S$ contains exactly one positive or exactly one negative element? We obtain the following peculiar results, which state that the sum of $S$ has an effect on the complexity of \prefsumsumprob\ in this case.
\begin{restatable}[\appsymb]{theorem}{theoremprefsumsumpoly}\label{theorem:prefsumsumpoly}
    \prefsumsumprob\ can be solved in time $\mathcal{O}(n\log n)$ if $S$ contains exactly one negative (positive) element, and $\sum_{i=1}^ns_i=0$.
\end{restatable}
\begin{restatable}[\appsymb]{theorem}{theooremprefsumsumweaknphard}\label{theoorem:prefsumsumweaknphard}
    The decision variant of \prefsumsumprob\ is \NP-complete, even if $S$ contains exactly one negative (positive) element.
\end{restatable}
We dedicate the rest of the section to show both results, starting with \cref{theorem:prefsumsumpoly}.

\ifshort
\begin{proof}[Proof sketch of \cref{theorem:prefsumsumpoly}]
    We show the result for $S$ containing a single negative element $x$, the result for a single positive element is shown equivalently.
    Now consider some permutation $\pi$ of $S$, and let $k=\text{pos}_\pi(x)$. We observe that the objective value can be split into absolute prefix sums before and after position $k$ as follows.
    \begin{align*}
        \sum_{i=1}^n|\sum_{j=1}^{i}\pi(j)|&=\sum_{i=1}^{k-1}\sum_{j=1}^i\pi(j)+\sum_{i=1}^{n-k}\sum_{j=1}^i\pi(n-j+1)\\
        &=\sum_{i=1}^{k-1}\pi(i)\cdot (k-i)+\sum_{i=1}^{n-k}\pi(n-i+1)\cdot (n-k-i+1).
    \end{align*}
     Thus, we obtain a weighted sum of the positive elements. The coefficient of an element depends only on its position in relation to the position of the negative element.
    This leads to a simple algorithm, which is also given as pseudocode in the long version of this paper: The permutation is chosen such that the negative element is in the middle. The smallest positive elements are placed at positions $1$ and $n$, the next smallest at positions $2$ and $n-1$, etc.
\end{proof}
\fi
\appendixproof{theorem:prefsumsumpoly}{
\ifshort\theoremprefsumsumpoly*\fi
\begin{proof}
\begin{algorithm}[htb]
\caption{Exact algorithm for \prefsumsumprob\ when $S$ contains exactly one negative element and $\sum_{s\in S}s=0$.}\label{alg:easyalg}
    \KwIn{A multiset $S$ of integers, which contains exactly one negative element.}
    \KwOut{A permutation $\pi$ of $S$.}
    $\pi(\lfloor \frac{n}{2} \rfloor)\gets \min S$\;
    $B\gets S\setminus \min S$\;
    $i\gets 0$\;
    \ForEach{$s\in B$ in non-decreasing order}{
        \uIf{$i \equiv 1\pmod{2}$}{
            $\pi(\frac{i+1}{2})\gets s$\;
        }
        \Else{
            $\pi(n-\frac{i}{2})\gets s$\;
        }
        $i\gets i+1$\;        
    }
    \Return $\pi$;
\end{algorithm}
    We show the result for $S$ containing a single negative element $x$, the result for a single positive element is shown equivalently.
    Now consider some permutation $\pi$ of $S$, and let $k=\text{pos}_\pi(x)$. We observe that the objective value can be split into absolute prefix sums before and after position $k$ as follows.
    \begin{align*}
        \sum_{i=1}^n|\sum_{j=1}^{i}\pi(j)|&=\sum_{i=1}^{k-1}\sum_{j=1}^i\pi(j)+\sum_{i=1}^{n-k}\sum_{j=1}^i\pi(n-j+1)\\
        &=\sum_{i=1}^{k-1}\pi(i)\cdot (k-i)+\sum_{i=1}^{n-k}\pi(n-i+1)\cdot (n-k-i+1).
    \end{align*}
    Thus, we obtain a weighted sum of the positive elements. The coefficient of an element depends only on its position in relation to the position of the negative element. Moreover, at most two elements can have coefficient one, at most two can have two, and so on. Thus, it is beneficial to have the two largest positive elements at positions $k-1$ and $k+1$, the next largest at position $k-2$ and $k+2$, etc.
    This leads to the simple \cref{alg:easyalg}. The permutation $\pi$ is chosen such that the negative element is in the middle. Then the smallest positive elements are placed at positions $1$ and $n$, the next smallest at positions $2$ and $n-1$, etc. This is optimal because in this way the largest positive elements are only counted towards the objective once, the next-largest two elements twice, and so on. Putting the negative element in the middle is optimal because it results in the smallest coefficients for the positive elements. The runtime is upper-bounded by sorting the numbers in $S$.
\end{proof}
}

To show \cref{theoorem:prefsumsumweaknphard}, we reduce from the following problem.

